window.PRF192_COURSE = {"name":"Lập trình C căn bản","code":"PRF192","subtitle":"21 bài học theo 5 module · Tư duy thuật toán · C11 · Thực hành và kiểm thử","version":"v3.0","updated":"2026-11-20","lessons":[{"id":"slot-00","number":0,"title":"Định hướng học phần và cách học lập trình C","unit":"Nhập môn","source":"Slot_00_Course Introduction.pptx, slide 1–17","lead":"Từ nhu cầu giải quyết bài toán bằng máy tính đến phương pháp tự học, đạo đức học thuật và môi trường thực hành OnlineGDB.","objectives":["Giải thích được vai trò học phần PRF192 trong tư duy giải quyết vấn đề.","Thiết lập được quy trình làm bài và kiểm thử trên OnlineGDB.","Nhận diện được quy định học thuật và phương pháp tự học phù hợp."],"sections":[{"title":"Mục đích học phần","text":"Lập trình là quá trình xây dựng các chỉ dẫn để máy tính xử lý dữ liệu và tạo kết quả. Học phần phát triển năng lực phân tích yêu cầu, thiết kế thuật toán, lập trình C, kiểm thử và đánh giá chất lượng lời giải. Cú pháp chỉ là một phần trong chu trình này.","bullets":[]},{"title":"Phương pháp học theo chu trình","text":"Mỗi nhiệm vụ nên triển khai theo sáu thao tác lặp: đọc yêu cầu; xác định đầu vào, đầu ra; thiết kế thuật toán; viết mã; kiểm tra bằng dữ liệu mẫu và dữ liệu biên; rút kinh nghiệm. Không nên chỉ học thuộc mã nguồn hoặc xem một lần chạy đúng là đủ.","bullets":["Dự đoán kết quả trước khi nhấn Run.","Thử ít nhất một trường hợp thông thường, một trường hợp biên và một trường hợp sai dữ liệu.","Diễn giải được chương trình bằng lời của mình."]},{"title":"Thực hành trên OnlineGDB","text":"Truy cập trình biên dịch C trực tuyến, giữ chế độ Language: C, xóa mã mặc định và dán chương trình được cung cấp. Nhấn Run để biên dịch và chạy. Khi chương trình yêu cầu nhập, cung cấp dữ liệu qua console hoặc ô Standard Input tùy chế độ. Có thể sử dụng Debug để theo dõi biến và lệnh.","bullets":[]},{"title":"Đạo đức học thuật và đánh giá","text":"Bài làm phải thể hiện năng lực tự lập trình và kiểm thử. Có thể tham khảo sách, thảo luận phương pháp, nhưng cần ghi nguồn khi sử dụng ý tưởng hoặc mã của người khác. Quy định chuyên cần, tỷ trọng điểm và hình thức thi phải tuân theo đề cương của lớp đang học, không suy trực tiếp từ slide tham khảo của cơ sở khác.","bullets":[]}],"example":{"title":"Chương trình đầu tiên chạy trên OnlineGDB","code":"#include <stdio.h>\nint main(void) {\n    puts(\"Chao mung den voi hoc phan C!\");\n    return 0;\n}\n","output":"Chao mung den voi hoc phan C!","stdin":"","why":"puts xuất một chuỗi và thêm ký tự xuống dòng. Đây là bước kiểm tra môi trường, chưa đòi hỏi kiến thức về biến.","tests":[],"trace":["Bộ tiền xử lý tìm khai báo puts trong stdio.h.","main gọi puts một lần để xuất thông báo rồi trả về trạng thái 0."]},"mistakes":["Không thay đổi chế độ ngôn ngữ C khi dán mã.","Không cung cấp dữ liệu đầu vào cho chương trình không có lệnh nhập."],"exercises":[{"name":"Làm quen OnlineGDB","task":"Chạy mã mẫu, đổi lời chào thành tên học phần, quan sát đầu ra.","hint":"Chỉ sửa chuỗi trong dấu ngoặc kép.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Quy trình 6 bước","task":"Viết bảng Input–Process–Output cho bài toán tính tổng hai số nguyên.","hint":"Chưa cần viết mã C; tập trung cách phân tích.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Lập bảng kiểm gồm: tên tệp .c, đầu vào, đầu ra kỳ vọng, kết quả chạy và cách sửa nếu không khớp.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Đâu là trình tự hợp lý khi bắt đầu bài toán lập trình?","choices":["Chạy chương trình trước khi biên dịch","Phân tích đầu vào–đầu ra trước khi viết mã","Viết mã rồi đoán yêu cầu","Chỉ sao chép chương trình mẫu"],"answer":1,"explain":"Cần hiểu bài toán trước, sau đó mới thiết kế và hiện thực.","rationales":["Mã nguồn C phải được biên dịch hoặc xử lý phù hợp trước khi chạy.","Cần hiểu bài toán trước, sau đó mới thiết kế và hiện thực.","Viết mã trước khi hiểu yêu cầu dễ dẫn tới lời giải sai.","Sao chép chỉ tái tạo mã, không chứng minh phân tích được bài toán."]},{"q":"Khi một chương trình cho đúng một bộ dữ liệu, kết luận nào phù hợp?","choices":["Mới xác nhận được một trường hợp","Không cần kiểm thử tiếp","Đã chứng minh đúng với mọi đầu vào","Không còn lỗi logic"],"answer":0,"explain":"Một ca thử không chứng minh tính đúng đắn trên toàn miền dữ liệu.","rationales":["Một ca thử không chứng minh tính đúng đắn trên toàn miền dữ liệu.","Vẫn phải kiểm thử biên, giá trị sai và các tình huống khác.","Một dữ liệu không bao phủ các trường hợp khác.","Lỗi logic có thể chỉ xuất hiện với đầu vào khác."]},{"q":"Một lần chạy cho kết quả đúng có đủ chứng minh chương trình đúng với mọi đầu vào không?","choices":["Có; nếu không có cảnh báo thì chắc chắn đúng.","Có; trình biên dịch đã kiểm tra thuật toán.","Không; vì C luôn không thể kiểm thử.","Không; cần thêm các ca thông thường, biên và sai theo đặc tả."],"answer":3,"explain":"Một trường hợp kiểm thử chỉ cho bằng chứng trên trường hợp đó.","rationales":["Không phù hợp: Có; nếu không có cảnh báo thì chắc chắn đúng. Phát biểu đúng: Một trường hợp kiểm thử chỉ cho bằng chứng trên trường hợp đó.","Không phù hợp: Có; trình biên dịch đã kiểm tra thuật toán. Phát biểu đúng: Một trường hợp kiểm thử chỉ cho bằng chứng trên trường hợp đó.","Không phù hợp: Không; vì C luôn không thể kiểm thử. Phát biểu đúng: Một trường hợp kiểm thử chỉ cho bằng chứng trên trường hợp đó.","Một trường hợp kiểm thử chỉ cho bằng chứng trên trường hợp đó."]},{"q":"Trước khi dán mã lên OnlineGDB, cần chọn ngôn ngữ nào cho học phần?","choices":["Java vì chạy trực tuyến.","HTML vì website dùng HTML.","C.","C++ vì trình dịch nào cũng cho kết quả tương tự."],"answer":2,"explain":"Chương trình học là C; C++ có những quy tắc khác.","rationales":["Không phù hợp: Java vì chạy trực tuyến. Phát biểu đúng: Chương trình học là C; C++ có những quy tắc khác.","Không phù hợp: HTML vì website dùng HTML. Phát biểu đúng: Chương trình học là C; C++ có những quy tắc khác.","Chương trình học là C; C++ có những quy tắc khác.","Không phù hợp: C++ vì trình dịch nào cũng cho kết quả tương tự. Phát biểu đúng: Chương trình học là C; C++ có những quy tắc khác."]},{"q":"Một báo cáo bài tập tốt tối thiểu cần bằng chứng gì?","choices":["Chỉ tên sinh viên.","Mã nguồn, dữ liệu kiểm thử, đầu ra dự kiến và đầu ra thực tế.","Chỉ ảnh màn hình trang chủ.","Chỉ thông báo Build succeeded."],"answer":1,"explain":"Bằng chứng phải cho phép tái hiện được kết quả.","rationales":["Không phù hợp: Chỉ tên sinh viên. Phát biểu đúng: Bằng chứng phải cho phép tái hiện được kết quả.","Bằng chứng phải cho phép tái hiện được kết quả.","Không phù hợp: Chỉ ảnh màn hình trang chủ. Phát biểu đúng: Bằng chứng phải cho phép tái hiện được kết quả.","Không phù hợp: Chỉ thông báo Build succeeded. Phát biểu đúng: Bằng chứng phải cho phép tái hiện được kết quả."]}],"summary":["Mục đích học phần","Phương pháp học theo chu trình","Thực hành trên OnlineGDB","Đạo đức học thuật và đánh giá"],"minutes":45,"syntax":[{"label":"Khung tối thiểu của chương trình C","code":"#include <stdio.h>\nint main(void) {\n    puts(\"Xin chao!\");\n    return 0;\n}\n","meaning":"Chương trình bắt đầu bằng hàm main; puts viết một dòng văn bản và tự thêm ký tự xuống dòng.","watch":"Mẫu này là chương trình C hoàn chỉnh, không phải cú pháp của một câu lệnh riêng lẻ."}],"flow":{"type":"sequence","caption":"Quy trình tự học và kiểm thử một chương trình","steps":["Đọc đề, xác định đầu vào/đầu ra","Thiết kế lời giải bằng lời","Viết mã C trên OnlineGDB","Dự đoán và chạy thử","So sánh, sửa lỗi, lưu bài"]},"worked":{"title":"Bài mẫu: kiểm tra đầu ra trên OnlineGDB","problem":"Viết chương trình in hai dòng, mỗi dòng một thông báo, và kết thúc thành công.","steps":["Chọn thư viện stdio.h để sử dụng puts.","Viết hàm main(void); lần lượt gọi puts hai lần.","Biên dịch, chạy và đối chiếu chính xác hai dòng."],"code":"#include <stdio.h>\nint main(void) {\n    puts(\"Buoi hoc C dau tien\");\n    puts(\"Kiem tra: thanh cong\");\n    return 0;\n}\n","output":"Buoi hoc C dau tien\nKiem tra: thanh cong","stdin":"","analysis":["puts viết chuỗi rồi xuống dòng, vì vậy hai lời gọi tạo hai dòng.","return 0 trả trạng thái thành công cho môi trường chạy."],"tests":["Đổi chuỗi ở dòng 1 và quan sát dòng 2 giữ nguyên."]},"deep_dive":{"context":"Trước khi viết mã, sinh viên cần giải thích được ba điều: chương trình nhận gì, phải tạo ra gì và bằng chứng nào cho thấy kết quả đúng. Học với OnlineGDB không thay thế nhiệm vụ tự kiểm tra và lưu mã nguồn.","contrast":[["Bước biên dịch","Kiểm tra mã C có tuân thủ ngôn ngữ và liên kết thành công hay không."],["Bước thực thi","Theo dõi chương trình chạy với một bộ dữ liệu cụ thể."],["Bước kiểm thử","So sánh đầu ra thực tế với kết quả dự kiến trên nhiều ca."]],"pitfall":"Không coi “Run không báo lỗi” là chứng minh chương trình đúng. Nộp mã cùng dữ liệu thử và kết quả đối chiếu.","challenge":"Lập bảng kiểm gồm: tên tệp .c, đầu vào, đầu ra kỳ vọng, kết quả chạy và cách sửa nếu không khớp."},"lab_examples":[{"title":"Khởi tạo môi trường và đọc kết quả chuẩn","purpose":"Dùng puts để tạo ba dòng có thể đối chiếu chính xác, không dùng input.","code":"#include <stdio.h>\nint main(void) {\n    puts(\"CHUONG TRINH C\");\n    puts(\"Trang thai: san sang\");\n    puts(\"Buoc tiep: kiem thu\");\n    return 0;\n}\n","output":"CHUONG TRINH C\nTrang thai: san sang\nBuoc tiep: kiem thu","stdin":"","cases":[{"stdin":"","stdout":"CHUONG TRINH C\nTrang thai: san sang\nBuoc tiep: kiem thu","exit":0}],"followup":"Thay thứ tự hai lệnh puts và dự đoán thứ tự ba dòng xuất."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M1","module_title":"Tư duy thuật toán và tính toán cơ bản","design_case":{"title":"Quy trình phân tích yêu cầu giám sát nhiệt độ","problem":"Dữ liệu quan sát: 29 °C, 30 °C, 31 °C; ngưỡng cảnh báo giả định là trên 30 °C. Lập đặc tả và các bước kiểm thử, chưa yêu cầu viết bộ điều khiển thực.","input":["Ba giá trị nhiệt độ có đơn vị °C; ngưỡng 30 °C"],"process":["Xác định điều kiện T > 30 và lập bảng đúng/sai"],"output":["Bảng kết luận ứng với từng giá trị"],"assumptions":["Đơn vị thống nhất; chỉ minh họa thuật toán, không phải giới hạn an toàn thực tế"],"pseudocode":["Bắt đầu","Xác định đầu vào, đầu ra và điều kiện hợp lệ","Với mỗi giá trị T: đối chiếu T > 30","Ghi kết quả cảnh báo hoặc bình thường","Đối chiếu ba ca và kết thúc"],"tests":[{"input":"T=29 °C","expected":"Không cảnh báo","kind":"Thông thường"},{"input":"T=30 °C","expected":"Không cảnh báo","kind":"Đúng tại ranh giới"},{"input":"T=31 °C","expected":"Cảnh báo","kind":"Vượt ngưỡng"}],"reflection":"Vì sao cần kiểm thử đúng tại 30 °C, không chỉ 29 °C và 31 °C?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-01","number":1,"title":"Bài toán, thuật toán và chương trình C","unit":"Nhập môn","source":"Slot_01_Introduction to PFC.pptx, slide 2–45","lead":"Hình thành liên hệ dữ liệu → thuật toán → mã nguồn → biên dịch → thực thi; đọc cấu trúc chương trình C đầu tiên.","objectives":["Phân biệt dữ liệu, thông tin, bài toán, thuật toán và chương trình.","Mô tả vai trò CPU, bộ nhớ và các bước dịch chương trình C.","Viết và giải thích chương trình C sử dụng main và printf."],"sections":[{"title":"Dữ liệu và thông tin","text":"Dữ liệu là các giá trị, ký hiệu hoặc tín hiệu có thể lưu trữ, xử lý. Thông tin là ý nghĩa thu được khi đặt dữ liệu trong bối cảnh và phân tích phù hợp. Ví dụ số đo 28, 30, 32 °C là dữ liệu; kết luận nhiệt độ tăng qua ba lần đo là thông tin.","bullets":[]},{"title":"Bài toán và thuật toán","text":"Bài toán xác định đầu vào, yêu cầu xử lý và kết quả mong đợi. Thuật toán là dãy hữu hạn các bước xác định, có thể thực hiện để giải một lớp đầu vào. Trước khi viết C, hãy mô tả thuật toán bằng lời, mã giả hoặc lưu đồ.","bullets":["Input: dữ liệu đã biết hoặc cần nhập.","Process: phép tính và quy tắc chuyển trạng thái.","Output: kết quả và định dạng cần trả về."]},{"title":"Máy tính và lưu trữ nhị phân","text":"CPU thực thi lệnh; RAM giữ dữ liệu và chương trình đang hoạt động; thiết bị vào/ra trao đổi thông tin với bên ngoài. Bit nhận một trong hai giá trị 0, 1. Tám bit có 256 tổ hợp. Phân biệt 1 kB = 1000 byte với 1 KiB = 1024 byte.","bullets":[]},{"title":"Biên dịch và liên kết","text":"Quy trình công cụ C thông dụng gồm tiền xử lý, biên dịch, hợp dịch và liên kết; các công cụ có thể gộp nhiều công đoạn. Mã nguồn không tự chạy trực tiếp bằng CPU, cần biến đổi thành chương trình thực thi phù hợp. Lỗi cú pháp được phát hiện khi dịch, lỗi logic cần phân tích và thử nghiệm.","bullets":[]},{"title":"Cấu trúc chương trình","text":"Dòng #include <stdio.h> cung cấp khai báo printf. Hàm int main(void) là điểm bắt đầu theo môi trường thực thi C thông dụng. Cặp ngoặc nhọn bao thân hàm, mỗi lời gọi printf kết thúc bằng chấm phẩy; là ký tự xuống dòng. return 0 cho biết kết thúc thành công.","bullets":[]}],"example":{"title":"Xuất kết quả tính diện tích hình chữ nhật","code":"#include <stdio.h>\nint main(void) {\n    int dai = 5, rong = 3;\n    int dien_tich = dai * rong;\n    printf(\"Dien tich = %d m2\\n\", dien_tich);\n    return 0;\n}\n","output":"Dien tich = 15 m2","stdin":"","why":"Ví dụ hiện thực thuật toán tuần tự: gán dữ liệu, xử lý nhân hai số nguyên và xuất kết quả bằng định dạng %d.","tests":[],"trace":["Các biến dai và rong được khởi tạo trước khi tính.","Biểu thức dai * rong có giá trị 15 và printf thay %d bằng số nguyên đó."]},"mistakes":["Nhầm thuật toán với mã nguồn.","Thiếu dấu ; hoặc dùng Printf thay printf.","Hiểu nhầm một lần chạy đúng là đã chứng minh chương trình đúng."],"exercises":[{"name":"Bảng IPO","task":"Xác định Input, Process, Output cho bài toán tính chu vi hình chữ nhật, với chiều dài và rộng dương.","hint":"Chu vi = 2 × (chiều dài + chiều rộng).","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Chương trình xuất thông tin","task":"Viết chương trình in ba dòng: tên sinh viên, lớp và tên học phần, sử dụng printf.","hint":"Mỗi dòng dùng ; không dùng biến nếu chưa cần.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Thiết kế IPO, mã giả và bảng truy vết cho bài toán tính vận tốc trung bình từ quãng đường và thời gian khác 0.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Phát biểu đúng về thuật toán là gì?","choices":["Là cách giải bài toán gồm các bước hữu hạn rõ ràng","Là phần cứng CPU","Là một lệnh máy","Là chương trình bắt buộc viết bằng C"],"answer":0,"explain":"Thuật toán không phụ thuộc một ngôn ngữ cụ thể.","rationales":["Thuật toán không phụ thuộc một ngôn ngữ cụ thể.","CPU là phần cứng, không phải thuật toán.","Lệnh máy là một chỉ thị cho CPU, không mô tả toàn bộ phương pháp giải.","Thuật toán độc lập ngôn ngữ, không bắt buộc viết bằng C."]},{"q":"Vai trò của \\n trong chuỗi printf?","choices":["Kết thúc chương trình","Nhập dữ liệu","Bắt đầu chú thích","Xuống dòng"],"answer":3,"explain":"\\n là ký tự điều khiển xuống dòng.","rationales":["Kết thúc chương trình do luồng điều khiển, không phải ký tự xuống dòng.","\\n thuộc chuỗi xuất, không đọc đầu vào.","Chú thích bắt đầu bằng // hoặc /*, không phải \\n.","\\n là ký tự điều khiển xuống dòng."]},{"q":"Trong mô hình IPO, phép nhân hai cạnh hình chữ nhật thuộc phần nào?","choices":["Output.","Thiết bị lưu trữ.","Process.","Input."],"answer":2,"explain":"Đây là thao tác xử lý dữ liệu đầu vào.","rationales":["Không phù hợp: Output. Phát biểu đúng: Đây là thao tác xử lý dữ liệu đầu vào.","Không phù hợp: Thiết bị lưu trữ. Phát biểu đúng: Đây là thao tác xử lý dữ liệu đầu vào.","Đây là thao tác xử lý dữ liệu đầu vào.","Không phù hợp: Input. Phát biểu đúng: Đây là thao tác xử lý dữ liệu đầu vào."]},{"q":"Điều nào đúng về thuật toán trước khi viết C?","choices":["Phải luôn dùng vòng lặp.","Có thể mô tả bằng mã giả mà chưa phụ thuộc C.","Phải dịch thành .exe.","Phải có #include."],"answer":1,"explain":"Thuật toán là phương pháp giải độc lập ngôn ngữ hiện thực.","rationales":["Không phù hợp: Phải luôn dùng vòng lặp. Phát biểu đúng: Thuật toán là phương pháp giải độc lập ngôn ngữ hiện thực.","Thuật toán là phương pháp giải độc lập ngôn ngữ hiện thực.","Không phù hợp: Phải dịch thành .exe. Phát biểu đúng: Thuật toán là phương pháp giải độc lập ngôn ngữ hiện thực.","Không phù hợp: Phải có #include. Phát biểu đúng: Thuật toán là phương pháp giải độc lập ngôn ngữ hiện thực."]},{"q":"Khi mã nguồn C cần gọi hàm printf, khai báo thuộc tệp nào?","choices":["stdio.h.","math.h.","string.h.","stdlib.h."],"answer":0,"explain":"Header stdio.h khai báo hàm printf.","rationales":["Header stdio.h khai báo hàm printf.","Không phù hợp: math.h. Phát biểu đúng: Header stdio.h khai báo hàm printf.","Không phù hợp: string.h. Phát biểu đúng: Header stdio.h khai báo hàm printf.","Không phù hợp: stdlib.h. Phát biểu đúng: Header stdio.h khai báo hàm printf."]}],"summary":["Dữ liệu và thông tin","Bài toán và thuật toán","Máy tính và lưu trữ nhị phân","Biên dịch và liên kết","Cấu trúc chương trình"],"minutes":90,"syntax":[{"label":"Biến, phép gán và hiển thị kết quả","code":"int dai = 8;\nint rong = 3;\nint chu_vi = 2 * (dai + rong);\nprintf(\"%d\\n\", chu_vi);\n","meaning":"Các câu lệnh được thực thi tuần tự; %d biểu diễn đối số kiểu int khi in bằng printf.","watch":"Đoạn mã phải đặt trong thân hàm và có #include <stdio.h>."}],"flow":{"type":"sequence","caption":"Thuật toán tính chu vi hình chữ nhật","steps":["Nhập hoặc xác định dai, rong (> 0)","Tính P = 2 × (dai + rong)","Xuất chu vi P"]},"worked":{"title":"Bài mẫu: tính chu vi hình chữ nhật","problem":"Cho chiều dài 8 m, chiều rộng 3 m. Viết chương trình tính và in chu vi.","steps":["Input: dai = 8, rong = 3; giả định hai kích thước dương.","Process: P = 2 × (dai + rong).","Output: in chu vi theo đơn vị m."],"code":"#include <stdio.h>\nint main(void) {\n    int dai = 8, rong = 3;\n    int chu_vi = 2 * (dai + rong);\n    printf(\"Chu vi = %d m\\n\", chu_vi);\n    return 0;\n}\n","output":"Chu vi = 22 m","stdin":"","analysis":["2 × (8 + 3) = 22; dữ liệu được chọn nhỏ để tránh tràn số nguyên.","Chương trình này áp dụng cấu trúc tuần tự, không cần vòng lặp."],"tests":["Thay dai=10, rong=4; kết quả mong đợi là 28 m."]},"deep_dive":{"context":"Mỗi yêu cầu cần được quy về mô hình IPO (Input–Process–Output) trước khi chuyển thành lệnh C. Bảng truy vết là công cụ nối thuật toán trên giấy với trạng thái biến khi chạy.","contrast":[["Dữ liệu","Giá trị chưa gắn với ý nghĩa kết luận."],["Thông tin","Ý nghĩa rút ra khi phân tích dữ liệu trong ngữ cảnh."],["Thuật toán","Phương pháp giải; có thể mô tả độc lập với C."],["Chương trình","Cách cài đặt thuật toán bằng ngôn ngữ cụ thể."]],"pitfall":"Trong lưu đồ, hình bình hành dùng cho thao tác nhập/xuất; hình chữ nhật cho xử lý và hình thoi cho điều kiện.","challenge":"Thiết kế IPO, mã giả và bảng truy vết cho bài toán tính vận tốc trung bình từ quãng đường và thời gian khác 0."},"lab_examples":[{"title":"Từ IPO đến chương trình chạy được","purpose":"Cho hai cạnh cố định; theo dõi biến truoc và sau phép gán.","code":"#include <stdio.h>\nint main(void) {\n    int dai = 6, rong = 4;\n    int chu_vi = 2 * (dai + rong);\n    int dien_tich = dai * rong;\n    printf(\"Chu vi=%d; Dien tich=%d\\n\", chu_vi, dien_tich);\n    return 0;\n}\n","output":"Chu vi=20; Dien tich=24","stdin":"","cases":[{"stdin":"","stdout":"Chu vi=20; Dien tich=24","exit":0}],"followup":"Thay dai=0 và giải thích điều kiện tiền đề “chiều dài dương” bị vi phạm."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"teaching_note":"Nên dạy theo 2 pha: phân tích bài toán/IPO rồi đến biên dịch và chương trình đầu tiên.","module":"M1","module_title":"Tư duy thuật toán và tính toán cơ bản","design_case":{"title":"Tính tiết diện cửa gió hình chữ nhật","problem":"Với bề rộng 0,6 m và chiều cao 0,4 m, tính diện tích tiết diện thông thoáng khi bỏ qua nan và vật cản.","input":["b = 0,6 m; h = 0,4 m"],"process":["A = b × h"],"output":["A (m²)"],"assumptions":["b, h không âm; diện tích hình học không đồng nghĩa lưu lượng gió"],"pseudocode":["Bắt đầu","Nhận b và h; kiểm tra điều kiện không âm","Tính A = b × h","In A kèm đơn vị m²","Kết thúc"],"tests":[{"input":"0,6 × 0,4 m","expected":"0,24 m²","kind":"Thông thường"},{"input":"0 × 0,4 m","expected":"0 m²","kind":"Biên"},{"input":"b = −0,6 m","expected":"Từ chối dữ liệu theo đặc tả","kind":"Không hợp lệ"}],"reflection":"Đơn vị của A là gì? Vì sao không suy ra được lưu lượng gió chỉ từ diện tích?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-02","number":2,"title":"Biến, định danh và kiểu dữ liệu","unit":"Tính toán cơ bản","source":"Slot_02_03_04_Basic_Computation.pptx, slide 4–13, 23–30","lead":"Biến đặt tên cho đối tượng dữ liệu; kiểu dữ liệu quy định miền giá trị và các phép toán hợp lệ.","objectives":["Khai báo, khởi tạo và sử dụng được biến C.","Phân biệt int, char, float, double và định dạng xuất cơ bản.","Giải thích được vì sao sizeof và miền giá trị phụ thuộc môi trường."],"sections":[{"title":"Biến và định danh","text":"Biến là đối tượng có kiểu và vùng lưu trữ tương ứng trong quá trình thực thi. Tên biến gồm chữ cái, chữ số, dấu gạch dưới và không được bắt đầu bằng chữ số. C phân biệt chữ hoa với chữ thường. Nên đặt tên thể hiện ý nghĩa như so_luong thay cho x.","bullets":[]},{"title":"Khai báo và khởi tạo","text":"Cú pháp: kiểu tên_biến = giá_trị; Ví dụ int tuoi = 19; . Biến cục bộ tự động nếu không được khởi tạo thường có giá trị không xác định; đọc trước khi gán có thể dẫn tới hành vi không xác định. Hãy ưu tiên khởi tạo trước khi sử dụng.","bullets":[]},{"title":"Kiểu dữ liệu số học","text":"int biểu diễn số nguyên; char là kiểu nguyên nhỏ nhất dùng biểu diễn một byte; float và double biểu diễn số thực dấu phẩy động. C không cố định kích thước byte cho tất cả kiểu dữ liệu trên mọi hệ thống. sizeof trả về số byte theo triển khai; CHAR_BIT trong limits.h cho số bit của một byte C.","bullets":[]},{"title":"Định dạng printf","text":"Đối với printf, %d dùng cho int; %f dùng cho đối số double (float được nâng lên double khi truyền); %c dùng cho ký tự. %zu dùng để in sizeof. Cần giữ kiểu đối số khớp với yêu cầu của định dạng.","bullets":[]}],"example":{"title":"Kiểm tra khai báo và kích thước kiểu","code":"#include <stdio.h>\nint main(void) {\n    int so_luong = 12;\n    double don_gia = 3.5;\n    double tong = so_luong * don_gia;\n    printf(\"Tong = %.2f\\n\", tong);\n    printf(\"sizeof(int) = %zu byte\\n\", sizeof(int));\n    return 0;\n}\n","output":"","stdin":"","why":"Tổng được tính theo số thực; kích thước int phụ thuộc môi trường nên không đặt trước giá trị đầu ra cố định.","tests":[],"trace":["Biến số lượng và đơn giá được dùng trong phép nhân.","sizeof(int) trả số byte của int trong hệ thống thực thi, không phải hằng số chung cho mọi máy."],"output_pattern":"^Tong = 42\\.00\\nsizeof\\(int\\) = [1-9][0-9]* byte\\n?$"},"mistakes":["Mặc định int luôn 4 byte trên mọi hệ thống.","Đọc biến cục bộ chưa khởi tạo.","Dùng %d để in double."],"exercises":[{"name":"Tính tổng tiền","task":"Khai báo số lượng 7 và đơn giá 12.5, tính thành tiền và hiển thị hai chữ số thập phân.","hint":"Dùng int cho số lượng và double cho đơn giá.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Quan sát môi trường","task":"In sizeof(char), sizeof(short), sizeof(int), sizeof(long), sizeof(double).","hint":"Dùng %zu cho kết quả sizeof; không kết luận cố định từ một máy.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Viết bảng mô tả kiểu, giá trị gán và định dạng in cho các biến: tuổi, điểm, ký tự xếp loại và số lượng thiết bị.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Biến cục bộ int x; chưa khởi tạo có thể được đọc an toàn không?","choices":["Luôn bằng địa chỉ","Luôn bằng 1","Luôn bằng 0","Không, phải gán giá trị trước"],"answer":3,"explain":"Đối tượng tự động chưa khởi tạo có giá trị không xác định.","rationales":["Khai báo int x không làm x trở thành biến con trỏ.","C cũng không mặc định bằng 1.","Biến tự động chưa khởi tạo không mặc định bằng 0.","Đối tượng tự động chưa khởi tạo có giá trị không xác định."]},{"q":"Định dạng nào dùng cho sizeof trong printf chuẩn C?","choices":["%f","%d","%zu","%c"],"answer":2,"explain":"%zu in đối số kiểu size_t, kiểu của sizeof.","rationales":["%f yêu cầu double khi xuất.","%d yêu cầu đối số int tương ứng, không phải size_t.","%zu in đối số kiểu size_t, kiểu của sizeof.","%c dùng xuất ký tự từ đối số int."]},{"q":"Định dạng chuẩn của printf để in kết quả sizeof là gì?","choices":["%c.","%zu.","%lf.","%d luôn đúng trên mọi hệ thống."],"answer":1,"explain":"Toán tử sizeof có kiểu size_t.","rationales":["Không phù hợp: %c. Phát biểu đúng: Toán tử sizeof có kiểu size_t.","Toán tử sizeof có kiểu size_t.","Không phù hợp: %lf. Phát biểu đúng: Toán tử sizeof có kiểu size_t.","Không phù hợp: %d luôn đúng trên mọi hệ thống. Phát biểu đúng: Toán tử sizeof có kiểu size_t."]},{"q":"Vì sao không nên dùng int x; rồi đọc x ngay?","choices":["Biến tự động chưa khởi tạo không có giá trị xác định để sử dụng.","Đó là lỗi viết hoa.","x luôn tự bằng 0.","int không chứa số âm."],"answer":0,"explain":"Đọc một giá trị không xác định có thể gây hành vi không xác định.","rationales":["Đọc một giá trị không xác định có thể gây hành vi không xác định.","Không phù hợp: Đó là lỗi viết hoa. Phát biểu đúng: Đọc một giá trị không xác định có thể gây hành vi không xác định.","Không phù hợp: x luôn tự bằng 0. Phát biểu đúng: Đọc một giá trị không xác định có thể gây hành vi không xác định.","Không phù hợp: int không chứa số âm. Phát biểu đúng: Đọc một giá trị không xác định có thể gây hành vi không xác định."]},{"q":"Muốn biết số bit của một byte trên hệ thống, dùng hằng nào?","choices":["sizeof(int).","RAND_MAX.","FLT_DIG.","CHAR_BIT trong limits.h."],"answer":3,"explain":"C định nghĩa CHAR_BIT để cung cấp số bit mỗi byte.","rationales":["Không phù hợp: sizeof(int). Phát biểu đúng: C định nghĩa CHAR_BIT để cung cấp số bit mỗi byte.","Không phù hợp: RAND_MAX. Phát biểu đúng: C định nghĩa CHAR_BIT để cung cấp số bit mỗi byte.","Không phù hợp: FLT_DIG. Phát biểu đúng: C định nghĩa CHAR_BIT để cung cấp số bit mỗi byte.","C định nghĩa CHAR_BIT để cung cấp số bit mỗi byte."]}],"summary":["Biến và định danh","Khai báo và khởi tạo","Kiểu dữ liệu số học","Định dạng printf"],"minutes":45,"syntax":[{"label":"Khai báo biến và khởi tạo","code":"int so_luong = 3;\ndouble don_gia = 12.5;\ndouble thanh_tien = so_luong * don_gia;\n","meaning":"int chứa số nguyên; double chứa số thực dấu phẩy động; phép nhân thực hiện chuyển kiểu phù hợp.","watch":"Không giả định mọi môi trường đều có sizeof(int) = 4; cần dùng sizeof để kiểm tra khi cần."}],"flow":{"type":"sequence","caption":"Chuỗi xử lý trong bài 2: Lựa chọn kiểu dữ liệu cho hồ sơ đo","steps":["Xác định ý nghĩa từng trường","Chọn kiểu dữ liệu và tên biến","Khởi tạo các trường","In kết quả với định dạng phù hợp"]},"worked":{"title":"Bài mẫu: tính tiền hàng","problem":"Một sản phẩm giá 12,5 (đơn vị tiền minh họa), khách mua 3 sản phẩm. In tổng tiền với hai chữ số thập phân.","steps":["Khai báo so_luong kiểu int và don_gia kiểu double.","Nhân số lượng với đơn giá và lưu vào biến kiểu double.","Dùng %.2f để in kết quả với hai chữ số sau dấu thập phân."],"code":"#include <stdio.h>\nint main(void) {\n    int so_luong = 3;\n    double don_gia = 12.5;\n    double thanh_tien = so_luong * don_gia;\n    printf(\"Thanh tien = %.2f\\n\", thanh_tien);\n    return 0;\n}\n","output":"Thanh tien = 37.50","stdin":"","analysis":["Giá trị 3 được chuyển đổi phù hợp trong phép nhân với double.","%.2f là định dạng xuất của printf cho giá trị double."],"tests":["Đổi số lượng thành 4 thì tổng tiền là 50.00."]},"deep_dive":{"context":"Một tên biến cần có kiểu và giá trị xác định trước khi được đọc. Các giới hạn kiểu không đồng nhất trên mọi bộ xử lý; khi muốn biết đặc tính của môi trường, dùng các hằng trong limits.h và float.h.","contrast":[["int","Số nguyên; xuất với %d."],["char","Kiểu nguyên lưu một byte; xuất dạng ký tự với %c."],["float","Số thực đơn; khi truyền vào printf được nâng lên double."],["double","Số thực có độ chính xác ít nhất không kém float; xuất với %f."]],"pitfall":"sizeof trả số byte, không nhất thiết là byte 8 bit trong mọi triển khai C. Tránh điền cố định “int = 4 byte” vào bài giải phổ quát.","challenge":"Viết bảng mô tả kiểu, giá trị gán và định dạng in cho các biến: tuổi, điểm, ký tự xếp loại và số lượng thiết bị."},"lab_examples":[{"title":"Quan sát giới hạn kiểu dữ liệu","purpose":"In đặc tính thực tế của môi trường thay vì giả định độ dài kiểu.","code":"#include <stdio.h>\n#include <limits.h>\n#include <float.h>\nint main(void) {\n    printf(\"CHAR_BIT=%d\\n\", CHAR_BIT);\n    printf(\"INT_MAX=%d\\n\", INT_MAX);\n    printf(\"sizeof(double)=%zu\\n\", sizeof(double));\n    printf(\"FLT_DIG=%d\\n\", FLT_DIG);\n    return 0;\n}\n","output":"","stdin":"","cases":[],"followup":"Chạy trên hai môi trường khác nhau rồi so sánh giá trị CHAR_BIT và sizeof(double).","output_pattern":"^CHAR_BIT=[1-9][0-9]*\\nINT_MAX=[1-9][0-9]*\\nsizeof\\(double\\)=[1-9][0-9]*\\nFLT_DIG=[1-9][0-9]*\\n?$"}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M1","module_title":"Tư duy thuật toán và tính toán cơ bản","design_case":{"title":"Lựa chọn kiểu dữ liệu cho hồ sơ đo","problem":"Một bản ghi gồm mã thiết bị 12, nhiệt độ 26,5 °C và trạng thái bật/tắt. Chọn kiểu C phù hợp và giải thích.","input":["Mã 12; nhiệt độ 26,5 °C; trạng thái ON"],"process":["Dùng int cho mã, double cho nhiệt độ, bool hoặc int cho trạng thái"],"output":["Bản ghi có đủ ba trường"],"assumptions":["Mã chỉ định danh; không sử dụng float làm mã số"],"pseudocode":["Bắt đầu","Xác định ý nghĩa từng trường","Chọn kiểu dữ liệu và tên biến","Khởi tạo các trường","In kết quả với định dạng phù hợp","Kết thúc"],"tests":[{"input":"ID=12, T=26,5","expected":"Bảo toàn phần thập phân","kind":"Thông thường"},{"input":"T=0,0","expected":"Lưu dưới kiểu thực","kind":"Biên"},{"input":"T là chữ abc","expected":"Không chấp nhận trong phép đọc số thực","kind":"Sai kiểu"}],"reflection":"Vì sao khai báo nhiệt độ là int có thể làm mất thông tin?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-03","number":3,"title":"Hằng, biểu diễn số và nhập xuất","unit":"Tính toán cơ bản","source":"Slot_02_03_04_Basic_Computation.pptx, slide 14–22, 31–45","lead":"Nhận biết số nguyên nhị phân, số âm theo bù hai và tổ chức nhập xuất dữ liệu đúng kiểu.","objectives":["Giải thích được biểu diễn nhị phân và bù hai dưới mô hình 8 bit.","Phân biệt hằng số, const và macro #define.","Dùng scanf có kiểm tra kết quả để nhập giá trị."],"sections":[{"title":"Số nhị phân và bù hai","text":"Với mô hình minh họa số nguyên 8 bit không dấu, 00001101₂ = 13₁₀. Trong biểu diễn bù hai 8 bit, -13 có dạng 11110011₂. Đây là minh họa về dạng bit, không đồng nghĩa mọi int trong C có 8 bit. Tràn số nguyên có dấu là hành vi không xác định.","bullets":[]},{"title":"Ký tự và chuỗi hằng","text":"Một ký tự viết trong dấu nháy đơn, ví dụ 'A'; chuỗi hằng dùng nháy kép, ví dụ \"ABC\" và được kết thúc bằng byte không \\0. Một số ký tự điều khiển có dạng escape như \\n và \\t. Với ví dụ nhập môn dùng ASCII cho tập ký tự cơ bản, cần phân biệt nó với Unicode/UTF-8.","bullets":[]},{"title":"Hằng có tên","text":"const double PI = 3.141592653589793; tạo đối tượng không được sửa qua tên này sau khi khai báo; #define MAX 100 là macro thay thế tiền xử lý chứ không phải biến. Ưu tiên const khi cần một giá trị có kiểu.","bullets":[]},{"title":"Nhập bằng scanf","text":"scanf(\"%d\", &n) đọc int, cần truyền địa chỉ của n để hàm có thể ghi dữ liệu. Giá trị trả về cho biết số phép chuyển đổi gán thành công; nếu nhập sai kiểu, chương trình phải xử lý lỗi thay vì sử dụng biến chưa hợp lệ.","bullets":[]}],"example":{"title":"Nhập và tính tổng hai số nguyên","code":"#include <stdio.h>\nint main(void) {\n    int a, b;\n    printf(\"Nhap a b: \");\n    if (scanf(\"%d %d\", &a, &b) != 2) {\n        puts(\"Du lieu khong hop le\");\n        return 1;\n    }\n    printf(\"Tong = %d\\n\", a + b);\n    return 0;\n}\n","output":"Nhap a b: Tong = 15","stdin":"7 8","why":"Đầu vào mẫu là 7 8. Với số nguyên cực lớn gây tràn, phép cộng signed int không an toàn; bài này giả thiết hai đầu vào và tổng nằm trong phạm vi int.","tests":[],"trace":["Hàm scanf phải chuyển đổi thành công cả hai số trước khi sử dụng.","Sau khi cộng, printf hiển thị kết quả; chương trình giả định phép cộng không tràn int."]},"mistakes":["Quên dấu & khi nhập số nguyên bằng scanf.","Nhầm chuỗi trong nháy kép với ký tự trong nháy đơn.","Áp dụng bù hai 8 bit như kích thước bắt buộc của int."],"exercises":[{"name":"Chuyển đổi nhị phân","task":"Viết số 25 ở dạng nhị phân 8 bit và tính bù hai biểu diễn -25 trong 8 bit.","hint":"25 = 00011001; đảo bit rồi cộng 1.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Nhập số và tính trung bình","task":"Nhập 3 số nguyên, tính trung bình bằng số thực và in 2 chữ số thập phân.","hint":"Chuyển thành double hoặc chia cho 3.0; kiểm tra scanf.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Với x trong [−1000,1000], dùng phép ép (long long)x trước khi nhân, lập các test −1000, 0, 1000.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Khi scanf(\"%d\", &x) trả về 1 có nghĩa là?","choices":["x luôn bằng 1","Lỗi chương trình","Đã gán thành công một mục chuyển đổi","Đã tới cuối tệp"],"answer":2,"explain":"Giá trị trả về bằng số lượng phép gán chuyển đổi thành công.","rationales":["Giá trị trả về là số mục đã gán, không phải giá trị x.","Trả về 1 biểu thị một mục gán thành công, không phải lỗi.","Giá trị trả về bằng số lượng phép gán chuyển đổi thành công.","EOF là trường hợp không hoàn thành phép chuyển đổi trước khi gặp hết dữ liệu."]},{"q":"Dạng bù hai 8 bit của -1 là?","choices":["00000001","11111111","10000000","00000000"],"answer":1,"explain":"Trong mô hình bù hai 8 bit, tất cả bit 1 tương ứng -1.","rationales":["00000001₂ biểu diễn +1.","Trong mô hình bù hai 8 bit, tất cả bit 1 tương ứng -1.","10000000₂ là -128 trong bù hai 8 bit.","00000000₂ biểu diễn 0."]},{"q":"Điểm khác giữa const double PI và #define PI là gì?","choices":["const khai báo một đối tượng có kiểu; macro thay thế mã tiền xử lý.","const là tên hàm thư viện.","#define chỉ có trong C++.","Cả hai luôn tạo vùng nhớ giống nhau."],"answer":0,"explain":"Macro không tự tạo đối tượng có kiểu như một khai báo biến.","rationales":["Macro không tự tạo đối tượng có kiểu như một khai báo biến.","Không phù hợp: const là tên hàm thư viện. Phát biểu đúng: Macro không tự tạo đối tượng có kiểu như một khai báo biến.","Không phù hợp: #define chỉ có trong C++. Phát biểu đúng: Macro không tự tạo đối tượng có kiểu như một khai báo biến.","Không phù hợp: Cả hai luôn tạo vùng nhớ giống nhau. Phát biểu đúng: Macro không tự tạo đối tượng có kiểu như một khai báo biến."]},{"q":"Để tính x*x với |x|<=1000 trên mọi triển khai C phù hợp, nên làm gì?","choices":["Luôn dùng int vì int luôn có 32 bit.","Viết x*x rồi ép kiểu kết quả.","Đổi tên biến thành square.","Chuyển một toán hạng thành long long trước phép nhân."],"answer":3,"explain":"Giá trị 1000000 vượt INT_MAX tối thiểu nhưng nằm trong long long.","rationales":["Không phù hợp: Luôn dùng int vì int luôn có 32 bit. Phát biểu đúng: Giá trị 1000000 vượt INT_MAX tối thiểu nhưng nằm trong long long.","Không phù hợp: Viết x*x rồi ép kiểu kết quả. Phát biểu đúng: Giá trị 1000000 vượt INT_MAX tối thiểu nhưng nằm trong long long.","Không phù hợp: Đổi tên biến thành square. Phát biểu đúng: Giá trị 1000000 vượt INT_MAX tối thiểu nhưng nằm trong long long.","Giá trị 1000000 vượt INT_MAX tối thiểu nhưng nằm trong long long."]},{"q":"Khi scanf(\"%d\", &x) trả về 0, cần hiểu điều gì?","choices":["Đã đọc một số nguyên 0.","Luôn là lỗi mất mạng.","Không chuyển đổi gán thành công cho x.","x chắc chắn bằng 0."],"answer":2,"explain":"Không được sử dụng x như giá trị vừa nhập hợp lệ.","rationales":["Không phù hợp: Đã đọc một số nguyên 0. Phát biểu đúng: Không được sử dụng x như giá trị vừa nhập hợp lệ.","Không phù hợp: Luôn là lỗi mất mạng. Phát biểu đúng: Không được sử dụng x như giá trị vừa nhập hợp lệ.","Không được sử dụng x như giá trị vừa nhập hợp lệ.","Không phù hợp: x chắc chắn bằng 0. Phát biểu đúng: Không được sử dụng x như giá trị vừa nhập hợp lệ."]}],"summary":["Số nhị phân và bù hai","Ký tự và chuỗi hằng","Hằng có tên","Nhập bằng scanf"],"minutes":45,"syntax":[{"label":"Đọc số nguyên có kiểm tra","code":"int x;\nif (scanf(\"%d\", &x) != 1) {\n    return 1;\n}\n","meaning":"scanf trả về số mục được chuyển đổi/gán thành công; dấu & đưa địa chỉ biến cho hàm ghi dữ liệu.","watch":"Không dùng giá trị x nếu scanf không đọc thành công; không dùng & cho mọi đối số printf."}],"flow":{"type":"decision","caption":"Thuật toán nhập số và kiểm tra chuyển đổi","start":"Nhận dữ liệu nhập","condition":"scanf đọc được số nguyên?","yes":"Tính kết quả","no":"Thông báo dữ liệu sai","end":"Kết thúc"},"worked":{"title":"Bài mẫu: nhập số nguyên và tính bình phương","problem":"Nhập x thuộc đoạn [-1000,1000], xuất bình phương x. Thông báo nếu nhập sai hoặc ngoài phạm vi.","steps":["Đọc x bằng scanf và kiểm tra giá trị trả về bằng 1.","Kiểm tra miền đầu vào để phép nhân x*x không gây tràn trên môi trường thông dụng.","Tính và in kết quả nếu đầu vào hợp lệ."],"code":"#include <stdio.h>\nint main(void) {\n    int x;\n    if (scanf(\"%d\", &x) != 1) {\n        puts(\"Du lieu khong hop le\");\n        return 1;\n    }\n    if (x < -1000 || x > 1000) {\n        puts(\"Ngoai pham vi\");\n        return 1;\n    }\n    long long square = (long long)x * x;\n    printf(\"Binh phuong = %lld\\n\", square);\n    return 0;\n}\n","output":"Binh phuong = 49","stdin":"7","analysis":["Phải kiểm tra dữ liệu trước khi sử dụng; scanf cơ bản chưa bảo đảm chấp nhận mọi chuỗi số không vượt miền theo chuẩn, bài 12 sẽ trình bày chuyển đổi nghiêm ngặt.","Ép (long long)x trước phép nhân nên |x|≤1000 không gây tràn long long; không thể giả định int trên mọi hệ thống có thể lưu 1.000.000."],"tests":["x=−1000 → bình phương = 1000000; x=0 → 0; x=1000 → 1000000; x=1001 → ngoài phạm vi."]},"deep_dive":{"context":"Hằng có tên cho phép giải thích ý nghĩa đại lượng. Bên cạnh scanf cơ bản, cần nhận thức giới hạn của chuyển đổi đầu vào và phép toán số nguyên trước khi học cách xác thực đầy đủ ở Slot 12.","contrast":[["const","Đối tượng có kiểu được khai báo và không sửa qua tên này."],["#define","Phép thay thế ở giai đoạn tiền xử lý, không tự tạo biến."],["Ký tự hằng","Ví dụ: 'A'; khác chuỗi \"A\" có thêm byte NUL."]],"pitfall":"Tràn số nguyên có dấu là hành vi không xác định. Phép bình phương phải chọn kiểu đủ rộng trước khi phép nhân được thực hiện.","challenge":"Với x trong [−1000,1000], dùng phép ép (long long)x trước khi nhân, lập các test −1000, 0, 1000."},"lab_examples":[{"title":"So sánh const và macro","purpose":"Cùng tính chu vi hình tròn bằng các giá trị được đặt tên.","code":"#include <stdio.h>\n#define SO_MAT 2\nint main(void) {\n    const double PI = 3.141592653589793;\n    double r = 2.0;\n    printf(\"Chu vi=%.2f\\n\", SO_MAT * PI * r);\n    return 0;\n}\n","output":"Chu vi=12.57","stdin":"","cases":[{"stdin":"","stdout":"Chu vi=12.57","exit":0}],"followup":"Giải thích vì sao #define không chứa dấu chấm phẩy cuối dòng."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M1","module_title":"Tư duy thuật toán và tính toán cơ bản","design_case":{"title":"Tính điện năng từ công suất không đổi","problem":"Thiết bị tiêu thụ công suất điện đầu vào giả định không đổi 1500 W trong 2 h. Tính điện năng theo kWh.","input":["P = 1500 W; t = 2 h"],"process":["E = P × t / 1000"],"output":["E = 3,0 kWh"],"assumptions":["P là công suất điện, không phải công suất lạnh; giả thiết P không đổi"],"pseudocode":["Bắt đầu","Đọc P và t; kiểm tra không âm","Tính E = (P / 1000) × t dưới dạng số thực","In E kWh","Kết thúc"],"tests":[{"input":"1500 W; 2 h","expected":"3,0 kWh","kind":"Thông thường"},{"input":"0 W; 2 h","expected":"0 kWh","kind":"Biên"},{"input":"1500 W; −2 h","expected":"Không hợp lệ theo đặc tả","kind":"Dữ liệu sai"}],"reflection":"Phép chia 1000 phải xử lý thế nào để không bị mất phần thập phân?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-04","number":4,"title":"Toán tử, biểu thức và chuyển kiểu","unit":"Tính toán cơ bản","source":"Slot_02_03_04_Basic_Computation.pptx, slide 46–63","lead":"Sử dụng phép toán đúng kiểu, nhận diện ưu tiên toán tử và tác động của phép chia nguyên.","objectives":["Phân loại được toán tử số học, quan hệ, logic và gán.","Giải thích được chia nguyên, ép kiểu, ưu tiên và thứ tự tính toán.","Viết chương trình tính toán tránh lỗi sai kiểu dữ liệu."],"sections":[{"title":"Toán tử số học","text":"Các toán tử số học cơ bản là +, -, *, / và %. Khi cả hai toán hạng của / đều là số nguyên thì kết quả được cắt về 0; % lấy phần dư của phép chia nguyên và không được chia cho 0. Với số thực, 5.0/2 cho kết quả 2.5.","bullets":[]},{"title":"So sánh và logic","text":"Toán tử quan hệ: <, <=, >, >=, ==, !=. Toán tử logic: &&, ||, !. Trong C, giá trị 0 là sai, khác 0 là đúng trong điều kiện; kết quả phép so sánh/logic là int 0 hoặc 1. && và || có đánh giá ngắn mạch.","bullets":[]},{"title":"Gán và tăng giảm","text":"Dấu = là gán, không phải so sánh; == dùng so sánh bằng. ++i tăng i rồi tạo giá trị mới, i++ tạo giá trị cũ sau đó tăng. Tránh kết hợp nhiều phép sửa cùng một biến trong một biểu thức chưa nắm thứ tự đánh giá.","bullets":[]},{"title":"Chuyển kiểu và thứ tự ưu tiên","text":"Phép ép kiểu (double)a/b làm phép chia thực nếu b khác 0. Dấu ngoặc () giúp diễn đạt thứ tự mong muốn; ưu tiên toán tử không quyết định toàn bộ thứ tự đánh giá toán hạng. Với biểu thức phức tạp, tách câu lệnh để dễ kiểm chứng.","bullets":[]},{"title":"Toán tử bit","text":"&, |, ^, ~, <<, >> thao tác trên bit của kiểu nguyên. Không nhầm & (AND bit) với && (AND logic), | với ||. Tránh dịch trái số âm hoặc dịch vượt độ rộng kiểu.","bullets":[]}],"example":{"title":"So sánh chia nguyên và chia thực","code":"#include <stdio.h>\nint main(void) {\n    int tong = 17, so_bai = 4;\n    printf(\"Chia nguyen: %d\\n\", tong / so_bai);\n    printf(\"Chia thuc: %.2f\\n\", (double)tong / so_bai);\n    printf(\"Du: %d\\n\", tong % so_bai);\n    return 0;\n}\n","output":"Chia nguyen: 4\nChia thuc: 4.25\nDu: 1","stdin":"","why":"Đọc chương trình theo thứ tự thực thi, dự đoán kết quả trước khi chạy và đối chiếu các bước giải thích ngay dưới mã ví dụ.","tests":[],"trace":["Biểu thức 17/4 thực hiện phép chia nguyên nên cho 4.","Ép (double)17/4 cho kết quả 4.25; phép % cho phần dư 1."]},"mistakes":["Nhầm = và ==.","Dùng phép chia nguyên để tính trung bình số thực.","Cho rằng && và & tương đương."],"exercises":[{"name":"Tính BMI","task":"Nhập cân nặng (kg), chiều cao (m), tính BMI = cân_nặng / (chiều_cao × chiều_cao).","hint":"Dùng double và kiểm tra chiều cao > 0.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Phân tích biểu thức","task":"Cho a=7, b=3; dự đoán a/b, (double)a/b và a%b.","hint":"Giải thích trước rồi chạy ví dụ đối chiếu.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Viết ba biểu thức điều kiện tránh chia cho 0, kiểm tra biên và dùng một phép dịch trái trên unsigned không vượt độ rộng.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Với int a=7,b=3, a/b bằng?","choices":["3","2","2.33","1"],"answer":1,"explain":"Phép chia nguyên lấy phần nguyên cắt về 0.","rationales":["Phép chia nguyên 7/3 không làm tròn lên thành 3.","Phép chia nguyên lấy phần nguyên cắt về 0.","2.33 là kết quả gần đúng của phép chia thực, không phải chia nguyên.","1 là phần dư của 7 chia 3, không phải thương."]},{"q":"Toán tử so sánh bằng trong C là?","choices":["==","=","&&","!="],"answer":0,"explain":"== so sánh bằng; = là gán.","rationales":["== so sánh bằng; = là gán.","= là phép gán.","&& biểu thị AND logic.","!= biểu thị khác nhau."]},{"q":"Điều kiện b!=0 && a/b>2 khi b==0 sẽ làm gì?","choices":["Chia cho 0 rồi bắt lỗi.","Tự đổi b thành 1.","Luôn chạy vế phải trước.","Không đánh giá phép chia a/b."],"answer":3,"explain":"&& đánh giá ngắn mạch khi vế trái sai.","rationales":["Không phù hợp: Chia cho 0 rồi bắt lỗi. Phát biểu đúng: && đánh giá ngắn mạch khi vế trái sai.","Không phù hợp: Tự đổi b thành 1. Phát biểu đúng: && đánh giá ngắn mạch khi vế trái sai.","Không phù hợp: Luôn chạy vế phải trước. Phát biểu đúng: && đánh giá ngắn mạch khi vế trái sai.","&& đánh giá ngắn mạch khi vế trái sai."]},{"q":"Khác biệt giữa & và && với các toán hạng nguyên là gì?","choices":["& chỉ dùng cho số thực.","Hai toán tử hoàn toàn giống nhau.","& tính AND từng bit; && là AND logic và ngắn mạch.","&& lấy địa chỉ biến."],"answer":2,"explain":"Hai toán tử có ý nghĩa và quy tắc đánh giá khác nhau.","rationales":["Không phù hợp: & chỉ dùng cho số thực. Phát biểu đúng: Hai toán tử có ý nghĩa và quy tắc đánh giá khác nhau.","Không phù hợp: Hai toán tử hoàn toàn giống nhau. Phát biểu đúng: Hai toán tử có ý nghĩa và quy tắc đánh giá khác nhau.","Hai toán tử có ý nghĩa và quy tắc đánh giá khác nhau.","Không phù hợp: && lấy địa chỉ biến. Phát biểu đúng: Hai toán tử có ý nghĩa và quy tắc đánh giá khác nhau."]},{"q":"Biểu thức (double)a/b với a=5,b=2 cho giá trị nào?","choices":["Biểu thức không biên dịch.","2.5.","2.","3."],"answer":1,"explain":"Một toán hạng đã được chuyển thành double trước khi chia.","rationales":["Không phù hợp: Biểu thức không biên dịch. Phát biểu đúng: Một toán hạng đã được chuyển thành double trước khi chia.","Một toán hạng đã được chuyển thành double trước khi chia.","Không phù hợp: 2. Phát biểu đúng: Một toán hạng đã được chuyển thành double trước khi chia.","Không phù hợp: 3. Phát biểu đúng: Một toán hạng đã được chuyển thành double trước khi chia."]}],"summary":["Toán tử số học","So sánh và logic","Gán và tăng giảm","Chuyển kiểu và thứ tự ưu tiên","Toán tử bit"],"minutes":45,"syntax":[{"label":"Các toán tử số học, quan hệ và chuyển kiểu","code":"int a = 7, b = 2;\nint phan_nguyen = a / b;\ndouble thuong = (double)a / b;\nint du = a % b;\n","meaning":"7/2 bằng 3 vì cả hai toán hạng là số nguyên; chuyển kiểu trước phép chia tạo kết quả 3.5; % lấy phần dư phép chia nguyên.","watch":"Không nhầm = (gán) với == (so sánh); tránh chia cho 0."}],"flow":{"type":"sequence","caption":"Chuỗi xử lý trong bài 4: Kiểm tra phép chia nguyên trong công thức kỹ thuật","steps":["Khởi tạo P và t","Tính E1 bằng chia nguyên; E2 bằng chia số thực","So sánh hai kết quả","Giải thích nguyên nhân chênh lệch"]},"worked":{"title":"Bài mẫu: đổi độ C sang độ F","problem":"Cho nhiệt độ 25 °C. Tính nhiệt độ theo thang Fahrenheit với công thức F = C × 9/5 + 32.","steps":["Biểu diễn nhiệt độ Celsius kiểu double.","Dùng hằng thực 9.0/5.0 để tránh chia nguyên ngoài ý muốn.","Xuất kết quả làm tròn tới hai chữ số sau dấu thập phân."],"code":"#include <stdio.h>\nint main(void) {\n    double c = 25.0;\n    double f = c * 9.0 / 5.0 + 32.0;\n    printf(\"Nhiet do F = %.2f\\n\", f);\n    return 0;\n}\n","output":"Nhiet do F = 77.00","stdin":"","analysis":["Nếu viết 9/5 ở dạng hai toán hạng int, kết quả của phép chia là 1.","Công thức được áp dụng cho giá trị nhiệt độ xác định, không hàm ý sai số đo."],"tests":["Với c=0, kết quả là 32.00 °F."]},"deep_dive":{"context":"Đánh giá ngắn mạch của && và || không chỉ tối ưu mà còn có thể bảo vệ một phép toán phía sau. Toán tử bit không đồng nghĩa toán tử logic; thứ tự ưu tiên khác thứ tự đánh giá toán hạng.","contrast":[["a && b","Nếu a bằng 0, b không được đánh giá."],["a & b","AND trên từng bit của kiểu nguyên, hai toán hạng đều được tính."],["a || b","Nếu a khác 0, b không được đánh giá."],["a | b","OR trên từng bit, khác OR logic."]],"pitfall":"Không viết i = i++ + ++i; vì thao tác sửa biến nhiều lần không được sắp thứ tự phù hợp có hành vi không xác định.","challenge":"Viết ba biểu thức điều kiện tránh chia cho 0, kiểm tra biên và dùng một phép dịch trái trên unsigned không vượt độ rộng."},"lab_examples":[{"title":"Đánh giá ngắn mạch bảo vệ phép chia","purpose":"Toán tử && chỉ thực hiện phép chia khi mẫu số khác 0.","code":"#include <stdio.h>\nint main(void) {\n    int a = 12, b = 0;\n    if (b != 0 && a / b > 2) {\n        puts(\"Lon hon 2\");\n    } else {\n        puts(\"Khong chia khi b bang 0\");\n    }\n    unsigned x = 5U;\n    printf(\"5 & 3 = %u\\n\", x & 3U);\n    return 0;\n}\n","output":"Khong chia khi b bang 0\n5 & 3 = 1","stdin":"","cases":[{"stdin":"","stdout":"Khong chia khi b bang 0\n5 & 3 = 1","exit":0}],"followup":"Thay b=3 và dự đoán kết quả điều kiện đầu tiên."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M1","module_title":"Tư duy thuật toán và tính toán cơ bản","design_case":{"title":"Kiểm tra phép chia nguyên trong công thức kỹ thuật","problem":"Tính năng lượng điện khi P = 1500 W và t = 1 h. Giải thích lỗi khi viết biểu thức chia nguyên trước phép nhân.","input":["P = 1500 W; t = 1 h"],"process":["So sánh P / 1000 với P / 1000.0"],"output":["Kết quả toán học 1,5 kWh"],"assumptions":["Tránh tràn số nếu nhân số nguyên lớn trước khi chuyển kiểu"],"pseudocode":["Bắt đầu","Khởi tạo P và t","Tính E1 bằng chia nguyên; E2 bằng chia số thực","So sánh hai kết quả","Giải thích nguyên nhân chênh lệch"],"tests":[{"input":"1500/1000 (int)","expected":"1","kind":"Mất phần thập phân"},{"input":"1500/1000.0","expected":"1,5","kind":"Đúng kiểu thực"},{"input":"0/1000.0","expected":"0,0","kind":"Biên"}],"reflection":"Vì sao dùng 1000.0 thay vì 1000 có thể thay đổi kết quả?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-05","number":5,"title":"Tư duy thuật toán, mã giả và lưu đồ","unit":"Điều khiển luồng","source":"Slot_05_06_07_Basic_Logics.pptx, slide 5–12","lead":"Hình thành tư duy cấu trúc trước khi triển khai lựa chọn và lặp.","objectives":["Chỉ ra được ba cấu trúc tuần tự, rẽ nhánh và lặp.","Mô tả thuật toán bằng mã giả và lưu đồ.","Truy vết chương trình theo đầu vào cụ thể."],"sections":[{"title":"Ba cấu trúc điều khiển","text":"Thuật toán có thể mô tả bằng tuần tự, lựa chọn và lặp. Tuần tự thực hiện lệnh theo thứ tự; lựa chọn dựa trên điều kiện; lặp thực hiện thân lặp khi điều kiện cho phép. Các cấu trúc này là nền tảng của lập trình có cấu trúc.","bullets":[]},{"title":"Mã giả","text":"Mã giả diễn đạt các bước giải bằng cấu trúc gần ngôn ngữ lập trình nhưng không ràng buộc cú pháp C. Ví dụ: Nhập n; nếu n < 0 thì xuất -n; ngược lại xuất n. Mục tiêu là xác định luồng xử lý trước khi viết đúng cú pháp.","bullets":[]},{"title":"Lưu đồ","text":"Lưu đồ biểu diễn luồng bằng hình: bầu dục cho bắt đầu/kết thúc, hình bình hành cho nhập/xuất, hình chữ nhật cho xử lý, hình thoi cho quyết định và mũi tên cho hướng đi. Điều kiện phải có các nhánh được ghi rõ để tránh diễn giải mơ hồ.","bullets":[]},{"title":"Truy vết","text":"Truy vết (walkthrough) là theo dõi từng bước thay đổi biến và nhánh điều kiện với một bộ dữ liệu cụ thể. Bảng truy vết nên ghi giá trị đầu vào, điều kiện được đánh giá, câu lệnh thực hiện và kết quả biến sau bước đó.","bullets":[]}],"example":{"title":"Phân loại số âm và không âm bằng if/else","code":"#include <stdio.h>\nint main(void) {\n    int x;\n    if (scanf(\"%d\", &x) != 1) return 1;\n    if (x < 0) {\n        printf(\"So am\\n\");\n    } else {\n        printf(\"So khong am\\n\");\n    }\n    return 0;\n}\n","output":"So am","stdin":"-5","why":"Chương trình phân loại dấu của số; không hề tính giá trị tuyệt đối. Nhánh else nhận cả số 0.","tests":[],"trace":["Giá trị đầu vào được phân loại theo dấu trước khi chọn nhánh.","Tránh áp dụng phép đổi dấu với INT_MIN, vì trị tuyệt đối của INT_MIN không biểu diễn được bằng kiểu int thông thường."]},"mistakes":["Vẽ lưu đồ thiếu nhánh sai hoặc đúng.","Dùng mã giả như thể là cú pháp C.","Không kiểm thử trường hợp x=0."],"exercises":[{"name":"Lưu đồ phân loại","task":"Vẽ lưu đồ phân loại số nguyên dương, âm hoặc bằng 0.","hint":"Dùng hai quyết định theo thứ tự x>0, x<0.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Truy vết","task":"Tạo bảng truy vết cho x=-5, 0, 12 trong chương trình mẫu.","hint":"Ghi điều kiện nào đúng tại mỗi ca.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Vẽ lưu đồ và lập bảng truy vết với ba đầu vào −8, 0, 8; ghi rõ điều kiện chọn nhánh.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Khối hình thoi trong lưu đồ thường biểu diễn?","choices":["Quyết định điều kiện","Bắt đầu","Phép nhập","Kết thúc"],"answer":0,"explain":"Hình thoi dùng cho điều kiện rẽ nhánh.","rationales":["Hình thoi dùng cho điều kiện rẽ nhánh.","Bắt đầu thường là hình bầu dục/đầu-cuối.","Nhập/xuất thường biểu diễn bằng hình bình hành.","Kết thúc cũng dùng hình bầu dục/đầu-cuối."]},{"q":"Mã giả có bắt buộc dùng đúng dấu ; của C không?","choices":["Chỉ với hàm","Chỉ với vòng lặp","Có","Không"],"answer":3,"explain":"Mã giả là công cụ diễn đạt thuật toán, không phải chương trình C.","rationales":["Không có ngoại lệ bắt buộc đúng dấu ; riêng hàm.","Không có ngoại lệ bắt buộc đúng dấu ; riêng vòng lặp.","Mã giả không có yêu cầu tuân thủ cú pháp C.","Mã giả là công cụ diễn đạt thuật toán, không phải chương trình C."]},{"q":"Trong lưu đồ theo quy ước, hình thoi biểu diễn gì?","choices":["Một phép gán không điều kiện.","Bắt đầu.","Điều kiện rẽ nhánh.","Đầu vào."],"answer":2,"explain":"Hình thoi dùng để kiểm tra điều kiện với các nhánh ra được gắn nhãn.","rationales":["Không phù hợp: Một phép gán không điều kiện. Phát biểu đúng: Hình thoi dùng để kiểm tra điều kiện với các nhánh ra được gắn nhãn.","Không phù hợp: Bắt đầu. Phát biểu đúng: Hình thoi dùng để kiểm tra điều kiện với các nhánh ra được gắn nhãn.","Hình thoi dùng để kiểm tra điều kiện với các nhánh ra được gắn nhãn.","Không phù hợp: Đầu vào. Phát biểu đúng: Hình thoi dùng để kiểm tra điều kiện với các nhánh ra được gắn nhãn."]},{"q":"Chương trình chỉ in \"Số âm\" khi x<0 đã làm gì?","choices":["Đã chuyển dữ liệu sang nhị phân.","Phân loại dấu của số, chưa tính trị tuyệt đối.","Đã tính |x|.","Đã sắp xếp số."],"answer":1,"explain":"Không có phép toán tạo ra |x|.","rationales":["Không phù hợp: Đã chuyển dữ liệu sang nhị phân. Phát biểu đúng: Không có phép toán tạo ra |x|.","Không có phép toán tạo ra |x|.","Không phù hợp: Đã tính |x|. Phát biểu đúng: Không có phép toán tạo ra |x|.","Không phù hợp: Đã sắp xếp số. Phát biểu đúng: Không có phép toán tạo ra |x|."]},{"q":"Vì sao lấy -INT_MIN bằng kiểu int là không an toàn trong một số mô hình số nguyên?","choices":["Giá trị dương tương ứng có thể vượt INT_MAX.","Toán tử - không tồn tại trong C.","INT_MIN luôn là 0.","Vì puts tự thêm newline."],"answer":0,"explain":"Số đối của INT_MIN có thể không biểu diễn được bằng int.","rationales":["Số đối của INT_MIN có thể không biểu diễn được bằng int.","Không phù hợp: Toán tử - không tồn tại trong C. Phát biểu đúng: Số đối của INT_MIN có thể không biểu diễn được bằng int.","Không phù hợp: INT_MIN luôn là 0. Phát biểu đúng: Số đối của INT_MIN có thể không biểu diễn được bằng int.","Không phù hợp: Vì puts tự thêm newline. Phát biểu đúng: Số đối của INT_MIN có thể không biểu diễn được bằng int."]}],"summary":["Ba cấu trúc điều khiển","Mã giả","Lưu đồ","Truy vết"],"minutes":45,"syntax":[{"label":"Mã giả theo ba cấu trúc điều khiển","code":"NHẬP x\nNẾU x >= 0 THÌ\n    IN \"không âm\"\nNGƯỢC LẠI\n    IN \"âm\"\nKẾT THÚC NẾU\n","meaning":"Đây là mã giả (không phải mã C): diễn đạt rõ điều kiện rẽ nhánh và hai hướng xử lý.","watch":"Cấu trúc thuật toán cần phản ánh đúng yêu cầu; không nhầm mã giả với mã có thể biên dịch."}],"flow":{"type":"decision","caption":"Lưu đồ phân loại số âm và không âm","start":"Bắt đầu với x","condition":"x ≥ 0 ?","yes":"In: Không âm","no":"In: Âm","end":"Kết thúc"},"worked":{"title":"Bài mẫu: phân loại số nguyên","problem":"Cho x = -8; mô tả thuật toán rẽ nhánh và hiện thực C để xuất số âm hay không âm.","steps":["Input: số nguyên x.","Điều kiện: nếu x >= 0 thì nhánh không âm; ngược lại nhánh âm.","Thực hiện đúng một nhánh và kết thúc."],"code":"#include <stdio.h>\nint main(void) {\n    int x = -8;\n    if (x >= 0) {\n        puts(\"Khong am\");\n    } else {\n        puts(\"Am\");\n    }\n    return 0;\n}\n","output":"Am","stdin":"","analysis":["Điều kiện -8 >= 0 sai, vì vậy chỉ nhánh else chạy.","Số 0 thuộc nhánh không âm."],"tests":["Đổi x=0 → Khong am.","Đổi x=5 → Khong am."]},"deep_dive":{"context":"Lưu đồ là biểu diễn trực quan của logic, không phải hình trang trí. Ba cấu trúc tuần tự, rẽ nhánh và lặp đủ để xây dựng nhiều thuật toán cơ bản; hình thoi phải có nhánh Đúng/Sai rõ ràng.","contrast":[["Hình bầu dục","Bắt đầu hoặc kết thúc."],["Hình bình hành","Nhập hoặc xuất dữ liệu."],["Hình chữ nhật","Thao tác xử lý hoặc gán."],["Hình thoi","Điều kiện phân nhánh."]],"pitfall":"Với INT_MIN, phép lấy -x bằng kiểu int có thể tràn. Không được khẳng định ép qua long long luôn đủ rộng trên mọi triển khai C; cách dùng unsigned int ở đây tránh phụ thuộc đó.","challenge":"Vẽ lưu đồ và lập bảng truy vết với ba đầu vào −8, 0, 8; ghi rõ điều kiện chọn nhánh."},"lab_examples":[{"title":"Độ lớn của INT_MIN bằng số nguyên không dấu","purpose":"Tính độ lớn của int theo quy tắc chuyển đổi unsigned, không lấy -INT_MIN bằng kiểu có dấu.","code":"#include <stdio.h>\n#include <limits.h>\nint main(void) {\n    int x = INT_MIN;\n    unsigned int mag = x < 0 ? 0U - (unsigned int)x : (unsigned int)x;\n    printf(\"Do lon INT_MIN = %u\\n\", mag);\n    return 0;\n}\n","output":"","stdin":"","cases":[],"followup":"Kiểm tra UINT_MAX, INT_MIN trong limits.h rồi đối chiếu kết quả trên OnlineGDB; giải thích quy tắc số học modulo của unsigned.","output_pattern":"^Do lon INT_MIN = [1-9][0-9]*\\n?$"}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M2","module_title":"Cấu trúc điều khiển và tổ chức chương trình","design_case":{"title":"Mô tả điều kiện cảnh báo quá nhiệt","problem":"Cảnh báo khi nhiệt độ T lớn hơn 30 °C; tại đúng 30 °C chưa cảnh báo. Trình bày mã giả, lưu đồ và ca biên.","input":["T, °C; ngưỡng giả định 30 °C"],"process":["Nếu T > 30 thì cảnh báo, ngược lại bình thường"],"output":["Trạng thái nhị phân cảnh báo/không cảnh báo"],"assumptions":["Ngưỡng 30 °C chỉ để học thuật toán, không là ngưỡng bảo vệ thực tế"],"pseudocode":["Bắt đầu","Đọc T","Nếu T > 30: trạng thái = CẢNH BÁO","Ngược lại: trạng thái = BÌNH THƯỜNG","Xuất trạng thái; kết thúc"],"tests":[{"input":"T=29","expected":"Bình thường","kind":"Dưới ngưỡng"},{"input":"T=30","expected":"Bình thường","kind":"Biên"},{"input":"T=31","expected":"Cảnh báo","kind":"Trên ngưỡng"}],"reflection":"Điều kiện T > 30 khác T >= 30 ở trường hợp nào?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-06","number":6,"title":"Rẽ nhánh if, else và switch","unit":"Điều khiển luồng","source":"Slot_05_06_07_Basic_Logics.pptx, slide 13–23","lead":"Quyết định luồng xử lý theo điều kiện và phân biệt lựa chọn theo khoảng với lựa chọn theo giá trị rời rạc.","objectives":["Viết được if, else if, else và switch đúng cú pháp.","Giải thích được dangling else, break và fall-through.","Phân tích được các ca biên của điều kiện."],"sections":[{"title":"if và else","text":"Cấu trúc if (điều_kiện) thực hiện câu lệnh khi điều kiện khác 0. else gắn với if gần nhất chưa có else, vì vậy dùng ngoặc nhọn giúp tránh nhầm. Có thể kết hợp else if để xử lý nhiều khoảng điều kiện.","bullets":[]},{"title":"switch","text":"switch (biểu_thức_nguyên) phân nhánh theo các giá trị hằng của case. Nếu không dùng break, thực thi sẽ tiếp tục sang các nhãn case tiếp theo (fall-through). default xử lý trường hợp không khớp; nó không bắt buộc nhưng thường hữu ích.","bullets":[]},{"title":"Điều kiện ghép","text":"Sử dụng && để yêu cầu đồng thời hai điều kiện, || khi chỉ cần một điều kiện. Ví dụ điểm >= 0 && điểm <= 10 là điều kiện hợp lệ. Các biên bằng phải được kiểm thử riêng, nhất là ngưỡng đỗ và ngưỡng xếp loại.","bullets":[]},{"title":"Toán tử điều kiện","text":"Biểu thức điều_kiện ? biểu_thức_đúng : biểu_thức_sai tạo một giá trị theo nhánh đã chọn. Phù hợp với phép lựa chọn ngắn, nhưng không nên thay thế chuỗi if phức tạp làm giảm tính dễ đọc.","bullets":[]}],"example":{"title":"Phân loại điểm có kiểm tra miền hợp lệ","code":"#include <stdio.h>\nint main(void) {\n    double diem;\n    if (scanf(\"%lf\", &diem) != 1) return 1;\n    if (diem < 0 || diem > 10) {\n        puts(\"Khong hop le\");\n    } else if (diem >= 5) {\n        puts(\"Dat\");\n    } else {\n        puts(\"Chua dat\");\n    }\n    return 0;\n}\n","output":"Dat","stdin":"7.5","why":"Đọc chương trình theo thứ tự thực thi, dự đoán kết quả trước khi chạy và đối chiếu các bước giải thích ngay dưới mã ví dụ.","tests":[],"trace":["scanf(\"%lf\", &diem) đọc số thực kiểu double.","Nếu điểm ngoài 0–10 thì in Không hợp lệ; với 7.5, nhánh diem>=5 được chọn và in Dat."]},"mistakes":["Thiếu break sau case khi không mong muốn đi tiếp.","Dùng = thay vì == trong điều kiện.","Quên xét các biên như 0, 5 và 10."],"exercises":[{"name":"Menu tháng","task":"Nhập tháng nguyên 1..12, dùng switch xuất số ngày của tháng trong năm không nhuận.","hint":"Gộp case 1,3,5,7,8,10,12; kiểm tra tháng ngoài miền.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bậc giá điện minh họa","task":"Nhập số kWh >=0; tính tiền với mức giá giả định cho ba bậc.","hint":"Nêu rõ đây là bảng giá giả định, không phải giá điện hiện hành.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Thiết kế menu 4 phép toán hai số, nêu điều kiện để phép chia hợp lệ và cách xử lý lựa chọn sai.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Nếu không có break, switch thường sẽ?","choices":["Bỏ qua case tiếp theo","Báo lỗi cú pháp","Quay lại switch","Tiếp tục thực thi các câu lệnh của case sau"],"answer":3,"explain":"Đó là hành vi fall-through của switch.","rationales":["Không có break không khiến C bỏ qua case sau.","Fall-through là cú pháp hợp lệ, không phải lỗi biên dịch.","Không tự quay lại đầu switch.","Đó là hành vi fall-through của switch."]},{"q":"else thuộc về if nào khi không có dấu ngoặc nhọn?","choices":["mọi if","if đầu tiên","if gần nhất chưa có else","không if nào"],"answer":2,"explain":"Quy tắc dangling else gắn else với if gần nhất chưa được ghép.","rationales":["Một else chỉ ghép với một if phù hợp.","Không nhất thiết gắn với if đầu tiên nếu còn if gần hơn.","Quy tắc dangling else gắn else với if gần nhất chưa được ghép.","else không thể đứng độc lập mà không có if tương ứng."]},{"q":"switch trong C nhận biểu thức điều khiển thuộc loại nào?","choices":["Kiểu struct.","Kiểu nguyên hoặc enum sau chuyển đổi phù hợp.","Mảng double.","Chuỗi ký tự bất kỳ."],"answer":1,"explain":"Các nhãn case phải là biểu thức hằng nguyên phù hợp.","rationales":["Không phù hợp: Kiểu struct. Phát biểu đúng: Các nhãn case phải là biểu thức hằng nguyên phù hợp.","Các nhãn case phải là biểu thức hằng nguyên phù hợp.","Không phù hợp: Mảng double. Phát biểu đúng: Các nhãn case phải là biểu thức hằng nguyên phù hợp.","Không phù hợp: Chuỗi ký tự bất kỳ. Phát biểu đúng: Các nhãn case phải là biểu thức hằng nguyên phù hợp."]},{"q":"Nếu thiếu break cuối case 1 và có case 2 ngay sau thì thường xảy ra gì?","choices":["Tiếp tục thực hiện lệnh của case 2 (fall-through).","C tự thêm break.","Tự động quay về main.","switch tạo vòng lặp vô hạn."],"answer":0,"explain":"switch không tự dừng khi đi hết một nhánh case.","rationales":["switch không tự dừng khi đi hết một nhánh case.","Không phù hợp: C tự thêm break. Phát biểu đúng: switch không tự dừng khi đi hết một nhánh case.","Không phù hợp: Tự động quay về main. Phát biểu đúng: switch không tự dừng khi đi hết một nhánh case.","Không phù hợp: switch tạo vòng lặp vô hạn. Phát biểu đúng: switch không tự dừng khi đi hết một nhánh case."]},{"q":"default trong switch được dùng khi nào?","choices":["Khi chương trình cần giải phóng bộ nhớ.","Khi biến mang giá trị âm dù có case tương ứng.","Khi luôn có lỗi biên dịch.","Khi không có nhãn case nào khớp giá trị biểu thức."],"answer":3,"explain":"default cung cấp nhánh dự phòng.","rationales":["Không phù hợp: Khi chương trình cần giải phóng bộ nhớ. Phát biểu đúng: default cung cấp nhánh dự phòng.","Không phù hợp: Khi biến mang giá trị âm dù có case tương ứng. Phát biểu đúng: default cung cấp nhánh dự phòng.","Không phù hợp: Khi luôn có lỗi biên dịch. Phát biểu đúng: default cung cấp nhánh dự phòng.","default cung cấp nhánh dự phòng."]}],"summary":["if và else","switch","Điều kiện ghép","Toán tử điều kiện"],"minutes":45,"syntax":[{"label":"Rẽ nhánh if/else","code":"if (dieu_kien) {\n    /* xử lý khi đúng */\n} else {\n    /* xử lý khi sai */\n}\n","meaning":"Biểu thức điều kiện có giá trị bằng 0 được xem là sai; khác 0 là đúng.","watch":"Dùng dấu ngoặc nhọn để tránh lỗi ghép nhánh và duy trì cách viết nhất quán."},{"label":"Nhiều lựa chọn với switch","code":"switch (gia_tri_nguyen) {\n    case 1: /* xử lý */ break;\n    case 2: /* xử lý */ break;\n    default: /* trường hợp còn lại */ break;\n}\n","meaning":"switch so sánh biểu thức kiểu nguyên với các nhãn case hằng số nguyên; break thoát switch.","watch":"Thiếu break có thể gây chuyển tiếp xuống case kế tiếp; không sử dụng khoảng điều kiện dạng x>10 trong nhãn case."}],"flow":{"type":"decision","caption":"Rẽ nhánh chính sách giảm giá minh họa","start":"Nhận tổng tiền T","condition":"T ≥ 500 ?","yes":"Giảm 10%","no":"Không giảm","end":"Xuất số tiền thanh toán"},"worked":{"title":"Bài mẫu: tính giá sau giảm","problem":"Quy ước minh họa: đơn hàng có tổng tiền từ 500 trở lên được giảm 10%; các đơn khác giữ nguyên. Tính số tiền phải trả cho đơn 500.","steps":["Xác định T=500, kiểm tra T>=500.","Áp dụng mức giảm 10% khi điều kiện đúng.","In số tiền thanh toán với hai chữ số thập phân."],"code":"#include <stdio.h>\nint main(void) {\n    double tong = 500.0;\n    double giam = 0.0;\n    if (tong >= 500.0) {\n        giam = 0.10;\n    }\n    printf(\"Phai tra = %.2f\\n\", tong * (1.0 - giam));\n    return 0;\n}\n","output":"Phai tra = 450.00","stdin":"","analysis":["Khi T=500, điều kiện T>=500 đúng; chương trình chọn giam=0.10.","Đây là quy ước bài toán, không phải chính sách của nhà bán hàng cụ thể."],"tests":["Đổi tong=499 → 499.00.","Đổi tong=1000 → 900.00."]},"deep_dive":{"context":"if/else phù hợp điều kiện tổng quát; switch thuận lợi khi phân nhánh theo giá trị nguyên hay enum rời rạc. Mỗi nhánh switch cần quyết định rõ có break hay chủ ý rơi xuyên (fall-through).","contrast":[["if ... else if","Điều kiện có thể là bất kỳ biểu thức vô hướng hợp lệ."],["switch (x)","Chọn nhánh theo hằng số nguyên/enum case khác nhau."],["break","Thoát khỏi switch hoặc vòng lặp gần nhất."],["default","Xử lý trường hợp không khớp nhãn case nào."]],"pitfall":"Thiếu break có thể thực thi tiếp nhánh case kế tiếp. Cần phân biệt đây là chủ ý hay lỗi.","challenge":"Thiết kế menu 4 phép toán hai số, nêu điều kiện để phép chia hợp lệ và cách xử lý lựa chọn sai."},"lab_examples":[{"title":"Menu chọn chức năng bằng switch","purpose":"Chạy với lựa chọn 1, 2, 3 hoặc số khác; phân biệt break và default.","code":"#include <stdio.h>\nint main(void) {\n    int menu;\n    if (scanf(\"%d\", &menu) != 1) { puts(\"Nhap sai\"); return 1; }\n    switch (menu) {\n        case 1: puts(\"Xem diem\"); break;\n        case 2: puts(\"Sua diem\"); break;\n        case 3: puts(\"Thoat\"); break;\n        default: puts(\"Lua chon khong ton tai\");\n    }\n    return 0;\n}\n","output":"Sua diem","stdin":"2","cases":[{"stdin":"1\n","stdout":"Xem diem","exit":0},{"stdin":"2\n","stdout":"Sua diem","exit":0},{"stdin":"3\n","stdout":"Thoat","exit":0},{"stdin":"9\n","stdout":"Lua chon khong ton tai","exit":0},{"stdin":"abc\n","stdout":"Nhap sai","exit":1}],"followup":"Xóa break ở case 1, chạy với lựa chọn 1 và giải thích tác động."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M2","module_title":"Cấu trúc điều khiển và tổ chức chương trình","design_case":{"title":"Phân loại dữ liệu nhiệt độ theo mức quy ước","problem":"Phân loại dữ liệu thử: thấp khi T < 20 °C, bình thường khi 20 ≤ T ≤ 30 °C và cao khi T > 30 °C.","input":["T (°C)"],"process":["Kiểm tra lần lượt các khoảng không giao nhau"],"output":["THẤP / BÌNH THƯỜNG / CAO"],"assumptions":["Khoảng chỉ phục vụ bài học; không là tiêu chuẩn vận hành thiết bị"],"pseudocode":["Bắt đầu","Đọc T","Nếu T < 20: THẤP","Ngược lại nếu T <= 30: BÌNH THƯỜNG","Ngược lại: CAO; xuất kết quả"],"tests":[{"input":"T=19,9","expected":"THẤP","kind":"Dưới biên"},{"input":"T=20 hoặc 30","expected":"BÌNH THƯỜNG","kind":"Hai biên"},{"input":"T=30,1","expected":"CAO","kind":"Trên biên"}],"reflection":"Nếu đảo thứ tự các điều kiện, có thể xảy ra lỗi gì?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-07","number":7,"title":"Vòng lặp for, while, do while và gỡ lỗi","unit":"Điều khiển luồng","source":"Slot_05_06_07_Basic_Logics.pptx, slide 24–60","lead":"Lựa chọn cấu trúc lặp, xác định điều kiện dừng, kiểm tra bằng bảng truy vết và gỡ lỗi.","objectives":["Viết được vòng lặp for, while, do while.","Phân biệt break và continue, tránh vòng lặp vô hạn.","Dùng truy vết và dữ liệu biên để phát hiện lỗi lặp."],"sections":[{"title":"for","text":"for (khởi_tạo; điều_kiện; cập_nhật) phù hợp khi có biến điều khiển và bước tăng giảm rõ ràng. Thứ tự: khởi tạo một lần, kiểm tra điều kiện, thực hiện thân lặp, cập nhật, rồi quay lại kiểm tra.","bullets":[]},{"title":"while và do while","text":"while kiểm tra điều kiện trước thân lặp nên có thể không chạy lần nào. do {...} while (điều_kiện); kiểm tra sau nên thân lặp chạy ít nhất một lần. Lựa chọn theo yêu cầu chứ không theo thói quen.","bullets":[]},{"title":"break, continue và biến cờ","text":"break thoát khỏi vòng lặp gần nhất; continue bỏ qua phần còn lại của lần lặp hiện tại rồi chuyển sang bước tiếp theo phù hợp. Biến cờ (flag) có thể biểu diễn trạng thái đã tìm thấy hoặc yêu cầu tiếp tục, giúp chương trình có luồng thoát rõ ràng.","bullets":[]},{"title":"Gỡ lỗi và kiểm thử","text":"Kiểm tra trường hợp số lần lặp bằng 0, 1 và nhiều lần. Với lỗi không dừng, kiểm tra điều kiện dừng và biến cập nhật. OnlineGDB có chế độ Debug cho phép đặt breakpoint, theo dõi biến và chạy từng bước.","bullets":[]}],"example":{"title":"Tính tổng các số từ 1 đến n","code":"#include <stdio.h>\nint main(void) {\n    int n;\n    long long tong = 0;\n    if (scanf(\"%d\", &n) != 1 || n < 0 || n > 1000000) {\n        puts(\"n khong hop le\"); return 1;\n    }\n    for (int i = 1; i <= n; ++i) {\n        tong += i;\n    }\n    printf(\"Tong = %lld\\n\", tong);\n    return 0;\n}\n","output":"Tong = 15","stdin":"5","why":"Giới hạn n để vòng lặp và tổng có miền giá trị kiểm soát được; dùng long long để chứa tổng trong phạm vi bài.","tests":[],"trace":["Biến tổng bắt đầu từ 0 và mỗi vòng lặp bổ sung giá trị i.","Sau khi i vượt n, kết quả được in ra bằng kiểu long long; phải giới hạn n để tránh tràn."]},"mistakes":["Gán nhầm điều kiện i < n thay vì i <= n.","Quên cập nhật biến lặp.","Nhầm continue với break."],"exercises":[{"name":"Đếm chữ số","task":"Nhập số nguyên không âm, xác định số chữ số thập phân của nó bằng vòng lặp.","hint":"Riêng số 0 có một chữ số.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Lọc số chẵn","task":"Nhập n từ 1 đến 50 và in các số chẵn từ 1 đến n.","hint":"Dùng % và thử n=1,2,49,50.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Viết phiên bản dùng while (không dùng do while) để đếm chữ số; kiểm thử 0, 9, 10, 100.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Vòng lặp nào luôn chạy thân ít nhất một lần?","choices":["không có","for","do while","while"],"answer":2,"explain":"do while kiểm tra điều kiện sau thân.","rationales":["Có một cấu trúc bảo đảm ít nhất một lần là do while.","for có thể chạy 0 lần nếu điều kiện ban đầu sai.","do while kiểm tra điều kiện sau thân.","while kiểm tra điều kiện trước nên có thể chạy 0 lần."]},{"q":"break trong vòng lặp có tác dụng gì?","choices":["Kết thúc mọi hàm","Thoát khỏi vòng lặp gần nhất","Chạy lại toàn bộ","Bỏ qua một bước rồi tiếp tục"],"answer":1,"explain":"break chuyển điều khiển ra sau vòng lặp hoặc switch gần nhất.","rationales":["break chỉ thoát vòng lặp hoặc switch gần nhất, không phải toàn bộ hàm.","break chuyển điều khiển ra sau vòng lặp hoặc switch gần nhất.","break không khởi động lại vòng lặp.","Bỏ qua phần còn lại của lần lặp là continue."]},{"q":"Vòng lặp nào thực thi thân ít nhất một lần nếu chạy tới nó?","choices":["do while.","Không có dạng vòng lặp nào.","while.","for."],"answer":0,"explain":"Điều kiện được kiểm tra sau thân vòng lặp.","rationales":["Điều kiện được kiểm tra sau thân vòng lặp.","Không phù hợp: Không có dạng vòng lặp nào. Phát biểu đúng: Điều kiện được kiểm tra sau thân vòng lặp.","Không phù hợp: while. Phát biểu đúng: Điều kiện được kiểm tra sau thân vòng lặp.","Không phù hợp: for. Phát biểu đúng: Điều kiện được kiểm tra sau thân vòng lặp."]},{"q":"continue trong for có nghĩa gì?","choices":["Quay về đầu tệp C.","Kết thúc luôn vòng lặp.","Thoát khỏi hàm main.","Chuyển sang bước tiếp theo của vòng lặp hiện tại theo quy tắc for."],"answer":3,"explain":"continue không kết thúc toàn bộ vòng lặp.","rationales":["Không phù hợp: Quay về đầu tệp C. Phát biểu đúng: continue không kết thúc toàn bộ vòng lặp.","Không phù hợp: Kết thúc luôn vòng lặp. Phát biểu đúng: continue không kết thúc toàn bộ vòng lặp.","Không phù hợp: Thoát khỏi hàm main. Phát biểu đúng: continue không kết thúc toàn bộ vòng lặp.","continue không kết thúc toàn bộ vòng lặp."]},{"q":"Trường hợp n=0, do { ++count; n/=10; } while(n>0) có count bằng mấy?","choices":["0.","10.","1.","Vòng lặp vô hạn."],"answer":2,"explain":"Số 0 có một chữ số và thân do được chạy trước kiểm tra.","rationales":["Không phù hợp: 0. Phát biểu đúng: Số 0 có một chữ số và thân do được chạy trước kiểm tra.","Không phù hợp: 10. Phát biểu đúng: Số 0 có một chữ số và thân do được chạy trước kiểm tra.","Số 0 có một chữ số và thân do được chạy trước kiểm tra.","Không phù hợp: Vòng lặp vô hạn. Phát biểu đúng: Số 0 có một chữ số và thân do được chạy trước kiểm tra."]}],"summary":["for","while và do while","break, continue và biến cờ","Gỡ lỗi và kiểm thử"],"minutes":90,"syntax":[{"label":"Vòng lặp for","code":"for (int i = 1; i <= n; ++i) {\n    /* thân lặp */\n}\n","meaning":"Biểu thức khởi tạo chạy một lần; điều kiện được kiểm tra trước mỗi vòng; cập nhật chạy sau thân lặp.","watch":"Không thay đổi biến điều khiển thiếu chủ đích trong thân vòng lặp."},{"label":"Vòng lặp while và do...while","code":"while (dieu_kien) {\n    /* thân lặp */\n}\ndo {\n    /* thân lặp */\n} while (dieu_kien);\n","meaning":"while có thể thực hiện 0 lần; do...while thực hiện thân ít nhất 1 lần khi vào vòng lặp.","watch":"do...while có dấu chấm phẩy cuối câu lệnh; mọi vòng lặp phải có cơ chế tiến đến điều kiện dừng."}],"flow":{"type":"loop","caption":"Lưu đồ cộng các số lẻ từ 1 đến n","start":"i = 1; tong = 0","condition":"i ≤ n ?","body":"Nếu i lẻ: tong += i; i++","end":"In tong, kết thúc"},"worked":{"title":"Bài mẫu: tính tổng các số lẻ","problem":"Cho n=7. Dùng vòng lặp for tính tổng các số lẻ từ 1 đến n.","steps":["Đặt biến tong=0.","Duyệt i từ 1 đến n; chỉ cộng các số i lẻ.","Sau vòng lặp, in tổng."],"code":"#include <stdio.h>\nint main(void) {\n    int n = 7, tong = 0;\n    for (int i = 1; i <= n; ++i) {\n        if (i % 2 != 0) {\n            tong += i;\n        }\n    }\n    printf(\"Tong le = %d\\n\", tong);\n    return 0;\n}\n","output":"Tong le = 16","stdin":"","analysis":["Các giá trị được cộng là 1, 3, 5, 7; tổng bằng 16.","Điều kiện i<=n được kiểm tra ở mỗi vòng, i++ làm vòng lặp tiến tới kết thúc."],"tests":["n=6 → 9.","n=1 → 1."]},"deep_dive":{"context":"for phù hợp vòng lặp đếm; while kiểm tra trước và có thể chạy 0 lần; do while kiểm tra sau và luôn chạy thân ít nhất một lần. Phải xác định điều kiện dừng, giá trị thay đổi và bất biến vòng lặp.","contrast":[["for","Khai báo/bước lặp/điều kiện thường đặt cạnh nhau."],["while","Kiểm tra điều kiện trước khi vào thân."],["do while","Thực thi thân rồi mới kiểm tra điều kiện."],["continue","Bỏ phần còn lại của một vòng hiện tại; không kết thúc cả vòng lặp."]],"pitfall":"Vòng lặp không thay đổi biến điều khiển có thể không dừng; với do while cần dấu chấm phẩy sau while(điều kiện);","challenge":"Viết phiên bản dùng while (không dùng do while) để đếm chữ số; kiểm thử 0, 9, 10, 100."},"lab_examples":[{"title":"while: tổng các số 1..4","purpose":"Kiểm tra điều kiện trước mỗi lượt và tăng biến điều khiển để bảo đảm dừng.","code":"#include <stdio.h>\nint main(void) {\n    int i = 1, sum = 0;\n    while (i <= 4) {\n        sum += i;\n        ++i;\n    }\n    printf(\"Tong = %d\\n\", sum);\n    return 0;\n}\n","output":"Tong = 10","stdin":"","cases":[{"stdin":"","stdout":"Tong = 10","exit":0}],"followup":"Cho i bắt đầu từ 5: vòng while có chạy không? So sánh với do while."},{"title":"do while: đếm chữ số của số nguyên không âm","purpose":"Chú ý trường hợp n=0 có một chữ số.","code":"#include <stdio.h>\nint main(void) {\n    unsigned int n = 12040U;\n    unsigned int count = 0U;\n    do { ++count; n /= 10U; } while (n > 0U);\n    printf(\"So chu so = %u\\n\", count);\n    return 0;\n}\n","output":"So chu so = 5","stdin":"","cases":[{"stdin":"","stdout":"So chu so = 5","exit":0}],"followup":"Lý giải vì sao do while phù hợp khi n=0."},{"title":"continue: bỏ qua số lẻ","purpose":"Duyệt 1..8 và cộng các số chẵn bằng continue.","code":"#include <stdio.h>\nint main(void) {\n    int tong = 0;\n    for (int i = 1; i <= 8; ++i) {\n        if (i % 2 != 0) continue;\n        tong += i;\n    }\n    printf(\"Tong chan = %d\\n\", tong);\n    return 0;\n}\n","output":"Tong chan = 20","stdin":"","cases":[{"stdin":"","stdout":"Tong chan = 20","exit":0}],"followup":"Lập bảng i, điều kiện tiếp tục và tong ở từng bước."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"teaching_note":"Đề xuất 2 tiết: tiết 1 for/while; tiết 2 do while, break, continue và truy vết.","module":"M2","module_title":"Cấu trúc điều khiển và tổ chức chương trình","design_case":{"title":"Tính nhiệt độ trung bình của ba lần đo","problem":"Ba giá trị nhiệt độ 25 °C, 27 °C và 26 °C. Dùng vòng lặp để tính trung bình và kiểm soát số lượng mẫu.","input":["Dãy 25, 27, 26 (°C); n = 3"],"process":["Cộng n giá trị rồi chia cho n"],"output":["Giá trị trung bình 26 °C"],"assumptions":["n > 0; mỗi mẫu cùng đơn vị; giá trị trung bình không thay thế giá trị cực đại"],"pseudocode":["Bắt đầu","tong = 0; i = 0","Trong khi i < n: tong += T[i]; i++","Nếu n > 0: TB = tong / n","Xuất TB và kết thúc"],"tests":[{"input":"25,27,26","expected":"26 °C","kind":"Thông thường"},{"input":"10,10,10","expected":"10 °C","kind":"Các mẫu bằng nhau"},{"input":"n=0","expected":"Không tính trung bình","kind":"Biên sai"}],"reflection":"Tại sao cần đảm bảo n > 0 trước khi tính trung bình?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-08","number":8,"title":"Thiết kế mô-đun và hàm trong C","unit":"Hàm và mô-đun","source":"Slot_08_09_Modules_Functions.pptx, slide 5–48","lead":"Tách bài toán thành các hàm có nhiệm vụ rõ ràng, tăng tính gắn kết và giảm phụ thuộc.","objectives":["Mô tả được mô-đun, cohesion và coupling.","Khai báo prototype, định nghĩa và gọi được hàm.","Thiết kế lời giải gồm các hàm thực hiện nhiệm vụ đơn nhất."],"sections":[{"title":"Mô-đun và chia nhỏ bài toán","text":"Mô-đun là thành phần thực hiện một nhiệm vụ xác định. Trong C, hàm là một cách phân chia chương trình thành các đơn vị chức năng. Chương trình lớn thường dễ kiểm thử và bảo trì hơn khi được tách thành các hàm nhỏ theo chức năng.","bullets":[]},{"title":"Cohesion và coupling","text":"Cohesion (mức gắn kết nội bộ) cao nghĩa là các thao tác trong một hàm tập trung vào cùng nhiệm vụ. Coupling (mức phụ thuộc lẫn nhau) thấp nghĩa là các hàm trao đổi thông tin qua giao diện rõ ràng, hạn chế sử dụng trạng thái toàn cục không cần thiết.","bullets":[]},{"title":"Định nghĩa và gọi hàm","text":"Dạng cơ bản: kiểu_trả_về tên_hàm(danh_sách_tham_số) { thân_hàm }. Hàm return giá_trị dùng để trả kết quả, còn kiểu void thể hiện không trả giá trị. Các kiểu tham số và kiểu trả về phải khớp lời gọi.","bullets":[]},{"title":"Prototype và tệp header","text":"Khai báo hàm (prototype) cho phép bộ biên dịch kiểm tra kiểu lời gọi trước khi thấy phần định nghĩa. Đối với chương trình nhiều tệp, tệp header thường chứa các khai báo dùng chung và tệp .c chứa phần hiện thực.","bullets":[]}],"example":{"title":"Hàm tìm ước chung lớn nhất","code":"#include <stdio.h>\nint gcd(int a, int b);\nint main(void) {\n    int a = 24, b = 18;\n    printf(\"UCLN = %d\\n\", gcd(a, b));\n    return 0;\n}\nint gcd(int a, int b) {\n    while (b != 0) {\n        int r = a % b;\n        a = b;\n        b = r;\n    }\n    return a;\n}\n","output":"UCLN = 6","stdin":"","why":"Hàm gcd thực hiện một nhiệm vụ; main gọi hàm và trình bày kết quả. Ví dụ xét đầu vào dương.","tests":[],"trace":["Hàm gcd được gọi với hai số nguyên dương.","Mỗi lượt lặp thay cặp số bằng (b, a%b), cho đến khi số dư bằng 0; kết quả là ước chung lớn nhất."]},"mistakes":["Khai báo prototype không khớp định nghĩa.","Quên return trong hàm có kiểu trả về khác void.","Hàm ôm quá nhiều nhiệm vụ không liên quan."],"exercises":[{"name":"Tách hàm","task":"Xây dựng chương trình tính diện tích và chu vi hình tròn bằng hai hàm nhận bán kính double.","hint":"Dùng hằng PI minh họa và kiểm tra r>=0.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Tổng ước","task":"Viết hàm sumDivisors(int n) trả về tổng các ước dương của n với n>0.","hint":"Duyệt từ 1 đến n; sau đó thảo luận tối ưu thuật toán.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Chuyển bài toán điểm trung bình thành ba hàm: tính, xếp loại và hiển thị; không lặp công thức ở nhiều nơi.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Hàm có mức cohesion cao thường?","choices":["Làm nhiều nhiệm vụ không liên quan","Tập trung một nhiệm vụ rõ ràng","Không nhận tham số","Phải dùng biến toàn cục"],"answer":1,"explain":"Cohesion cao gắn với tính nhất quán mục tiêu bên trong mô-đun.","rationales":["Nhiều nhiệm vụ không liên quan là cohesion thấp.","Cohesion cao gắn với tính nhất quán mục tiêu bên trong mô-đun.","Hàm vẫn có thể gắn kết cao và nhận tham số.","Cohesion không bắt buộc dùng biến toàn cục."]},{"q":"Prototype hàm giúp?","choices":["Khai báo giao diện để kiểm tra lời gọi","Thay thế định nghĩa hàm","Cấp phát RAM cho mọi biến","Tự động chạy chương trình"],"answer":0,"explain":"Prototype cung cấp tên, kiểu tham số và kiểu trả về cho bộ biên dịch.","rationales":["Prototype cung cấp tên, kiểu tham số và kiểu trả về cho bộ biên dịch.","Định nghĩa hàm vẫn cần nếu hàm được gọi mà không do thư viện cung cấp.","Khai báo hàm không cấp phát RAM cho mọi biến.","Prototype không thực thi chương trình."]},{"q":"Nguyên mẫu hàm có vai trò chính nào?","choices":["Biến mọi biến thành toàn cục.","Tự động chạy hàm.","Thay thế toàn bộ định nghĩa.","Thông báo giao diện hàm để trình biên dịch kiểm tra lời gọi."],"answer":3,"explain":"Nguyên mẫu nêu kiểu trả về và kiểu tham số.","rationales":["Không phù hợp: Biến mọi biến thành toàn cục. Phát biểu đúng: Nguyên mẫu nêu kiểu trả về và kiểu tham số.","Không phù hợp: Tự động chạy hàm. Phát biểu đúng: Nguyên mẫu nêu kiểu trả về và kiểu tham số.","Không phù hợp: Thay thế toàn bộ định nghĩa. Phát biểu đúng: Nguyên mẫu nêu kiểu trả về và kiểu tham số.","Nguyên mẫu nêu kiểu trả về và kiểu tham số."]},{"q":"Một hàm tính diện tích tốt nên nhận gì?","choices":["Mọi biến toàn cục của chương trình.","Con trỏ FILE bắt buộc.","Các kích thước đầu vào, rồi trả kết quả tính.","Tên cửa sổ trình duyệt."],"answer":2,"explain":"Tách tính toán khỏi nhập/xuất giúp kiểm thử độc lập.","rationales":["Không phù hợp: Mọi biến toàn cục của chương trình. Phát biểu đúng: Tách tính toán khỏi nhập/xuất giúp kiểm thử độc lập.","Không phù hợp: Con trỏ FILE bắt buộc. Phát biểu đúng: Tách tính toán khỏi nhập/xuất giúp kiểm thử độc lập.","Tách tính toán khỏi nhập/xuất giúp kiểm thử độc lập.","Không phù hợp: Tên cửa sổ trình duyệt. Phát biểu đúng: Tách tính toán khỏi nhập/xuất giúp kiểm thử độc lập."]},{"q":"Hàm int square(int x){return x*x;} có thể kiểm thử độc lập khi nào?","choices":["Khi đổi kiểu trả về thành void.","Khi chọn được miền đầu vào tránh tràn và đầu ra mong đợi.","Khi bỏ tất cả return.","Khi chương trình có ít nhất 100 hàm."],"answer":1,"explain":"Cần ràng buộc miền để phép nhân int được xác định.","rationales":["Không phù hợp: Khi đổi kiểu trả về thành void. Phát biểu đúng: Cần ràng buộc miền để phép nhân int được xác định.","Cần ràng buộc miền để phép nhân int được xác định.","Không phù hợp: Khi bỏ tất cả return. Phát biểu đúng: Cần ràng buộc miền để phép nhân int được xác định.","Không phù hợp: Khi chương trình có ít nhất 100 hàm. Phát biểu đúng: Cần ràng buộc miền để phép nhân int được xác định."]}],"summary":["Mô-đun và chia nhỏ bài toán","Cohesion và coupling","Định nghĩa và gọi hàm","Prototype và tệp header"],"minutes":45,"syntax":[{"label":"Nguyên mẫu, định nghĩa và gọi hàm","code":"int chu_vi(int dai, int rong);\n\nint chu_vi(int dai, int rong) {\n    return 2 * (dai + rong);\n}\n\n/* Trong main: int p = chu_vi(8, 3); */\n","meaning":"Nguyên mẫu khai báo giao diện; định nghĩa cung cấp thân hàm; lời gọi cung cấp đối số phù hợp.","watch":"Không chép định nghĩa hàm vào bên trong một hàm khác vì C chuẩn không cho phép hàm lồng nhau."}],"flow":{"type":"sequence","caption":"Trình tự chia bài toán thành các hàm","steps":["Xác định nhiệm vụ chính","Chia thành chức năng nhỏ, độc lập","Khai báo nguyên mẫu/định nghĩa hàm","Gọi hàm trong main","Kiểm thử đầu ra từng hàm"]},"worked":{"title":"Bài mẫu: xây dựng hàm tính chu vi","problem":"Viết hàm chu_vi trả về chu vi hình chữ nhật; gọi hàm từ main với chiều dài 8 và chiều rộng 3.","steps":["Định nghĩa giao diện int chu_vi(int,int).","Hàm trả về giá trị biểu thức 2*(dai+rong).","Gọi hàm từ main và hiển thị kết quả."],"code":"#include <stdio.h>\nint chu_vi(int dai, int rong) {\n    return 2 * (dai + rong);\n}\nint main(void) {\n    printf(\"Chu vi = %d\\n\", chu_vi(8, 3));\n    return 0;\n}\n","output":"Chu vi = 22","stdin":"","analysis":["Các tham số dai, rong của hàm có phạm vi cục bộ trong hàm.","main gọi hàm để tái sử dụng thuật toán và giảm lặp lại biểu thức."],"tests":["Gọi chu_vi(10,4) trả về 28."]},"deep_dive":{"context":"Phân rã bài toán thành các hàm giúp tránh lặp mã và kiểm thử độc lập. Hàm cần giao diện rõ: tên, danh sách tham số, kiểu trả về và điều kiện áp dụng.","contrast":[["Nguyên mẫu","Giúp trình biên dịch kiểm tra lời gọi trước định nghĩa."],["Định nghĩa","Chứa thân mã để thực thi công việc."],["Lời gọi","Truyền giá trị đối số đến tham số hàm."],["Hàm thuần","Cùng đầu vào trả cùng đầu ra và không có tác dụng phụ quan sát được."]],"pitfall":"Không gộp nhập dữ liệu, tính toán và xuất kết quả vào một hàm nếu mục tiêu là kiểm thử thuật toán tính toán độc lập.","challenge":"Chuyển bài toán điểm trung bình thành ba hàm: tính, xếp loại và hiển thị; không lặp công thức ở nhiều nơi."},"lab_examples":[{"title":"Tách chương trình thành ba hàm","purpose":"Thực hiện tính toán bằng hai hàm độc lập, main chỉ điều phối.","code":"#include <stdio.h>\nint chu_vi(int d, int r) { return 2 * (d + r); }\nint dien_tich(int d, int r) { return d * r; }\nvoid hien_thi(int cv, int dt) {\n    printf(\"P=%d; S=%d\\n\", cv, dt);\n}\nint main(void) {\n    int dai = 6, rong = 4;\n    hien_thi(chu_vi(dai, rong), dien_tich(dai, rong));\n    return 0;\n}\n","output":"P=20; S=24","stdin":"","cases":[{"stdin":"","stdout":"P=20; S=24","exit":0}],"followup":"Tự viết một hàm tinh_chi_so và kiểm thử nó với giá trị cố định."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M2","module_title":"Cấu trúc điều khiển và tổ chức chương trình","design_case":{"title":"Thiết kế hàm chuyển đổi Fahrenheit sang Celsius","problem":"Viết hàm nhận nhiệt độ °F và trả về °C theo công thức C = (F − 32) × 5/9.","input":["F = 86 °F"],"process":["C = (F − 32) × 5.0 / 9.0"],"output":["C = 30 °C"],"assumptions":["Đầu vào hữu hạn; tránh chia nguyên làm sai kết quả"],"pseudocode":["Bắt đầu","Định nghĩa hàm chuyen_doi(F)","Tính C = (F-32)*5.0/9.0","Trả C","Gọi hàm và hiển thị"],"tests":[{"input":"F=32","expected":"0 °C","kind":"Điểm quy đổi"},{"input":"F=86","expected":"30 °C","kind":"Thông thường"},{"input":"F=212","expected":"100 °C","kind":"Điểm quy đổi"}],"reflection":"Hàm nên nhận tham số nào và trả kiểu dữ liệu nào?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-09","number":9,"title":"Truyền tham số, phạm vi và thời gian tồn tại","unit":"Hàm và mô-đun","source":"Slot_08_09_Modules_Functions.pptx, slide 49–71","lead":"Phân biệt truyền giá trị với thay đổi qua con trỏ, nhận diện phạm vi và thời gian tồn tại biến.","objectives":["Giải thích được C truyền đối số theo giá trị.","Phân biệt phạm vi khối với thời gian tồn tại của đối tượng.","Phân tích được các tình huống sửa biến, gọi hàm và đệ quy cơ bản."],"sections":[{"title":"Truyền tham số theo giá trị","text":"Trong C, đối số được truyền cho tham số bằng giá trị. Việc gán lại tham số trong hàm không thay đổi biến của hàm gọi. Nếu muốn sửa đối tượng của người gọi, ta có thể truyền giá trị con trỏ đến đối tượng và giải tham chiếu đúng kiểu.","bullets":[]},{"title":"Biến cục bộ và biến toàn cục","text":"Biến khai báo trong khối thông thường chỉ có phạm vi tên trong khối đó. Định danh được khai báo ở phạm vi tệp có thể được sử dụng từ các vị trí phù hợp trong đơn vị dịch; biến toàn cục nên hạn chế để tránh phụ thuộc khó kiểm thử.","bullets":[]},{"title":"Thời gian tồn tại đối tượng","text":"Đối tượng có thời gian lưu trữ tự động thường tồn tại trong thời gian thực hiện khối phù hợp; đối tượng static có thời gian lưu trữ tĩnh tồn tại suốt chương trình. Phạm vi tên và thời gian sống là hai khái niệm khác nhau, không đồng nhất.","bullets":[]},{"title":"Đệ quy","text":"Hàm đệ quy gọi chính nó, cần có trường hợp dừng và bước quy về bài toán nhỏ hơn. Đệ quy đơn giản như tính giai thừa làm rõ ngăn xếp lời gọi, nhưng cần giới hạn đầu vào để tránh tràn số hoặc tràn ngăn xếp.","bullets":[]}],"example":{"title":"Truyền giá trị không sửa biến gốc","code":"#include <stdio.h>\nvoid tang(int x) { x = x + 1; printf(\"Trong ham: %d\\n\", x); }\nint main(void) {\n    int n = 5;\n    tang(n);\n    printf(\"Trong main: %d\\n\", n);\n    return 0;\n}\n","output":"Trong ham: 6\nTrong main: 5","stdin":"","why":"Tham số x là đối tượng riêng được khởi tạo bằng giá trị n; thay đổi x không làm n đổi.","tests":[],"trace":["Tham số x của hàm là bản giá trị được truyền vào, không phải bản thân biến n.","Gán x trong hàm không làm thay đổi n tại main; đây là cơ sở để học truyền địa chỉ ở bài sau."]},"mistakes":["Cho rằng tham số int x là tham chiếu đến biến gốc.","Trả địa chỉ biến cục bộ tự động từ hàm rồi sử dụng.","Nhầm phạm vi tên với vòng đời vùng nhớ."],"exercises":[{"name":"Thử truyền giá trị","task":"Viết ham swapBad(int a,int b), giải thích vì sao không đổi biến ở main.","hint":"Tự theo dõi bảng biến theo từng hàm.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Đệ quy có giới hạn","task":"Viết hàm factorial(int n) trả long long cho 0<=n<=20; giải thích điều kiện dừng.","hint":"Sử dụng 0! = 1 và kiểm thử n=0,1,20.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Viết hàm hoan_doi(int *a,int *b), giải thích rõ giá trị con trỏ truyền vào và đối tượng bị thay đổi.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"C truyền tham số kiểu int bằng cơ chế nào?","choices":["Giá trị","Không hỗ trợ","Con trỏ ngầm","Tham chiếu ngầm"],"answer":0,"explain":"C truyền giá trị; con trỏ cũng được truyền bằng giá trị con trỏ.","rationales":["C truyền giá trị; con trỏ cũng được truyền bằng giá trị con trỏ.","C có hỗ trợ tham số kiểu int.","Muốn thay đổi đối tượng qua địa chỉ cần truyền con trỏ tường minh.","C không có cơ chế truyền tham chiếu ngầm cho tham số int."]},{"q":"Trong ví dụ tăng x, n trong main thay đổi thế nào?","choices":["Thành 6","Thành 0","Không xác định","Vẫn 5"],"answer":3,"explain":"Gán x không thay đổi đối tượng n trong main.","rationales":["Thay đổi bản sao x không làm n tăng.","Không có câu lệnh nào gán n bằng 0.","n đã được khởi tạo 5 và không bị sửa, nên không bất định.","Gán x không thay đổi đối tượng n trong main."]},{"q":"Trong C, đối số truyền vào hàm được truyền theo cơ chế nào?","choices":["Theo địa chỉ vật lý CPU.","Theo tham chiếu C++ bắt buộc.","Theo giá trị.","Theo tên của biến."],"answer":2,"explain":"Giá trị đối số dùng khởi tạo tham số riêng của hàm.","rationales":["Không phù hợp: Theo địa chỉ vật lý CPU. Phát biểu đúng: Giá trị đối số dùng khởi tạo tham số riêng của hàm.","Không phù hợp: Theo tham chiếu C++ bắt buộc. Phát biểu đúng: Giá trị đối số dùng khởi tạo tham số riêng của hàm.","Giá trị đối số dùng khởi tạo tham số riêng của hàm.","Không phù hợp: Theo tên của biến. Phát biểu đúng: Giá trị đối số dùng khởi tạo tham số riêng của hàm."]},{"q":"Biến static cục bộ khác biến tự động cục bộ ở điểm nào?","choices":["Có phạm vi toàn bộ chương trình bắt buộc.","Có thời gian lưu trữ tĩnh nhưng phạm vi tên vẫn ở khối.","Không được khởi tạo.","Luôn nằm trên stack."],"answer":1,"explain":"Đối tượng tồn tại qua nhiều lời gọi, dù tên vẫn chỉ trong khối.","rationales":["Không phù hợp: Có phạm vi toàn bộ chương trình bắt buộc. Phát biểu đúng: Đối tượng tồn tại qua nhiều lời gọi, dù tên vẫn chỉ trong khối.","Đối tượng tồn tại qua nhiều lời gọi, dù tên vẫn chỉ trong khối.","Không phù hợp: Không được khởi tạo. Phát biểu đúng: Đối tượng tồn tại qua nhiều lời gọi, dù tên vẫn chỉ trong khối.","Không phù hợp: Luôn nằm trên stack. Phát biểu đúng: Đối tượng tồn tại qua nhiều lời gọi, dù tên vẫn chỉ trong khối."]},{"q":"Với n=5, gọi gt(n) đệ quy đúng có giá trị gì?","choices":["120.","25.","15.","0."],"answer":0,"explain":"5! = 5×4×3×2×1.","rationales":["5! = 5×4×3×2×1.","Không phù hợp: 25. Phát biểu đúng: 5! = 5×4×3×2×1.","Không phù hợp: 15. Phát biểu đúng: 5! = 5×4×3×2×1.","Không phù hợp: 0. Phát biểu đúng: 5! = 5×4×3×2×1."]}],"summary":["Truyền tham số theo giá trị","Biến cục bộ và biến toàn cục","Thời gian tồn tại đối tượng","Đệ quy"],"minutes":45,"syntax":[{"label":"Truyền theo giá trị","code":"void tang(int x) {\n    x = x + 1;\n}\n/* tang(a) không tự thay đổi biến a ở hàm gọi. */\n","meaning":"C truyền đối số theo giá trị; tham số nhận một bản giá trị, nên gán lại tham số không cập nhật biến đối số.","watch":"Để thay đổi một đối tượng ở nơi gọi, truyền địa chỉ bằng con trỏ phù hợp (học ở Slot 10)."},{"label":"Đệ quy có điều kiện dừng","code":"unsigned long long gt(unsigned n) {\n    if (n <= 1U) return 1ULL;\n    return (unsigned long long)n * gt(n - 1U);\n}\n","meaning":"Đệ quy là hàm gọi lại chính nó; phải có điều kiện cơ sở và chuỗi lời gọi tiến tới điều kiện đó.","watch":"Giai thừa tăng nhanh; ví dụ cần giới hạn n<=20 trên unsigned long long ít nhất 64 bit."}],"flow":{"type":"decision","caption":"Trình tự đệ quy tính giai thừa n!","start":"Gọi gt(n)","condition":"n ≤ 1 ?","yes":"Trả về 1","no":"n × gt(n−1)","end":"Trả kết quả cho lời gọi"},"worked":{"title":"Bài mẫu: tính giai thừa với hàm đệ quy","problem":"Tính 5! bằng hàm đệ quy có điều kiện cơ sở; giới hạn n trong [0,20].","steps":["Nếu n<=1, trả về 1.","Nếu n>1, trả về n × gt(n-1).","Trong main gọi gt(5) và in bằng %llu."],"code":"#include <stdio.h>\nunsigned long long gt(unsigned n) {\n    if (n <= 1U) return 1ULL;\n    return (unsigned long long)n * gt(n - 1U);\n}\nint main(void) {\n    unsigned n = 5;\n    printf(\"Giai thua = %llu\\n\", gt(n));\n    return 0;\n}\n","output":"Giai thua = 120","stdin":"","analysis":["Các lời gọi lần lượt gt(5), gt(4), gt(3), gt(2), gt(1).","Giá trị được nhân khi quay lui: 2, 6, 24, 120."],"tests":["n=0 → 1.","n=4 → 24."]},"deep_dive":{"context":"Trong C, đối số được truyền theo giá trị. Phạm vi tên (scope) quyết định vị trí truy cập tên; thời gian lưu trữ (storage duration) quyết định thời gian đối tượng tồn tại. Hai khái niệm này không đồng nhất.","contrast":[["Biến tự động trong khối","Thông thường tồn tại trong lần vào/ra khối, không tự khởi tạo về 0."],["Biến static cục bộ","Chỉ truy cập trong khối nhưng tồn tại suốt thời gian thực thi."],["Đối tượng phạm vi tệp","Khai báo ngoài các hàm, có thời gian lưu trữ tĩnh."],["Tham số hàm","Nhận bản sao giá trị đối số khi gọi."]],"pitfall":"Không kết luận rằng “truyền một con trỏ” là truyền theo tham chiếu của C++; bản thân giá trị con trỏ cũng được sao chép khi gọi hàm.","challenge":"Viết hàm hoan_doi(int *a,int *b), giải thích rõ giá trị con trỏ truyền vào và đối tượng bị thay đổi."},"lab_examples":[{"title":"Biến local và static qua hai lời gọi","purpose":"Kiểm chứng bằng đầu ra tại mỗi lần gọi cùng hàm.","code":"#include <stdio.h>\nvoid dem(void) {\n    int local = 0;\n    static int persistent = 0;\n    ++local;\n    ++persistent;\n    printf(\"local=%d; static=%d\\n\", local, persistent);\n}\nint main(void) {\n    dem();\n    dem();\n    return 0;\n}\n","output":"local=1; static=1\nlocal=1; static=2","stdin":"","cases":[{"stdin":"","stdout":"local=1; static=1\nlocal=1; static=2","exit":0}],"followup":"Giải thích vì sao local không tăng qua hai lời gọi nhưng persistent thì có."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M2","module_title":"Cấu trúc điều khiển và tổ chức chương trình","design_case":{"title":"Phân biệt tham số truyền theo giá trị","problem":"Giả sử hàm nhận một giá trị đặt 1200 vòng/phút rồi nhân đôi tham số cục bộ. Quan sát biến gốc có thay đổi không.","input":["Biến gốc 1200; hệ số 2"],"process":["Truyền bản sao của giá trị vào hàm"],"output":["Tham số trong hàm 2400; biến gốc vẫn 1200"],"assumptions":["Mô phỏng giá trị đặt, không đo tốc độ thực của động cơ"],"pseudocode":["Bắt đầu","Khởi tạo toc_do_dat = 1200","Gọi hàm với toc_do_dat","Trong hàm, nhân tham số cục bộ với 2","Đối chiếu biến trước/sau lời gọi"],"tests":[{"input":"Gốc=1200","expected":"Gốc không đổi nếu chỉ sửa tham số","kind":"Truyền giá trị"},{"input":"Tham số=1200 ×2","expected":"2400 bên trong hàm","kind":"Nội bộ"},{"input":"Gốc=0","expected":"Vẫn 0 nếu không sửa qua con trỏ","kind":"Biên"}],"reflection":"Khi nào cần truyền địa chỉ của biến để hàm có thể cập nhật giá trị?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-10","number":10,"title":"Con trỏ và cấp phát bộ nhớ động","unit":"Con trỏ và bộ nhớ","source":"Slot_10_Pointers.pptx, slide 3–35","lead":"Hiểu địa chỉ, phép lấy địa chỉ, giải tham chiếu và quản lý bộ nhớ đúng vòng đời.","objectives":["Khai báo con trỏ, sử dụng & và * đúng kiểu.","Dùng con trỏ để thay đổi giá trị qua tham số hàm.","Cấp phát và giải phóng bộ nhớ động, xử lý lỗi NULL."],"sections":[{"title":"Khái niệm và toán tử","text":"Con trỏ là giá trị dùng để chỉ đến một đối tượng hoặc hàm phù hợp; biến con trỏ chứa giá trị con trỏ. &x lấy địa chỉ x; *p giải tham chiếu p khi p hợp lệ. Đọc/ghi qua con trỏ NULL hoặc con trỏ treo dẫn đến hành vi không xác định.","bullets":[]},{"title":"Số học con trỏ","text":"Với con trỏ trỏ vào phần tử của mảng, p+1 chỉ tới phần tử kế tiếp, không nhất thiết tăng địa chỉ đúng một byte. Phép toán và so sánh thứ tự con trỏ chỉ có miền hợp lệ nhất định, điển hình là các phần tử trong cùng mảng và vị trí one-past.","bullets":[]},{"title":"Con trỏ làm tham số hàm","text":"Vì C truyền đối số theo giá trị, có thể truyền địa chỉ để hàm truy cập đối tượng của hàm gọi. Ví dụ swap(&a, &b) cho phép đổi giá trị qua *pa và *pb. Hàm vẫn nhận bản sao của hai giá trị con trỏ.","bullets":[]},{"title":"malloc, calloc, realloc, free","text":"malloc(n) xin n byte chưa khởi tạo, calloc cấp phát và đặt các byte về 0, realloc thay đổi kích thước vùng nhớ, free giải phóng. Luôn kiểm tra NULL sau cấp phát; với realloc cần dùng biến con trỏ tạm để không mất vùng nhớ cũ nếu thất bại. Không sử dụng vùng nhớ sau free.","bullets":[]},{"title":"Tránh lỗi bảo mật bộ nhớ","text":"Không truy cập ngoài giới hạn mảng, không giải tham chiếu con trỏ chưa khởi tạo, không free hai lần, không sử dụng địa chỉ biến cục bộ sau khi biến hết vòng đời. Khi đếm số phần tử, ưu tiên size_t và tính toán kích thước có kiểm tra.","bullets":[]}],"example":{"title":"Hoán đổi bằng con trỏ","code":"#include <stdio.h>\nvoid hoan_doi(int *a, int *b) {\n    int tam = *a;\n    *a = *b;\n    *b = tam;\n}\nint main(void) {\n    int x = 2, y = 9;\n    hoan_doi(&x, &y);\n    printf(\"x=%d y=%d\\n\", x, y);\n    return 0;\n}\n","output":"x=9 y=2","stdin":"","why":"Chỉ giải tham chiếu các địa chỉ hợp lệ của x và y; sau hàm, giá trị hai biến đã hoán đổi.","tests":[],"trace":["Dấu & lấy địa chỉ x và y để truyền cho hàm.","Hàm truy cập hai đối tượng qua con trỏ hợp lệ và hoán đổi giá trị bằng biến tạm."]},"mistakes":["Nhầm &x và *x.","Không kiểm tra kết quả malloc.","Truy cập vùng nhớ đã free."],"exercises":[{"name":"Tính tổng mảng động","task":"Đọc n từ 1 đến 100; cấp phát n số int bằng malloc, nhập, tính tổng, free.","hint":"Kiểm tra n và cấp phát trước khi dùng; chú ý phép nhân kích thước.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Tăng qua địa chỉ","task":"Viết hàm void increase(int *p) tăng giá trị tại địa chỉ hợp lệ.","hint":"Truyền &a và dùng *p += 1.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Vẽ sơ đồ bộ nhớ gồm hai biến a,b và một con trỏ p=&a, mô tả các trạng thái trước/sau *p=10.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Phép &x nhận được gì?","choices":["Giá trị x+1","Kích thước x","Giá trị của con trỏ x","Địa chỉ của x"],"answer":3,"explain":"& áp dụng cho đối tượng phù hợp cho địa chỉ của đối tượng.","rationales":["&x không thực hiện phép tăng.","sizeof mới trả kích thước lưu trữ.","x có kiểu int ở ví dụ nên không có giá trị con trỏ cần lấy.","& áp dụng cho đối tượng phù hợp cho địa chỉ của đối tượng."]},{"q":"Sau free(p), phát biểu nào đúng?","choices":["p tự động bằng NULL","Mảng tự nhân đôi","Vùng đã giải phóng không được truy cập qua p","Có thể tiếp tục dùng *p"],"answer":2,"explain":"free không tự động gán NULL cho biến p; dereference sau giải phóng là không hợp lệ.","rationales":["free không tự gán NULL vào biến p.","free không tự làm mảng nhân đôi.","free không tự động gán NULL cho biến p; dereference sau giải phóng là không hợp lệ.","Sau free, vùng nhớ không còn hợp lệ để giải tham chiếu."]},{"q":"Sau malloc, điều cần kiểm tra trước khi giải tham chiếu là gì?","choices":["Luôn gọi realloc ngay.","Con trỏ trả về khác NULL.","Kiểm tra sizeof(int)==4.","Đọc a[0] để thử trước."],"answer":1,"explain":"Cấp phát có thể thất bại và trả NULL.","rationales":["Không phù hợp: Luôn gọi realloc ngay. Phát biểu đúng: Cấp phát có thể thất bại và trả NULL.","Cấp phát có thể thất bại và trả NULL.","Không phù hợp: Kiểm tra sizeof(int)==4. Phát biểu đúng: Cấp phát có thể thất bại và trả NULL.","Không phù hợp: Đọc a[0] để thử trước. Phát biểu đúng: Cấp phát có thể thất bại và trả NULL."]},{"q":"Nếu realloc(p, n) thất bại, điều gì xảy ra với vùng cũ?","choices":["Vùng cũ vẫn còn được cấp phát, p vẫn cần được giữ để free.","Vùng cũ tự giải phóng.","Mọi phần tử được đặt thành 0.","p bắt buộc thành NULL."],"answer":0,"explain":"Không được làm mất con trỏ cũ khi realloc trả NULL.","rationales":["Không được làm mất con trỏ cũ khi realloc trả NULL.","Không phù hợp: Vùng cũ tự giải phóng. Phát biểu đúng: Không được làm mất con trỏ cũ khi realloc trả NULL.","Không phù hợp: Mọi phần tử được đặt thành 0. Phát biểu đúng: Không được làm mất con trỏ cũ khi realloc trả NULL.","Không phù hợp: p bắt buộc thành NULL. Phát biểu đúng: Không được làm mất con trỏ cũ khi realloc trả NULL."]},{"q":"Sau free(p), phát biểu nào đúng?","choices":["Tất cả con trỏ tự động thành NULL.","free giải phóng cả biến cục bộ của main.","Có thể đọc a[0] một lần để kiểm tra.","Không được truy cập lại vùng đã giải phóng qua p."],"answer":3,"explain":"Use-after-free gây hành vi không xác định.","rationales":["Không phù hợp: Tất cả con trỏ tự động thành NULL. Phát biểu đúng: Use-after-free gây hành vi không xác định.","Không phù hợp: free giải phóng cả biến cục bộ của main. Phát biểu đúng: Use-after-free gây hành vi không xác định.","Không phù hợp: Có thể đọc a[0] một lần để kiểm tra. Phát biểu đúng: Use-after-free gây hành vi không xác định.","Use-after-free gây hành vi không xác định."]}],"summary":["Khái niệm và toán tử","Số học con trỏ","Con trỏ làm tham số hàm","malloc, calloc, realloc, free","Tránh lỗi bảo mật bộ nhớ"],"minutes":45,"syntax":[{"label":"Khai báo và giải tham chiếu con trỏ","code":"int x = 5;\nint *p = &x;\n*p = 8;\n","meaning":"p chứa địa chỉ đối tượng int; &x lấy địa chỉ, *p truy cập giá trị tại địa chỉ hợp lệ.","watch":"Không giải tham chiếu con trỏ chưa khởi tạo hoặc con trỏ NULL."},{"label":"Cấp phát và giải phóng","code":"size_t n = 4;\nint *a = malloc(n * sizeof *a);\nif (a == NULL) { /* xử lý thất bại */ }\n/* chỉ dùng a khi khác NULL */\nfree(a);\na = NULL;\n","meaning":"malloc yêu cầu vùng nhớ chứa n phần tử int; free giải phóng vùng cấp phát; gán NULL giúp tránh dùng lại tên con trỏ đó.","watch":"Đoạn minh họa cần đặt trong hàm và thêm <stdlib.h>; phải xét nguy cơ tràn khi tính n*sizeof *a với n không tin cậy."}],"flow":{"type":"decision","caption":"Cấp phát mảng động và kiểm tra kết quả","start":"Yêu cầu cấp phát n phần tử","condition":"malloc trả NULL?","yes":"Thông báo thất bại","no":"Dùng mảng; free(a)","end":"Kết thúc"},"worked":{"title":"Bài mẫu: trung bình của mảng động","problem":"Cấp phát mảng động 4 số nguyên, tính trung bình cộng và giải phóng bộ nhớ.","steps":["Cấp phát n × sizeof(int) với n=4; kiểm tra NULL.","Gán các phần tử 2, 4, 6, 8 và tính tổng.","In trung bình bằng double rồi free vùng nhớ."],"code":"#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    size_t n = 4;\n    int *a = malloc(n * sizeof *a);\n    if (a == NULL) {\n        puts(\"Khong du bo nho\");\n        return 1;\n    }\n    for (size_t i = 0; i < n; ++i) a[i] = (int)(2 * (i + 1));\n    int tong = 0;\n    for (size_t i = 0; i < n; ++i) tong += a[i];\n    printf(\"Trung binh = %.2f\\n\", (double)tong / n);\n    free(a);\n    return 0;\n}\n","output":"Trung binh = 5.00","stdin":"","analysis":["Sau malloc phải kiểm tra vì cấp phát có thể thất bại.","free phải được thực hiện khi không còn sử dụng vùng nhớ; không dùng a[i] sau free."],"tests":["Đổi n=2 → mảng 2,4 có trung bình 3.00."]},"deep_dive":{"context":"Con trỏ chứa giá trị tham chiếu đến đối tượng; toán tử & lấy địa chỉ, * giải tham chiếu khi con trỏ hợp lệ. Bộ nhớ động yêu cầu cân bằng giữa cấp phát, kiểm tra, sử dụng và giải phóng.","contrast":[["NULL","Không trỏ tới đối tượng; không được giải tham chiếu."],["malloc","Cấp phát một vùng nhớ không khởi tạo, có thể thất bại."],["realloc","Thay đổi kích thước, có thể chuyển vị trí vùng nhớ."],["free","Giải phóng vùng cấp phát; mọi con trỏ còn trỏ vùng cũ trở nên không hợp lệ cho truy cập."]],"pitfall":"Không viết p=realloc(p,n) trực tiếp khi cần giữ vùng cũ nếu thất bại; nên lưu kết quả vào con trỏ tạm trước.","challenge":"Vẽ sơ đồ bộ nhớ gồm hai biến a,b và một con trỏ p=&a, mô tả các trạng thái trước/sau *p=10."},"lab_examples":[{"title":"Mở rộng mảng bằng realloc an toàn","purpose":"Giữ con trỏ ban đầu cho tới khi realloc thành công.","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <stdint.h>\nint main(void) {\n    size_t n = 2U, bigger = 4U;\n    int *a = malloc(n * sizeof *a);\n    if (a == NULL) return 1;\n    a[0] = 3; a[1] = 5;\n    if (bigger > SIZE_MAX / sizeof *a) { free(a); return 1; }\n    int *tmp = realloc(a, bigger * sizeof *a);\n    if (tmp == NULL) { free(a); return 1; }\n    a = tmp;\n    a[2] = 7; a[3] = 9;\n    printf(\"Tong=%d\\n\", a[0] + a[1] + a[2] + a[3]);\n    free(a);\n    a = NULL;\n    return 0;\n}\n","output":"Tong=24","stdin":"","cases":[{"stdin":"","stdout":"Tong=24","exit":0}],"followup":"Giải thích thứ tự cập nhật con trỏ và vì sao a[2],a[3] chỉ được ghi sau realloc thành công."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"teaching_note":"Bài này giới thiệu con trỏ trước mảng; cần dùng minh họa địa chỉ–giá trị và có thể dạy cấp phát sau bài mảng.","module":"M3","module_title":"Bộ nhớ, thư viện và nhập dữ liệu an toàn","design_case":{"title":"Cấp phát mảng nhiệt độ có độ dài xác định khi chạy","problem":"Người dùng nhập số mẫu n. Chương trình cấp phát đủ bộ nhớ cho n giá trị kiểu double, kiểm tra và giải phóng.","input":["n là số mẫu nguyên dương"],"process":["Kiểm tra n, kiểm tra tràn kích thước; malloc; kiểm tra NULL; free"],"output":["Vùng nhớ hợp lệ hoặc thông báo thất bại"],"assumptions":["n=0 không đáp ứng đặc tả; cấp phát thành công không bảo đảm phần tử được khởi tạo"],"pseudocode":["Bắt đầu","Đọc n, xác thực n > 0","Kiểm tra n không vượt SIZE_MAX/sizeof(double)","Cấp phát, kiểm tra NULL","Sử dụng an toàn; free; kết thúc"],"tests":[{"input":"n=4","expected":"Có không gian cho 4 double nếu cấp phát thành công","kind":"Thông thường"},{"input":"n=0","expected":"Từ chối","kind":"Không hợp lệ"},{"input":"n quá lớn","expected":"Phát hiện tràn kích thước hoặc thất bại cấp phát","kind":"An toàn bộ nhớ"}],"reflection":"Vì sao phải dùng con trỏ tạm khi gọi realloc?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-11","number":11,"title":"Thư viện chuẩn: stdlib.h, math.h, time.h, ctype.h","unit":"Thư viện và nhập xuất","source":"Slot_11_12_Libraries.pptx, slide 2–30","lead":"Khai thác các hàm thư viện được chuẩn hóa thay vì tự viết lại các thao tác thông dụng.","objectives":["Chọn được header tương ứng với một hàm thư viện C.","Sử dụng các hàm toán, phân loại ký tự và số giả ngẫu nhiên.","Phân biệt hàm chuẩn C với phần mở rộng của compiler."],"sections":[{"title":"Thư viện chuẩn C","text":"Các header chuẩn cung cấp khai báo hàm, macro và kiểu dữ liệu. stdlib.h chứa abs, malloc, rand, atoi; math.h chứa sqrt, pow, fabs; time.h cung cấp time và một số thao tác thời gian; ctype.h hỗ trợ phân loại và chuyển đổi chữ cái.","bullets":[]},{"title":"Hàm toán học","text":"sqrt(x) trả căn bậc hai cho đầu vào trong miền xác định, pow(x,y) tính lũy thừa theo quy tắc dấu phẩy động. Tham số và kết quả thường thuộc double; trong một số môi trường cần liên kết thư viện toán bằng -lm (thao tác do trình biên dịch thực hiện).","bullets":[]},{"title":"Ký tự và phân loại","text":"isdigit, isalpha, isspace, tolower, toupper nhận EOF hoặc giá trị biểu diễn được dưới dạng unsigned char. Khi dùng một biến char có thể âm, ép sang (unsigned char) trước khi gọi để tránh hành vi không xác định. Phạm vi ký tự được phân loại phụ thuộc locale.","bullets":[]},{"title":"Số giả ngẫu nhiên","text":"rand trả số giả ngẫu nhiên trong đoạn 0..RAND_MAX. srand đặt seed; srand((unsigned)time(NULL)) tạo seed thay đổi theo thời gian nhưng không đảm bảo không trùng. rand() % n gây thiên lệch phân phối trong nhiều trường hợp; chỉ dùng để thực hành cơ bản, không cho mục đích bảo mật.","bullets":[]}],"example":{"title":"Kiểm tra chữ số và căn bậc hai","code":"#include <stdio.h>\n#include <ctype.h>\n#include <math.h>\nint main(void) {\n    unsigned char ky_tu = '7';\n    double x = 81.0;\n    printf(\"La chu so: %d\\n\", isdigit(ky_tu) != 0);\n    printf(\"Can bac hai: %.1f\\n\", sqrt(x));\n    return 0;\n}\n","output":"La chu so: 1\nCan bac hai: 9.0","stdin":"","why":"Bản minh họa dùng đầu vào số thực không âm và ký tự ASCII; khi gcc local không tự link libm cần thêm -lm.","tests":[],"trace":["Các hàm stdlib.h, math.h, ctype.h được gọi với dữ liệu phù hợp.","Sqrt nhận số không âm trong ví dụ; isdigit nhận giá trị chuyển sang unsigned char; khi dùng GCC thường cần -lm để liên kết math.h."]},"mistakes":["Dùng hàm không có khai báo từ header thích hợp.","Gọi sqrt với số âm và kỳ vọng kết quả double hữu hạn.","Dùng rand để tạo khóa bảo mật."],"exercises":[{"name":"Kiểm tra ký tự","task":"Nhập một ký tự và phân loại chữ, số, ký tự khác bằng ctype.h.","hint":"Chú ý giá trị trả về của getchar có kiểu int.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Hàm toán","task":"Nhập a>=0, tính sqrt(a) và pow(a,2).","hint":"Dùng double; xử lý đầu vào không hợp lệ.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Cho 4 yêu cầu: căn bậc hai, ký tự số, thời gian hiện tại, cấp phát động; ghép đúng với thư viện chuẩn và nêu điều kiện an toàn.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Header chuẩn nào khai báo sqrt?","choices":["ctype.h","string.h","math.h","stdio.h"],"answer":2,"explain":"Hàm sqrt được khai báo trong math.h.","rationales":["ctype.h cung cấp các hàm phân loại ký tự.","string.h khai báo các hàm thao tác chuỗi.","Hàm sqrt được khai báo trong math.h.","stdio.h khai báo chức năng nhập xuất chuẩn."]},{"q":"rand có phù hợp sinh khóa bảo mật không?","choices":["Có, luôn an toàn","Không, đây là bộ tạo số giả ngẫu nhiên không dành cho bảo mật","Chỉ khi n>100","Chỉ khi không gọi srand"],"answer":1,"explain":"Không dùng rand cho mục đích mật mã.","rationales":["rand không bảo đảm tính khó dự đoán mật mã.","Không dùng rand cho mục đích mật mã.","Độ lớn n không biến rand thành công cụ bảo mật.","Bỏ srand cũng không làm rand an toàn hơn."]},{"q":"sqrt cần include tệp tiêu đề nào?","choices":["math.h.","stdio.h duy nhất.","ctype.h.","string.h."],"answer":0,"explain":"math.h khai báo sqrt; khi dùng GCC có thể cần liên kết libm.","rationales":["math.h khai báo sqrt; khi dùng GCC có thể cần liên kết libm.","Không phù hợp: stdio.h duy nhất. Phát biểu đúng: math.h khai báo sqrt; khi dùng GCC có thể cần liên kết libm.","Không phù hợp: ctype.h. Phát biểu đúng: math.h khai báo sqrt; khi dùng GCC có thể cần liên kết libm.","Không phù hợp: string.h. Phát biểu đúng: math.h khai báo sqrt; khi dùng GCC có thể cần liên kết libm."]},{"q":"Kết quả của rand() % 6 có thể có vấn đề gì?","choices":["Đây là nguồn mật mã an toàn.","rand không có trong C chuẩn.","Kết quả luôn từ 1 đến 6.","Phân bố lệch nếu miền RAND_MAX+1 không chia hết cho 6."],"answer":3,"explain":"Phép lấy dư không luôn cho phân bố đều tuyệt đối.","rationales":["Không phù hợp: Đây là nguồn mật mã an toàn. Phát biểu đúng: Phép lấy dư không luôn cho phân bố đều tuyệt đối.","Không phù hợp: rand không có trong C chuẩn. Phát biểu đúng: Phép lấy dư không luôn cho phân bố đều tuyệt đối.","Không phù hợp: Kết quả luôn từ 1 đến 6. Phát biểu đúng: Phép lấy dư không luôn cho phân bố đều tuyệt đối.","Phép lấy dư không luôn cho phân bố đều tuyệt đối."]},{"q":"Khi dùng isalpha với char có thể âm, nên làm gì?","choices":["Không bao giờ dùng ctype.h.","Ép sang double.","Ép về unsigned char trước khi truyền.","Luôn truyền âm để kiểm tra."],"answer":2,"explain":"Các hàm ctype nhận EOF hoặc giá trị có thể biểu diễn bởi unsigned char.","rationales":["Không phù hợp: Không bao giờ dùng ctype.h. Phát biểu đúng: Các hàm ctype nhận EOF hoặc giá trị có thể biểu diễn bởi unsigned char.","Không phù hợp: Ép sang double. Phát biểu đúng: Các hàm ctype nhận EOF hoặc giá trị có thể biểu diễn bởi unsigned char.","Các hàm ctype nhận EOF hoặc giá trị có thể biểu diễn bởi unsigned char.","Không phù hợp: Luôn truyền âm để kiểm tra. Phát biểu đúng: Các hàm ctype nhận EOF hoặc giá trị có thể biểu diễn bởi unsigned char."]}],"summary":["Thư viện chuẩn C","Hàm toán học","Ký tự và phân loại","Số giả ngẫu nhiên"],"minutes":45,"syntax":[{"label":"Gọi hàm thuộc thư viện chuẩn","code":"#include <ctype.h>\n#include <math.h>\n#include <stdlib.h>\n#include <time.h>\n/* abs(-5), sqrt(9.0), isdigit((unsigned char)c), time(NULL) */\n","meaning":"Header tương ứng cung cấp khai báo hàm và các kiểu/hằng liên quan; sqrt trả về double.","watch":"Trước khi gọi hàm ctype.h, đối số phải là EOF hoặc giá trị có thể biểu diễn bằng unsigned char."},{"label":"Sinh số giả ngẫu nhiên","code":"srand((unsigned)time(NULL));\nint x = rand();\n","meaning":"srand khởi tạo trạng thái của bộ sinh; rand trả số giả ngẫu nhiên trong [0,RAND_MAX].","watch":"Không dùng rand cho mục đích bảo mật; khi kiểm thử nên dùng seed cố định để có thể lặp lại."}],"flow":{"type":"sequence","caption":"Chuỗi xử lý trong bài 11: Tính độ lớn của sai lệch đo bằng thư viện toán học","steps":["Đọc hai số đo thực","Tính delta = fabs(Tdo − Tthamchieu)","In delta cùng đơn vị","Kết thúc"]},"worked":{"title":"Bài mẫu: phân loại ký tự","problem":"Xét ký tự 7; kiểm tra có phải chữ số thập phân theo ctype.h hay không.","steps":["Sử dụng hàm isdigit với đối số được chuyển sang unsigned char.","Chọn thông báo tùy theo kết quả khác 0 hay bằng 0.","In kết quả bằng puts."],"code":"#include <stdio.h>\n#include <ctype.h>\nint main(void) {\n    char c = '7';\n    if (isdigit((unsigned char)c)) {\n        puts(\"La chu so\");\n    } else {\n        puts(\"Khong phai chu so\");\n    }\n    return 0;\n}\n","output":"La chu so","stdin":"","analysis":["isdigit trả khác 0 khi ký tự thuộc lớp chữ số thập phân trong locale đang dùng.","Ép kiểu unsigned char là thao tác an toàn cho giá trị char có thể âm."],"tests":["Thay c='A' → Khong phai chu so."]},"deep_dive":{"context":"Thư viện chuẩn cung cấp nhiều nhóm chức năng; người lập trình phải biết chọn header và kiểm tra miền áp dụng. Hàm sinh số giả ngẫu nhiên rand không phù hợp để tạo mật khẩu hoặc khóa bảo mật.","contrast":[["stdlib.h","Cấp phát, chuyển đổi, xử lý khác và rand/srand."],["math.h","Hàm toán học như sqrt và pow, cần miền áp dụng phù hợp."],["ctype.h","Phân loại hoặc chuyển đổi ký tự theo byte/locale."],["time.h","Các kiểu và hàm làm việc với thời gian."]],"pitfall":"rand() % n có thể tạo phân bố không đều do modulo bias; không dùng kết quả của rand cho bảo mật.","challenge":"Cho 4 yêu cầu: căn bậc hai, ký tự số, thời gian hiện tại, cấp phát động; ghép đúng với thư viện chuẩn và nêu điều kiện an toàn."},"lab_examples":[{"title":"Sinh số giả ngẫu nhiên và kiểm tra miền","purpose":"Đặt seed cố định để thuận tiện trình diễn; kết quả cụ thể vẫn phụ thuộc triển khai C.","code":"#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    srand(1U);\n    int x = rand();\n    printf(\"Thuoc [0,RAND_MAX]: %s\\n\", (x >= 0 && x <= RAND_MAX) ? \"co\" : \"khong\");\n    return 0;\n}\n","output":"Thuoc [0,RAND_MAX]: co","stdin":"","cases":[{"stdin":"","stdout":"Thuoc [0,RAND_MAX]: co","exit":0}],"followup":"Đổi seed thành (unsigned)time(NULL) (nhớ thêm time.h); so sánh các lần chạy."},{"title":"Kiểm tra miền sqrt","purpose":"Không lấy căn bậc hai thực của số âm khi chưa xác định cách xử lý.","code":"#include <stdio.h>\n#include <math.h>\nint main(void) {\n    double x = -4.0;\n    if (x < 0.0) puts(\"Ngoai mien can bac hai thuc\");\n    else printf(\"sqrt=%.2f\\n\", sqrt(x));\n    return 0;\n}\n","output":"Ngoai mien can bac hai thuc","stdin":"","cases":[{"stdin":"","stdout":"Ngoai mien can bac hai thuc","exit":0}],"followup":""}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M3","module_title":"Bộ nhớ, thư viện và nhập dữ liệu an toàn","design_case":{"title":"Tính độ lớn của sai lệch đo bằng thư viện toán học","problem":"Hai phép đo 27,5 °C và 30,0 °C. Tính |Tđo − Tthamchiếu| bằng fabs, diễn giải kết quả.","input":["Tđo = 27,5 °C; Tthamchiếu = 30,0 °C"],"process":["sai_lech = fabs(Tđo − Tthamchiếu)"],"output":["2,5 °C"],"assumptions":["Độ lệch tuyệt đối không phải sai số tương đối; không kết luận chất lượng cảm biến từ một mẫu"],"pseudocode":["Bắt đầu","Đọc hai số đo thực","Tính delta = fabs(Tdo − Tthamchieu)","In delta cùng đơn vị","Kết thúc"],"tests":[{"input":"27,5 và 30","expected":"2,5 °C","kind":"Thông thường"},{"input":"30 và 30","expected":"0 °C","kind":"Biên"},{"input":"32 và 30","expected":"2,0 °C","kind":"Giá trị cao hơn"}],"reflection":"Nên dùng fabs hay abs cho đối số kiểu double?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-12","number":12,"title":"Nhập xuất định dạng và kiểm tra dữ liệu","unit":"Thư viện và nhập xuất","source":"Slot_11_12_Libraries.pptx, slide 31–65","lead":"Xử lý dòng nhập có thể sai định dạng, phân biệt scanf, fgets và sscanf.","objectives":["Dùng đúng định dạng của printf và scanf.","Kiểm tra giá trị trả về của thao tác nhập.","Xây dựng trình tự xác thực dữ liệu đầu vào."],"sections":[{"title":"Đầu vào chuẩn và vùng đệm","text":"stdin và stdout là các luồng nhập/xuất chuẩn. Lời gọi scanf có thể để lại ký tự xuống dòng chưa tiêu thụ tùy định dạng; việc xử lý nhập sẽ đáng tin cậy hơn khi hiểu dòng dữ liệu thay vì cố đoán trạng thái vùng đệm.","bullets":[]},{"title":"printf và scanf","text":"printf(\"%d\", n) nhận giá trị int, scanf(\"%d\", &n) nhận địa chỉ int; đối với double, printf dùng %f còn scanf dùng %lf. Không truyền địa chỉ cho printf khi %d yêu cầu int, cũng không truyền biến thay cho con trỏ trong scanf.","bullets":[]},{"title":"Đọc theo dòng","text":"fgets(buffer, sizeof buffer, stdin) đọc tối đa kích thước-1 byte và kết thúc chuỗi bằng NUL nếu thành công. Có thể dùng sscanf hoặc strtol để phân tích sau khi đã đọc dòng. Nếu dòng quá dài, phải xử lý phần còn lại trước lần nhập tiếp theo.","bullets":[]},{"title":"Xác thực và phản hồi","text":"Một trình tự cơ bản: đọc dữ liệu; kiểm tra đọc thành công; kiểm tra cú pháp/chuyển đổi; kiểm tra miền giá trị; chấp nhận hoặc thông báo lỗi. Tách riêng thông báo lỗi, không thực hiện tính toán với dữ liệu chưa hợp lệ.","bullets":[]}],"example":{"title":"Nhập và kiểm tra số nguyên trên một dòng","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <errno.h>\n#include <ctype.h>\n#include <limits.h>\n#include <string.h>\n\n/* Tra ve 1 neu doc dung mot so nguyen trong [min, max]. */\nstatic int read_int_range(int min, int max, int *value) {\n    char line[100];\n    if (fgets(line, sizeof line, stdin) == NULL) return 0;\n    /* Neu chua co newline, doc them mot ky tu de phat hien phan du. */\n    if (strchr(line, '\\n') == NULL) {\n        int c = getchar();\n        if (c != EOF) {\n            while (c != '\\n' && c != EOF) c = getchar();\n            return 0;\n        }\n    }\n    errno = 0;\n    char *end = NULL;\n    char *begin = line;\n    long x = strtol(begin, &end, 10);\n    if (begin == end || errno == ERANGE) return 0;\n    while (isspace((unsigned char)*end)) ++end;\n    if (*end != '\\0' || x < min || x > max ||\n        x < INT_MIN || x > INT_MAX) return 0;\n    *value = (int)x;\n    return 1;\n}\nint main(void) {\n    int n;\n    puts(\"Nhap so nguyen 1..100:\");\n    if (!read_int_range(1, 100, &n)) {\n        puts(\"Du lieu khong hop le\");\n        return 1;\n    }\n    printf(\"Gia tri = %d\\n\", n);\n    return 0;\n}\n","output":"Nhap so nguyen 1..100:\nGia tri = 42","stdin":"42","why":"Đọc và xác thực toàn bộ dòng: kiểm tra phần bị cắt, chuyển đổi bằng strtol, xử lý ERANGE, ký tự thừa và miền giá trị. Dữ liệu hợp lệ được đưa vào biến n sau khi vượt mọi bước kiểm tra.","tests":[],"trace":["fgets giới hạn số byte; nếu không thấy ký tự xuống dòng, đọc thêm để phát hiện phần dữ liệu bị cắt và từ chối toàn bộ dòng.","strtol chuyển đổi số và trả con trỏ end tại ký tự đầu tiên chưa được xử lý; errno=ERANGE đánh dấu vượt miền long.","Bỏ qua khoảng trắng cuối, từ chối ký tự khác và giá trị ngoài 1..100 trước khi gán cho int."],"cases":[{"stdin":"42\n","stdout":"Nhap so nguyen 1..100:\nGia tri = 42","exit":0},{"stdin":"1\n","stdout":"Nhap so nguyen 1..100:\nGia tri = 1","exit":0},{"stdin":"100\n","stdout":"Nhap so nguyen 1..100:\nGia tri = 100","exit":0},{"stdin":"0\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"101\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"42x\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"42                                                                                                                        x\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"9999999999999999999999999999999999999\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"abc\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"  42  \n","stdout":"Nhap so nguyen 1..100:\nGia tri = 42","exit":0},{"stdin":"","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"42","stdout":"Nhap so nguyen 1..100:\nGia tri = 42","exit":0},{"stdin":"-1\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"42 3\n","stdout":"Nhap so nguyen 1..100:\nDu lieu khong hop le","exit":1},{"stdin":"42\t\t\n","stdout":"Nhap so nguyen 1..100:\nGia tri = 42","exit":0},{"stdin":"42\n999\n","stdout":"Nhap so nguyen 1..100:\nGia tri = 42","exit":0}]},"mistakes":["Dùng scanf không kiểm tra số phần tử được gán.","Nhầm %f và %lf ở đối số scanf.","Sử dụng gets (đã bị loại khỏi C11, không an toàn)."],"exercises":[{"name":"Nhập tuổi","task":"Đọc tuổi nguyên 0..120 bằng fgets rồi kiểm tra; nếu sai in thông báo.","hint":"Có thể dùng sscanf như ví dụ hoặc strtol để kiểm tra nghiêm ngặt.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Menu tương tác","task":"Thiết kế menu 1. Cộng, 2. Trừ, 0. Thoát; nhập lựa chọn hợp lệ.","hint":"Kết hợp do while với switch; tránh vòng lặp không dừng.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Thiết kế 8 ca kiểm thử đầu vào số 1..100: hợp lệ, âm, 0, 101, chữ, khoảng trắng, quá dài, tràn kiểu.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Với scanf nhập double, định dạng đúng là?","choices":["%f","%lf","%d","%s"],"answer":1,"explain":"%lf là định dạng nhập double trong scanf.","rationales":["%f trong scanf dành cho float*, không phải double*.","%lf là định dạng nhập double trong scanf.","%d dành cho int*.","%s dành cho bộ đệm chuỗi char*."]},{"q":"Vì sao không nên dùng gets?","choices":["Không giới hạn kích thước bộ đệm và không còn trong C11","Quá chậm","Chỉ đọc tệp","Không hoạt động với số"],"answer":0,"explain":"gets không thể bảo đảm giới hạn dữ liệu, đã bị xóa khỏi tiêu chuẩn C11.","rationales":["gets không thể bảo đảm giới hạn dữ liệu, đã bị xóa khỏi tiêu chuẩn C11.","Tốc độ không phải lý do gets bị loại bỏ.","gets là hàm có trong C89/C99, bị loại ở C11.","gets được thiết kế đọc chuỗi, không phải chỉ đọc số."]},{"q":"Vì sao phải kiểm tra một dòng fgets có bị cắt không?","choices":["Vì fgets tự xóa hết dữ liệu thừa.","Vì fgets luôn đọc cả tệp.","Vì fgets không thêm NUL.","Dữ liệu thừa có thể nằm ngoài bộ đệm và chưa được xác thực."],"answer":3,"explain":"fgets chỉ đọc tối đa size−1 byte mỗi lần.","rationales":["Không phù hợp: Vì fgets tự xóa hết dữ liệu thừa. Phát biểu đúng: fgets chỉ đọc tối đa size−1 byte mỗi lần.","Không phù hợp: Vì fgets luôn đọc cả tệp. Phát biểu đúng: fgets chỉ đọc tối đa size−1 byte mỗi lần.","Không phù hợp: Vì fgets không thêm NUL. Phát biểu đúng: fgets chỉ đọc tối đa size−1 byte mỗi lần.","fgets chỉ đọc tối đa size−1 byte mỗi lần."]},{"q":"Sau strtol, endptr dùng để làm gì?","choices":["Đặt lại stdin.","Tính số phần tử mảng.","Xác định vị trí sau phần số đã chuyển đổi.","Lấy kích thước CPU."],"answer":2,"explain":"Có thể kiểm tra ký tự thừa sau phần số, kể cả khoảng trắng cuối.","rationales":["Không phù hợp: Đặt lại stdin. Phát biểu đúng: Có thể kiểm tra ký tự thừa sau phần số, kể cả khoảng trắng cuối.","Không phù hợp: Tính số phần tử mảng. Phát biểu đúng: Có thể kiểm tra ký tự thừa sau phần số, kể cả khoảng trắng cuối.","Có thể kiểm tra ký tự thừa sau phần số, kể cả khoảng trắng cuối.","Không phù hợp: Lấy kích thước CPU. Phát biểu đúng: Có thể kiểm tra ký tự thừa sau phần số, kể cả khoảng trắng cuối."]},{"q":"Khi strtol báo errno==ERANGE nghĩa là gì?","choices":["Đã đọc được số 0.","Giá trị nằm ngoài miền biểu diễn long của môi trường.","Chỉ có lỗi thiếu dòng mới gây ra.","Đã tìm thấy dấu chấm phẩy."],"answer":1,"explain":"Cần từ chối nếu bài toán yêu cầu long hợp lệ.","rationales":["Không phù hợp: Đã đọc được số 0. Phát biểu đúng: Cần từ chối nếu bài toán yêu cầu long hợp lệ.","Cần từ chối nếu bài toán yêu cầu long hợp lệ.","Không phù hợp: Chỉ có lỗi thiếu dòng mới gây ra. Phát biểu đúng: Cần từ chối nếu bài toán yêu cầu long hợp lệ.","Không phù hợp: Đã tìm thấy dấu chấm phẩy. Phát biểu đúng: Cần từ chối nếu bài toán yêu cầu long hợp lệ."]}],"summary":["Đầu vào chuẩn và vùng đệm","printf và scanf","Đọc theo dòng","Xác thực và phản hồi"],"minutes":45,"syntax":[{"label":"Nhập có kiểm tra bằng scanf","code":"int tuoi;\nif (scanf(\"%d\", &tuoi) != 1) {\n    puts(\"Khong doc duoc so nguyen\");\n}\n","meaning":"scanf chỉ báo việc chuyển đổi và gán, không tự đảm bảo giá trị thuộc phạm vi hợp lệ của bài toán.","watch":"Cần kiểm tra cả kết quả đọc và miền giá trị; tránh %s thiếu giới hạn độ rộng."},{"label":"Đọc nguyên dòng với fgets","code":"char buf[64];\nif (fgets(buf, sizeof buf, stdin) != NULL) {\n    /* xử lý chuỗi buf */\n}\n","meaning":"fgets đọc tối đa sizeof(buf)-1 ký tự và thêm NUL; thường giữ lại newline nếu còn chỗ.","watch":"Dữ liệu dài hơn bộ đệm có thể chỉ được đọc một phần; cần chính sách xử lý dòng quá dài."}],"flow":{"type":"decision","caption":"Nhập và xác nhận tuổi hợp lệ","start":"Đọc tuổi","condition":"Đọc được và 0–120?","yes":"In tuổi hợp lệ","no":"Báo lỗi dữ liệu","end":"Kết thúc"},"worked":{"title":"Bài mẫu: xác thực tuổi bằng đọc cả dòng và strtol","problem":"Nhập đúng một số nguyên từ 0 đến 120, từ chối chuỗi thừa ký tự, quá dài, tràn kiểu, EOF và số ngoài miền.","steps":["Dùng fgets trong bộ đệm 100 byte, phát hiện phần dư của dòng.","Dùng strtol/errno/endptr để phát hiện chuyển đổi lỗi.","Kiểm tra miền 0..120; chỉ xuất tuổi nếu toàn bộ dữ liệu hợp lệ."],"code":"#include <stdio.h>\n#include <stdlib.h>\n#include <errno.h>\n#include <ctype.h>\n#include <limits.h>\n#include <string.h>\n\n/* Tra ve 1 neu doc dung mot so nguyen trong [min, max]. */\nstatic int read_int_range(int min, int max, int *value) {\n    char line[100];\n    if (fgets(line, sizeof line, stdin) == NULL) return 0;\n    /* Neu chua co newline, doc them mot ky tu de phat hien phan du. */\n    if (strchr(line, '\\n') == NULL) {\n        int c = getchar();\n        if (c != EOF) {\n            while (c != '\\n' && c != EOF) c = getchar();\n            return 0;\n        }\n    }\n    errno = 0;\n    char *end = NULL;\n    char *begin = line;\n    long x = strtol(begin, &end, 10);\n    if (begin == end || errno == ERANGE) return 0;\n    while (isspace((unsigned char)*end)) ++end;\n    if (*end != '\\0' || x < min || x > max ||\n        x < INT_MIN || x > INT_MAX) return 0;\n    *value = (int)x;\n    return 1;\n}\nint main(void) {\n    int n;\n    puts(\"Nhap tuoi 0..120:\");\n    if (!read_int_range(0, 120, &n)) {\n        puts(\"Du lieu khong hop le\");\n        return 1;\n    }\n    printf(\"Tuoi hop le: %d\\n\", n);\n    return 0;\n}\n","output":"Nhap tuoi 0..120:\nTuoi hop le: 20","stdin":"20","analysis":["Không sử dụng một giá trị chưa qua kiểm tra; mọi ký tự của dòng được xác thực.","Các trường hợp 20x, tuổi âm, tuổi 121 và dòng bị cắt đều phải trả lỗi."],"tests":["0 và 120 hợp lệ; −1, 121, 20x, dòng vượt bộ đệm, chuỗi vượt miền long đều bị từ chối."]},"deep_dive":{"context":"Xác thực đầu vào cần kiểm tra cả dòng, không chỉ phần số được đọc. Với dữ liệu số nguyên, có thể đọc dòng bằng fgets, phát hiện dòng bị cắt, sau đó chuyển đổi bằng strtol với errno và endptr.","contrast":[["fgets","Giới hạn số byte nhận, luôn cần xem có phần dòng còn lại hay không."],["strtol","Phân tích số nguyên có con trỏ kết thúc và phát hiện ngoài miền long qua errno."],["errno=ERANGE","Tình trạng vượt miền biểu diễn long."],["endptr","Cho biết còn ký tự nào sau phần số đã phân tích."]],"pitfall":"Không chấp nhận chuỗi “42[120 dấu cách]x” khi x nằm sau phần bị cắt khỏi bộ đệm. Không dùng sscanf(\"%d\") để tự khẳng định xử lý được mọi số ngoài miền.","challenge":"Thiết kế 8 ca kiểm thử đầu vào số 1..100: hợp lệ, âm, 0, 101, chữ, khoảng trắng, quá dài, tràn kiểu."},"lab_examples":[{"title":"Hàm đọc số nguyên nghiêm ngặt: thêm ca kiểm thử","purpose":"Dùng chung hàm đọc nghiêm ngặt trong ví dụ chính; thử cả dữ liệu thừa và biên.","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <errno.h>\n#include <ctype.h>\n#include <limits.h>\n#include <string.h>\nint main(void) {\n    char s[] = \"  42  \";\n    errno = 0;\n    char *end;\n    long x = strtol(s, &end, 10);\n    while (isspace((unsigned char)*end)) ++end;\n    if (end == s || *end != '\\0' || errno == ERANGE || x < INT_MIN || x > INT_MAX)\n        puts(\"Khong hop le\");\n    else printf(\"So hop le=%ld\\n\", x);\n    return 0;\n}\n","output":"So hop le=42","stdin":"","cases":[{"stdin":"","stdout":"So hop le=42","exit":0}],"followup":"Sửa chuỗi đầu vào thành \"42xyz\" và giải thích vai trò của endptr."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M3","module_title":"Bộ nhớ, thư viện và nhập dữ liệu an toàn","design_case":{"title":"Xác thực số lần đo nhập từ bàn phím","problem":"Một phép thử nhận số lần đo nguyên từ 1 đến 100. Các chuỗi như “35x” phải bị từ chối, không được chỉ đọc phần 35.","input":["Một dòng ký tự biểu diễn số nguyên"],"process":["Đọc cả dòng; strtol; kiểm tra errno, endptr và miền 1–100"],"output":["Số nguyên hợp lệ hoặc thông báo nhập sai"],"assumptions":["Không chấp nhận số quá lớn, thiếu dữ liệu hoặc ký tự thừa"],"pseudocode":["Bắt đầu","Đọc toàn bộ dòng","Thử strtol; kiểm tra lỗi chuyển đổi và ký tự dư","Nếu số nằm trong 1..100 thì nhận","Ngược lại thông báo lỗi; kết thúc"],"tests":[{"input":"\"35\"","expected":"35 hợp lệ","kind":"Bình thường"},{"input":"\"35x\"","expected":"Từ chối","kind":"Ký tự thừa"},{"input":"\"0\" hoặc \"101\"","expected":"Từ chối","kind":"Ngoài miền"}],"reflection":"Điều gì xảy ra nếu chỉ dùng scanf(\"%d\", &n) mà không kiểm tra dữ liệu còn lại?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-13","number":13,"title":"Mảng một chiều và truyền mảng cho hàm","unit":"Mảng và cấu trúc","source":"Slot_13_14_15_ContiguousStorage.pptx, slide 4–24","lead":"Tổ chức các phần tử cùng kiểu trong vùng nhớ liên tiếp và xử lý có kiểm tra chỉ số.","objectives":["Khai báo và truy cập được mảng một chiều.","Duyệt mảng bằng vòng lặp có giới hạn hợp lệ.","Truyền mảng cho hàm cùng số phần tử."],"sections":[{"title":"Mảng và chỉ số","text":"Mảng là đối tượng gồm các phần tử cùng kiểu được lưu liên tiếp. Với int a[5], các chỉ số hợp lệ là 0..4. Truy cập a[5] là vượt ranh giới và dẫn đến hành vi không xác định khi đánh giá phần tử.","bullets":[]},{"title":"Khởi tạo và duyệt","text":"int a[] = {3,5,7}; xác định mảng ba phần tử. Số phần tử mảng tại phạm vi khai báo có thể tính bằng sizeof a / sizeof a[0] nếu a thực sự là mảng. Trong tham số hàm, kiểu mảng phần lớn được điều chỉnh thành kiểu con trỏ, do đó phải truyền số phần tử riêng.","bullets":[]},{"title":"Truyền mảng vào hàm","text":"Hàm void hien_thi(const int a[], size_t n) có thể đọc n phần tử; const thể hiện không được thay đổi phần tử qua tham số này. Hàm phải được gọi với n phù hợp độ dài thực tế của mảng.","bullets":[]},{"title":"Vùng lưu trữ và cấp phát","text":"Mảng cục bộ có thời gian lưu trữ tự động không đồng nghĩa bắt buộc nằm trên stack theo chuẩn C. Vùng nhớ được cấp phát bằng malloc có thời gian lưu trữ cấp phát động. Không nên lấy stack/heap làm định nghĩa bản chất của mảng.","bullets":[]}],"example":{"title":"Tính tổng và trung bình mảng","code":"#include <stdio.h>\nint main(void) {\n    int a[] = {4, 7, 2, 9};\n    size_t n = sizeof a / sizeof a[0];\n    int tong = 0;\n    for (size_t i = 0; i < n; ++i) tong += a[i];\n    printf(\"Tong = %d\\n\", tong);\n    printf(\"TB = %.2f\\n\", (double)tong / n);\n    return 0;\n}\n","output":"Tong = 22\nTB = 5.50","stdin":"","why":"Đọc chương trình theo thứ tự thực thi, dự đoán kết quả trước khi chạy và đối chiếu các bước giải thích ngay dưới mã ví dụ.","tests":[],"trace":["sizeof a/sizeof a[0] xác định số phần tử tại nơi a còn là mảng.","Vòng lặp cộng 4+7+2+9=22; chuyển tổng sang double trước khi chia 4 tạo 5.50."]},"mistakes":["Bắt đầu duyệt mảng từ 1 đến n thay vì 0 đến n-1.","Dùng sizeof con trỏ để suy ra số phần tử mảng trong hàm.","Vượt giới hạn khi đọc/ghi phần tử."],"exercises":[{"name":"Nhập và tìm cực trị","task":"Nhập 5 số nguyên, in tổng, giá trị lớn nhất, nhỏ nhất.","hint":"Khởi tạo min và max bằng phần tử đầu tiên sau khi bảo đảm mảng không rỗng.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Tách hàm","task":"Viết int sum(const int a[], size_t n) và gọi với mảng đã khởi tạo.","hint":"Truyền n cùng với mảng.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Viết hàm tìm phần tử lớn nhất của mảng có n>0, nêu cách biểu diễn lỗi khi n=0.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Mảng int a[5] có chỉ số hợp lệ nào?","choices":["0 đến 4","1 đến 5","0 đến 5","-1 đến 3"],"answer":0,"explain":"Mảng C dùng chỉ số bắt đầu từ 0.","rationales":["Mảng C dùng chỉ số bắt đầu từ 0.","Mảng C bắt đầu từ chỉ số 0 chứ không phải 1.","Chỉ số 5 vượt mảng 5 phần tử.","Chỉ số -1 nằm ngoài phạm vi hợp lệ."]},{"q":"Khi truyền a[] vào hàm, hàm có tự biết số phần tử không?","choices":["Chỉ khi dùng printf","Luôn biết","Không cần giới hạn","Không, nên truyền n riêng"],"answer":3,"explain":"Tham số mảng được điều chỉnh thành con trỏ nên không giữ độ dài.","rationales":["printf không cung cấp độ dài mảng cho hàm.","Số phần tử không tự truyền cùng con trỏ.","Không giới hạn chỉ số dẫn tới truy cập ngoài mảng.","Tham số mảng được điều chỉnh thành con trỏ nên không giữ độ dài."]},{"q":"Với int a[4], chỉ số nào không hợp lệ?","choices":["a[1].","a[3].","a[4].","a[0]."],"answer":2,"explain":"Chỉ số hợp lệ là 0..3, a[4] vượt phần tử cuối.","rationales":["Không phù hợp: a[1]. Phát biểu đúng: Chỉ số hợp lệ là 0..3, a[4] vượt phần tử cuối.","Không phù hợp: a[3]. Phát biểu đúng: Chỉ số hợp lệ là 0..3, a[4] vượt phần tử cuối.","Chỉ số hợp lệ là 0..3, a[4] vượt phần tử cuối.","Không phù hợp: a[0]. Phát biểu đúng: Chỉ số hợp lệ là 0..3, a[4] vượt phần tử cuối."]},{"q":"Đại lượng nào cần truyền kèm mảng cho hàm xử lý?","choices":["Số dòng mã C.","Số phần tử hợp lệ của mảng.","Địa chỉ máy tính người dùng.","Tên tệp nguồn."],"answer":1,"explain":"Tham số mảng trong hàm không tự chứa chiều dài.","rationales":["Không phù hợp: Số dòng mã C. Phát biểu đúng: Tham số mảng trong hàm không tự chứa chiều dài.","Tham số mảng trong hàm không tự chứa chiều dài.","Không phù hợp: Địa chỉ máy tính người dùng. Phát biểu đúng: Tham số mảng trong hàm không tự chứa chiều dài.","Không phù hợp: Tên tệp nguồn. Phát biểu đúng: Tham số mảng trong hàm không tự chứa chiều dài."]},{"q":"Cách xử lý trung bình mảng rỗng đúng về toán học là gì?","choices":["Báo không xác định/không có kết quả trung bình theo đặc tả.","Luôn bằng 0.0 một cách toán học.","Luôn bằng NULL.","Luôn bằng 1."],"answer":0,"explain":"Không có trung bình số học khi n=0 vì mẫu số bằng 0.","rationales":["Không có trung bình số học khi n=0 vì mẫu số bằng 0.","Không phù hợp: Luôn bằng 0.0 một cách toán học. Phát biểu đúng: Không có trung bình số học khi n=0 vì mẫu số bằng 0.","Không phù hợp: Luôn bằng NULL. Phát biểu đúng: Không có trung bình số học khi n=0 vì mẫu số bằng 0.","Không phù hợp: Luôn bằng 1. Phát biểu đúng: Không có trung bình số học khi n=0 vì mẫu số bằng 0."]}],"summary":["Mảng và chỉ số","Khởi tạo và duyệt","Truyền mảng vào hàm","Vùng lưu trữ và cấp phát"],"minutes":45,"syntax":[{"label":"Mảng và phép truy cập phần tử","code":"int a[4] = {3, 5, 7, 9};\nfor (size_t i = 0; i < 4; ++i) {\n    printf(\"%d \", a[i]);\n}\n","meaning":"a có bốn phần tử int với chỉ số 0..3; duyệt bằng i<4 để không vượt biên.","watch":"Đoạn mã nằm trong hàm, cần stdio.h và nơi khai báo size_t (stdio.h cung cấp size_t)."},{"label":"Truyền mảng vào hàm","code":"double trung_binh(const int a[], size_t n);\n","meaning":"Khi là tham số hàm, int a[] được điều chỉnh thành con trỏ int*; độ dài n phải truyền riêng.","watch":"Hàm không tự xác định số phần tử của mảng từ sizeof(a) nếu a là tham số."}],"flow":{"type":"loop","caption":"Duyệt mảng để tính tổng","start":"i = 0; tổng = 0","condition":"i < n ?","body":"tổng += a[i]; i++","end":"In tổng/giá trị trung bình"},"worked":{"title":"Bài mẫu: tính trung bình có trả trạng thái thành công","problem":"Cho mảng ba số {3,5,7}; viết hàm trả true khi đã tính được trung bình và false khi mảng rỗng hoặc con trỏ không hợp lệ.","steps":["Kiểm tra n>0, a và result khác NULL.","Cộng bằng double để tránh tràn số nguyên trong phép cộng.","Ghi kết quả vào vùng do result trỏ tới và trả trạng thái true."],"code":"#include <stdio.h>\n#include <stddef.h>\n#include <stdbool.h>\nbool average(const int *a, size_t n, double *result) {\n    if (n == 0 || a == NULL || result == NULL) return false;\n    double sum = 0.0;\n    for (size_t i = 0; i < n; ++i) sum += (double)a[i];\n    *result = sum / (double)n;\n    return true;\n}\nint main(void) {\n    int a[] = {3, 5, 7};\n    double t;\n    if (average(a, sizeof a / sizeof a[0], &t))\n        printf(\"TB=%.2f\\n\", t);\n    return 0;\n}\n","output":"TB=5.00","stdin":"","analysis":["Giá trị trung bình của mảng rỗng không được gán mặc định 0.0 về mặt toán học.","Giá trị trả về của hàm cho biết phép tính có thực hiện thành công hay không."],"tests":["{3,5,7} → 5.00; {−3,3} → 0.00; n=0 → false."]},"deep_dive":{"context":"Mảng lưu các phần tử cùng kiểu ở các vị trí liên tiếp và được truy cập từ chỉ số 0. Một API tính trung bình cần xác định rõ xử lý n=0; không thể tự xem 0.0 là trung bình toán học của mảng rỗng.","contrast":[["a[i]","Phần tử thứ i; chỉ hợp lệ nếu i trong miền chỉ số."],["sizeof a / sizeof a[0]","Số phần tử khi a còn là đối tượng mảng thật tại vị trí biểu thức."],["Tham số int a[]","Tại tham số hàm được điều chỉnh thành con trỏ, không tự mang chiều dài."],["n == 0","Cần trả trạng thái lỗi hoặc có quy ước riêng được nêu rõ."]],"pitfall":"Không đánh giá a[n], vì phần tử cuối là a[n−1] khi n>0. Không dùng giá trị không xác định của biến chưa khởi tạo.","challenge":"Viết hàm tìm phần tử lớn nhất của mảng có n>0, nêu cách biểu diễn lỗi khi n=0."},"lab_examples":[{"title":"API trung bình trả trạng thái","purpose":"Không trả 0.0 làm giá trị trung bình của mảng rỗng.","code":"#include <stdio.h>\n#include <stddef.h>\n#include <stdbool.h>\nbool average(const int *a, size_t n, double *result) {\n    if (n == 0 || a == NULL || result == NULL) return false;\n    double sum = 0.0;\n    for (size_t i = 0; i < n; ++i) sum += (double)a[i];\n    *result = sum / (double)n;\n    return true;\n}\nint main(void) {\n    int a[] = {3, 5, 7};\n    double t;\n    if (average(a, sizeof a / sizeof a[0], &t))\n        printf(\"TB=%.2f\\n\", t);\n    return 0;\n}\n","output":"TB=5.00","stdin":"","cases":[{"stdin":"","stdout":"TB=5.00","exit":0}],"followup":"Thử average(NULL, 0, &t) và giải thích vì sao hàm trả false."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M4","module_title":"Mảng, thuật toán xử lý dữ liệu và chuỗi","design_case":{"title":"Tính trung bình mảng số đo nhiệt độ","problem":"Một mảng gồm 24, 25, 26 và 27 °C. Duyệt mảng và tính trung bình, xử lý trường hợp không có mẫu.","input":["a = {24,25,26,27}, n=4"],"process":["Tổng 102; chia 4"],"output":["25,5 °C"],"assumptions":["n > 0; cần sử dụng phép chia thực"],"pseudocode":["Bắt đầu","Nếu n = 0: thông báo không có mẫu","Đặt tong = 0; duyệt i từ 0 đến n−1","Cộng a[i] vào tổng","Tính trung bình dưới dạng số thực, hiển thị"],"tests":[{"input":"24,25,26,27","expected":"25,5 °C","kind":"Thông thường"},{"input":"5","expected":"5,0 °C","kind":"Một phần tử"},{"input":"Mảng rỗng","expected":"Không có giá trị trung bình","kind":"Biên"}],"reflection":"Vì sao không nên trả 0,0 như một giá trị trung bình của mảng rỗng?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-14","number":14,"title":"Tìm kiếm và sắp xếp mảng","unit":"Mảng và cấu trúc","source":"Slot_13_14_15_ContiguousStorage.pptx, slide 25–45","lead":"Áp dụng tìm tuyến tính, tìm nhị phân và sắp xếp trực tiếp; đánh giá điều kiện tiền đề của thuật toán.","objectives":["Cài đặt được tìm kiếm tuyến tính và chọn cách trả về khi không tìm thấy.","Giải thích được điều kiện mảng đã sắp xếp của tìm kiếm nhị phân.","Mô tả và cài đặt sắp xếp chọn hoặc nổi bọt."],"sections":[{"title":"Tìm kiếm tuyến tính","text":"Duyệt lần lượt từ đầu mảng đến khi tìm thấy giá trị hoặc hết phần tử. Với n phần tử, số phép kiểm tra trong trường hợp xấu nhất tỷ lệ với n, ký hiệu O(n). Có thể dùng -1 làm ký hiệu không tìm thấy khi trả về chỉ số kiểu int với n phù hợp.","bullets":[]},{"title":"Tìm kiếm nhị phân","text":"Trên mảng đã được sắp xếp tăng (hoặc giảm với điều kiện so sánh tương ứng), tìm kiếm nhị phân so sánh với phần tử giữa rồi bỏ một nửa vùng tìm kiếm. Độ phức tạp O(log n) với giả định truy cập ngẫu nhiên. Không áp dụng trực tiếp lên mảng chưa sắp xếp.","bullets":[]},{"title":"Sắp xếp chọn","text":"Tại bước i, tìm phần tử nhỏ nhất trong đoạn a[i..n-1] rồi hoán đổi với a[i]. Thuật toán có O(n²) phép so sánh và dễ thực hiện, thích hợp học căn bản, không luôn tối ưu cho dữ liệu lớn.","bullets":[]},{"title":"Sắp xếp nổi bọt","text":"So sánh các cặp kề nhau và đổi chỗ nếu sai thứ tự; sau mỗi lượt, một phần tử lớn nhất chuyển về cuối đoạn chưa sắp. Có thể cải tiến bằng cờ đã đổi để dừng sớm nếu dãy đã có thứ tự.","bullets":[]}],"example":{"title":"Tìm kiếm tuyến tính trên mảng","code":"#include <stdio.h>\nint tim(const int a[], int n, int x) {\n    for (int i = 0; i < n; ++i)\n        if (a[i] == x) return i;\n    return -1;\n}\nint main(void) {\n    int a[] = {7, 4, 10, 2, 4};\n    int p = tim(a, 5, 10);\n    printf(\"Vi tri = %d\\n\", p);\n    return 0;\n}\n","output":"Vi tri = 2","stdin":"","why":"Đọc chương trình theo thứ tự thực thi, dự đoán kết quả trước khi chạy và đối chiếu các bước giải thích ngay dưới mã ví dụ.","tests":[],"trace":["Hàm tim duyệt a từ chỉ số 0 và trả về ngay khi gặp giá trị cần tìm.","Số 10 nằm ở chỉ số 2; nếu không thấy thì hàm trả -1."]},"mistakes":["Tìm nhị phân khi mảng chưa được sắp xếp.","Quên xử lý không tìm thấy.","Nhầm chỉ số 0-based với thứ tự phần tử 1-based."],"exercises":[{"name":"Sắp xếp chọn","task":"Nhập 8 số, sắp xếp tăng bằng selection sort và in kết quả.","hint":"Duyệt i từ 0 đến n-2, tìm vị trí nhỏ nhất ở phần chưa sắp.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Tìm nhị phân","task":"Viết binarySearch trên mảng tăng, thử khóa đầu/cuối/không có.","hint":"Tính mid = left + (right-left)/2, giữ điều kiện vùng tìm kiếm hợp lệ.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Tạo bảng truy vết selection sort cho mảng {4,1,3,2} sau từng vòng ngoài và giải thích bất biến.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Tìm nhị phân đòi hỏi điều kiện nào?","choices":["Không có số trùng","Mảng luôn có 100 phần tử","Chỉ gồm số chẵn","Mảng đã sắp xếp theo thứ tự phù hợp"],"answer":3,"explain":"Thuật toán dựa trên thứ tự để loại bỏ nửa vùng tìm kiếm.","rationales":["Có giá trị trùng không làm mất điều kiện dùng tìm nhị phân.","Tìm nhị phân không đòi đúng 100 phần tử.","Tính chẵn của phần tử không thay thế điều kiện có thứ tự.","Thuật toán dựa trên thứ tự để loại bỏ nửa vùng tìm kiếm."]},{"q":"Độ phức tạp trường hợp xấu nhất của tìm tuyến tính là?","choices":["O(log n)","O(n²)","O(n)","O(1)"],"answer":2,"explain":"Có thể phải kiểm tra toàn bộ n phần tử.","rationales":["O(log n) là quy mô của tìm nhị phân trên dữ liệu có thứ tự.","O(n²) thường gắn với một số thuật toán sắp xếp cơ bản, không phải tìm tuyến tính.","Có thể phải kiểm tra toàn bộ n phần tử.","O(1) không phản ánh trường hợp phải duyệt hết mảng."]},{"q":"Điều kiện tiên quyết của tìm kiếm nhị phân là gì?","choices":["Mảng chưa sắp xếp.","Mảng đã sắp xếp theo tiêu chí so sánh phù hợp.","Mảng phải có đúng 100 phần tử.","Mảng phải toàn số dương."],"answer":1,"explain":"Quyết định bỏ nửa trái/phải dựa vào thứ tự.","rationales":["Không phù hợp: Mảng chưa sắp xếp. Phát biểu đúng: Quyết định bỏ nửa trái/phải dựa vào thứ tự.","Quyết định bỏ nửa trái/phải dựa vào thứ tự.","Không phù hợp: Mảng phải có đúng 100 phần tử. Phát biểu đúng: Quyết định bỏ nửa trái/phải dựa vào thứ tự.","Không phù hợp: Mảng phải toàn số dương. Phát biểu đúng: Quyết định bỏ nửa trái/phải dựa vào thứ tự."]},{"q":"Độ phức tạp trường hợp xấu của selection sort theo n là gì?","choices":["O(n²).","O(1).","O(n log n) cho mọi đầu vào.","O(log n)."],"answer":0,"explain":"Hai vòng lặp duyệt số cặp phần tử tỉ lệ bậc hai.","rationales":["Hai vòng lặp duyệt số cặp phần tử tỉ lệ bậc hai.","Không phù hợp: O(1). Phát biểu đúng: Hai vòng lặp duyệt số cặp phần tử tỉ lệ bậc hai.","Không phù hợp: O(n log n) cho mọi đầu vào. Phát biểu đúng: Hai vòng lặp duyệt số cặp phần tử tỉ lệ bậc hai.","Không phù hợp: O(log n). Phát biểu đúng: Hai vòng lặp duyệt số cặp phần tử tỉ lệ bậc hai."]},{"q":"Tại sao nên tính mid=lo+(hi-lo)/2 trong binary search?","choices":["Bắt buộc để dùng scanf.","Để mảng được đảo ngược.","Để chương trình không cần vòng lặp.","Hạn chế nguy cơ tràn khi cộng trực tiếp lo+hi."],"answer":3,"explain":"Hiệu hi−lo được giới hạn khi lo≤hi.","rationales":["Không phù hợp: Bắt buộc để dùng scanf. Phát biểu đúng: Hiệu hi−lo được giới hạn khi lo≤hi.","Không phù hợp: Để mảng được đảo ngược. Phát biểu đúng: Hiệu hi−lo được giới hạn khi lo≤hi.","Không phù hợp: Để chương trình không cần vòng lặp. Phát biểu đúng: Hiệu hi−lo được giới hạn khi lo≤hi.","Hiệu hi−lo được giới hạn khi lo≤hi."]}],"summary":["Tìm kiếm tuyến tính","Tìm kiếm nhị phân","Sắp xếp chọn","Sắp xếp nổi bọt"],"minutes":45,"syntax":[{"label":"Tìm kiếm tuyến tính trong mảng","code":"int vi_tri = -1;\nfor (size_t i = 0; i < n; ++i) {\n    if (a[i] == x) {\n        vi_tri = (int)i;\n        break;\n    }\n}\n","meaning":"Duyệt lần lượt; break dừng khi gặp phần tử đầu tiên bằng x.","watch":"Mẫu chỉ minh họa với n đủ nhỏ để chỉ số chuyển sang int; nếu n rất lớn dùng kiểu phù hợp."},{"label":"Điều kiện của tìm kiếm nhị phân","code":"/* Chỉ tìm kiếm nhị phân khi mảng đã sắp xếp\n   theo đúng thứ tự dùng trong phép so sánh. */\n","meaning":"Thuật toán nhị phân loại một nửa không gian tìm kiếm nhờ tính đơn điệu của dữ liệu.","watch":"Không thực hiện tìm kiếm nhị phân trên mảng chưa sắp xếp."}],"flow":{"type":"loop","caption":"Tìm kiếm tuyến tính phần tử x","start":"i = 0","condition":"i < n và chưa thấy x?","body":"Kiểm tra a[i]; tăng i nếu chưa thấy","end":"Trả vị trí hoặc -1"},"worked":{"title":"Bài mẫu: sắp xếp chọn và tìm kiếm nhị phân","problem":"Cho mảng {7,2,9,1,4}; sắp xếp tăng dần và tìm vị trí của số 7 bằng tìm kiếm nhị phân.","steps":["Chọn phần tử nhỏ nhất ở đoạn chưa sắp và đổi về vị trí i (selection sort).","Sau khi đã sắp tăng, duy trì khoảng tìm kiếm [lo,hi) và chọn mid không gây tràn cộng chỉ số.","Nếu không thấy trả −1, ngược lại in chỉ số 0-based."],"code":"#include <stdio.h>\n#include <stddef.h>\nvoid selection_sort(int a[], size_t n) {\n    for (size_t i = 0; i < n; ++i) {\n        size_t min = i;\n        for (size_t j = i + 1; j < n; ++j) {\n            if (a[j] < a[min]) min = j;\n        }\n        int t = a[i]; a[i] = a[min]; a[min] = t;\n    }\n}\nint binary_search(const int a[], size_t n, int x) {\n    size_t lo = 0, hi = n;\n    while (lo < hi) {\n        size_t mid = lo + (hi - lo) / 2;\n        if (a[mid] == x) return (int)mid;\n        if (a[mid] < x) lo = mid + 1;\n        else hi = mid;\n    }\n    return -1;\n}\nint main(void) {\n    int a[] = {7, 2, 9, 1, 4};\n    size_t n = sizeof a / sizeof a[0];\n    selection_sort(a, n);\n    for (size_t i = 0; i < n; ++i) printf(\"%d%c\", a[i], (i+1==n)?'\\n':' ');\n    printf(\"Vi tri 7=%d\\n\", binary_search(a, n, 7));\n    return 0;\n}\n","output":"1 2 4 7 9\nVi tri 7=3","stdin":"","analysis":["Không tìm nhị phân trước khi sắp xếp; kết quả vị trí 7 là 3 trong mảng đã sắp.","Khi thu hẹp đoạn, điều kiện lo<hi bảo đảm vòng lặp dừng."],"tests":["Tìm 1 → 0; tìm 7 → 3; tìm 8 → −1."]},"deep_dive":{"context":"Tìm kiếm nhị phân chỉ đúng khi mảng đã có thứ tự phù hợp. Sắp xếp chọn duy trì bất biến: tiền tố đã xử lý có giá trị nhỏ nhất của các phần tử đã xét; tìm tuyến tính không cần giả thiết mảng đã sắp.","contrast":[["Tìm tuyến tính","O(n) trong trường hợp xấu, không cần thứ tự."],["Tìm nhị phân","O(log n), cần mảng đã sắp theo cùng tiêu chí."],["Sắp xếp chọn","O(n²), chọn phần tử nhỏ nhất cho vị trí i."],["Sắp xếp nổi bọt","O(n²) trong cách cài đơn giản, đổi vị trí hai phần tử kề nhau."]],"pitfall":"Không áp dụng binary search trực tiếp cho mảng chưa sắp xếp, ngay cả khi đôi lúc tìm đúng theo may mắn.","challenge":"Tạo bảng truy vết selection sort cho mảng {4,1,3,2} sau từng vòng ngoài và giải thích bất biến."},"lab_examples":[{"title":"Sắp xếp chọn rồi tìm nhị phân","purpose":"Từ mảng chưa sắp đến mảng đã sắp và tìm một phần tử.","code":"#include <stdio.h>\n#include <stddef.h>\nvoid selection_sort(int a[], size_t n) {\n    for (size_t i = 0; i < n; ++i) {\n        size_t min = i;\n        for (size_t j = i + 1; j < n; ++j) {\n            if (a[j] < a[min]) min = j;\n        }\n        int t = a[i]; a[i] = a[min]; a[min] = t;\n    }\n}\nint binary_search(const int a[], size_t n, int x) {\n    size_t lo = 0, hi = n;\n    while (lo < hi) {\n        size_t mid = lo + (hi - lo) / 2;\n        if (a[mid] == x) return (int)mid;\n        if (a[mid] < x) lo = mid + 1;\n        else hi = mid;\n    }\n    return -1;\n}\nint main(void) {\n    int a[] = {7, 2, 9, 1, 4};\n    size_t n = sizeof a / sizeof a[0];\n    selection_sort(a, n);\n    for (size_t i = 0; i < n; ++i) printf(\"%d%c\", a[i], (i+1==n)?'\\n':' ');\n    printf(\"Vi tri 7=%d\\n\", binary_search(a, n, 7));\n    return 0;\n}\n","output":"1 2 4 7 9\nVi tri 7=3","stdin":"","cases":[{"stdin":"","stdout":"1 2 4 7 9\nVi tri 7=3","exit":0}],"followup":"Tìm x=8 và x=1; trình bày lo,hi,mid qua mỗi lần lặp."},{"title":"Sắp xếp nổi bọt với tối ưu dừng sớm","purpose":"Dừng nếu một lượt đi không có lần đổi chỗ nào.","code":"#include <stdio.h>\nint main(void) {\n    int a[] = {4, 3, 1, 2};\n    int n = 4;\n    for (int pass = 0; pass < n-1; ++pass) {\n        int changed = 0;\n        for (int j = 0; j < n-pass-1; ++j) {\n            if (a[j] > a[j+1]) {\n                int tmp=a[j]; a[j]=a[j+1]; a[j+1]=tmp;\n                changed=1;\n            }\n        }\n        if (!changed) break;\n    }\n    for (int i=0; i<n; ++i) printf(\"%d%c\",a[i],i==n-1?'\\n':' ');\n    return 0;\n}\n","output":"1 2 3 4","stdin":"","cases":[{"stdin":"","stdout":"1 2 3 4","exit":0}],"followup":""}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M4","module_title":"Mảng, thuật toán xử lý dữ liệu và chuỗi","design_case":{"title":"Tìm lần đo đầu tiên vượt ngưỡng trong chuỗi dữ liệu","problem":"Cho dãy 26, 31, 28 °C và ngưỡng giả định 30 °C. Xác định vị trí đầu tiên của phần tử lớn hơn 30.","input":["a = {26,31,28}; ngưỡng 30"],"process":["Duyệt từ đầu; nếu a[i] > 30 trả chỉ số i"],"output":["Chỉ số 1, tính từ 0"],"assumptions":["Không nhầm chỉ số mảng với số thứ tự mẫu bắt đầu từ 1"],"pseudocode":["Bắt đầu","Duyệt i = 0 đến n−1","Nếu a[i] > 30: ghi nhận i và dừng","Nếu hết vòng lặp chưa thấy: trả −1","Kết thúc"],"tests":[{"input":"26,31,28","expected":"i=1","kind":"Có kết quả"},{"input":"29,30,28","expected":"−1","kind":"Không vượt ngưỡng"},{"input":"31,32,33","expected":"i=0","kind":"Phần tử đầu tiên"}],"reflection":"Nếu dùng tìm kiếm nhị phân, điều kiện bắt buộc đối với mảng đầu vào là gì?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-15","number":15,"title":"Mảng hai chiều và kiểu cấu trúc struct","unit":"Mảng và cấu trúc","source":"Slot_13_14_15_ContiguousStorage.pptx, slide 46–70","lead":"Biểu diễn ma trận và bản ghi nhiều trường, kết hợp mảng cấu trúc trong bài toán quản lý.","objectives":["Duyệt được mảng hai chiều với hai vòng lặp.","Khai báo và sử dụng thành viên của struct.","Xây dựng được mảng bản ghi và hàm xử lý."],"sections":[{"title":"Mảng hai chiều","text":"int a[2][3] là mảng gồm 2 hàng, mỗi hàng có 3 số nguyên; trong C các phần tử được lưu theo thứ tự hàng (row-major). Khi truyền cho hàm, các kích thước cần biết phải được khai báo theo quy tắc tham số mảng C.","bullets":[]},{"title":"Khái niệm struct","text":"struct gom các thành viên có thể khác kiểu thành một bản ghi. Ví dụ struct Student { int id; double gpa; }; chứa mã và điểm. Khác với mảng, các thành viên không bắt buộc cùng kiểu; có thể xuất hiện byte đệm trong bố cục bộ nhớ.","bullets":[]},{"title":"Truy cập thành viên","text":"Với biến s kiểu struct, s.id và s.gpa truy cập các thành viên. Với con trỏ p trỏ đến một struct hợp lệ, p->id tương đương (*p).id. Có thể gán nguyên struct cho struct cùng kiểu để sao chép giá trị các thành viên.","bullets":[]},{"title":"Mảng cấu trúc","text":"struct Student ds[100]; biểu diễn tối đa 100 bản ghi. Cần theo dõi số bản ghi thực tế, kiểm tra giới hạn và đưa chức năng nhập, tìm kiếm, hiển thị thành các hàm riêng.","bullets":[]}],"example":{"title":"Mảng hai chiều: tổng từng hàng của ma trận 2×3","code":"#include <stdio.h>\nint main(void) {\n    int a[2][3] = {{1, 2, 3}, {4, 5, 6}};\n    for (int i = 0; i < 2; ++i) {\n        int sum = 0;\n        for (int j = 0; j < 3; ++j) sum += a[i][j];\n        printf(\"Hang %d: %d\\n\", i, sum);\n    }\n    return 0;\n}\n","output":"Hang 0: 6\nHang 1: 15","stdin":"","why":"Hai vòng lặp biểu diễn chỉ số hàng và cột; mỗi hàng có ba phần tử. Ví dụ struct độc lập được minh họa tại bài tập mẫu hiện có.","tests":[],"trace":["Vòng ngoài i=0, cộng các phần tử 1,2,3 được 6.","Vòng ngoài i=1, cộng 4,5,6 được 15.","Không truy cập cột j=3, vì chỉ số hợp lệ là 0,1,2."]},"mistakes":["Dùng dấu . cho con trỏ struct thay vì ->.","Đọc thêm bản ghi khi mảng đã đầy.","Cho rằng bố cục struct không có byte đệm ở mọi nền tảng."],"exercises":[{"name":"Ma trận","task":"Cho ma trận 3×3, tính tổng đường chéo chính và tìm giá trị lớn nhất.","hint":"Dùng a[i][i] cho đường chéo; chú ý chỉ số.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Quản lý sinh viên","task":"Tạo mảng 5 struct Student, tìm sinh viên có GPA cao nhất.","hint":"Xử lý trường hợp điểm bằng nhau theo quy tắc nêu trước.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Viết hàm tính tổng đường chéo chính của ma trận vuông 3×3 và hàm tìm sinh viên có điểm cao nhất; nêu hai loại dữ liệu khác nhau.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Toán tử truy cập thành viên qua con trỏ struct là?","choices":[".","&","->","%"],"answer":2,"explain":"p->field được dùng khi p là con trỏ tới struct.","rationales":["Dấu . dùng khi có biến struct, không phải con trỏ struct.","Dấu & lấy địa chỉ, không truy cập thành viên.","p->field được dùng khi p là con trỏ tới struct.","Dấu % là phép chia lấy dư trên số nguyên."]},{"q":"Trong C, int a[2][3] có bao nhiêu phần tử int?","choices":["3","6","5","2"],"answer":1,"explain":"Số phần tử = 2 × 3 = 6.","rationales":["3 chỉ là số cột.","Số phần tử = 2 × 3 = 6.","5 là tổng số hàng và cột, không phải số phần tử.","2 chỉ là số hàng."]},{"q":"Trong int a[2][3], chỉ số cột hợp lệ là gì?","choices":["0, 1, 2.","1, 2, 3.","Chỉ có 2.","0, 1, 2, 3."],"answer":0,"explain":"Mỗi hàng có ba phần tử nên cột là 0..2.","rationales":["Mỗi hàng có ba phần tử nên cột là 0..2.","Không phù hợp: 1, 2, 3. Phát biểu đúng: Mỗi hàng có ba phần tử nên cột là 0..2.","Không phù hợp: Chỉ có 2. Phát biểu đúng: Mỗi hàng có ba phần tử nên cột là 0..2.","Không phù hợp: 0, 1, 2, 3. Phát biểu đúng: Mỗi hàng có ba phần tử nên cột là 0..2."]},{"q":"Biểu thức p->id tương đương gì nếu p trỏ struct hợp lệ?","choices":["*p.id.","&p.id.","p.id.","(*p).id."],"answer":3,"explain":"Toán tử -> kết hợp giải tham chiếu và truy cập trường.","rationales":["Không phù hợp: *p.id. Phát biểu đúng: Toán tử -> kết hợp giải tham chiếu và truy cập trường.","Không phù hợp: &p.id. Phát biểu đúng: Toán tử -> kết hợp giải tham chiếu và truy cập trường.","Không phù hợp: p.id. Phát biểu đúng: Toán tử -> kết hợp giải tham chiếu và truy cập trường.","Toán tử -> kết hợp giải tham chiếu và truy cập trường."]},{"q":"struct khác mảng int ở điểm nào?","choices":["Chỉ chứa một số nguyên.","Không bao giờ được dùng trong mảng.","Có thể chứa trường có nhiều kiểu dữ liệu khác nhau.","Không có trường tên."],"answer":2,"explain":"struct mô tả một bản ghi nhiều trường có kiểu riêng.","rationales":["Không phù hợp: Chỉ chứa một số nguyên. Phát biểu đúng: struct mô tả một bản ghi nhiều trường có kiểu riêng.","Không phù hợp: Không bao giờ được dùng trong mảng. Phát biểu đúng: struct mô tả một bản ghi nhiều trường có kiểu riêng.","struct mô tả một bản ghi nhiều trường có kiểu riêng.","Không phù hợp: Không có trường tên. Phát biểu đúng: struct mô tả một bản ghi nhiều trường có kiểu riêng."]}],"summary":["Mảng hai chiều","Khái niệm struct","Truy cập thành viên","Mảng cấu trúc"],"minutes":90,"syntax":[{"label":"Mảng hai chiều và truy cập","code":"int m[2][3] = {{1, 2, 3}, {4, 5, 6}};\nint x = m[1][2];\n","meaning":"m gồm 2 hàng, 3 cột; m[1][2] là phần tử hàng thứ hai, cột thứ ba.","watch":"Chỉ số hợp lệ lần lượt 0..1 và 0..2."},{"label":"Định nghĩa kiểu cấu trúc","code":"struct SinhVien {\n    char ten[32];\n    int diem;\n};\nstruct SinhVien a = {\"An\", 9};\n","meaning":"struct tập hợp trường có thể khác kiểu; dùng toán tử dấu chấm để truy cập a.diem hoặc a.ten.","watch":"Không so sánh hai struct bằng ==; dùng cách so sánh các trường phù hợp."}],"flow":{"type":"loop","caption":"Duyệt danh sách cấu trúc tìm điểm cao nhất","start":"max = SV đầu tiên; i = 1","condition":"i < n ?","body":"Nếu diem lớn hơn max, cập nhật; i++","end":"In SV có điểm cao nhất"},"worked":{"title":"Bài mẫu: tìm sinh viên điểm cao nhất","problem":"Cho danh sách ba sinh viên (An:9, Binh:7, Chi:8); tìm người có điểm cao nhất.","steps":["Khai báo kiểu cấu trúc gồm ten và diem.","Khởi tạo mảng ba cấu trúc; giả định mảng không rỗng.","Duyệt để chọn chỉ số có điểm cao nhất và xuất tên."],"code":"#include <stdio.h>\n#include <stddef.h>\nstruct SinhVien { char ten[20]; int diem; };\nint main(void) {\n    struct SinhVien ds[] = {{\"An\", 9}, {\"Binh\", 7}, {\"Chi\", 8}};\n    size_t n = sizeof ds / sizeof ds[0];\n    size_t best = 0;\n    for (size_t i = 1; i < n; ++i) {\n        if (ds[i].diem > ds[best].diem) best = i;\n    }\n    printf(\"Cao nhat: %s (%d)\\n\", ds[best].ten, ds[best].diem);\n    return 0;\n}\n","output":"Cao nhat: An (9)","stdin":"","analysis":["Mảng cấu trúc lưu các bản ghi cùng kiểu; trường diem được truy cập bằng dấu chấm.","Nếu nhiều người cùng điểm cao nhất, thuật toán giữ người xuất hiện trước."],"tests":["Đổi diem của Chi thành 10 → Chi (10)."]},"deep_dive":{"context":"Mảng hai chiều dùng hai chỉ số, trong đó C lưu dữ liệu theo hàng (row-major). Kiểu struct gộp các trường có thể khác kiểu; nên học cả hai chủ đề qua chương trình chạy độc lập trước khi tích hợp.","contrast":[["a[i][j]","Phần tử hàng i, cột j của mảng hai chiều."],["struct Student","Một kiểu kết hợp nhiều trường có thể khác kiểu."],["s.gpa","Truy cập trường từ đối tượng struct."],["p->gpa","Truy cập trường khi p trỏ đến struct hợp lệ."]],"pitfall":"Không dùng cùng một vòng lặp như thể mọi hàng có số cột thay đổi; đối với int a[2][3], chỉ số cột hợp lệ 0,1,2.","challenge":"Viết hàm tính tổng đường chéo chính của ma trận vuông 3×3 và hàm tìm sinh viên có điểm cao nhất; nêu hai loại dữ liệu khác nhau."},"lab_examples":[{"title":"Duyệt mảng 2 chiều và tính tổng từng hàng","purpose":"Bổ sung ví dụ ma trận hoàn chỉnh độc lập với phần struct.","code":"#include <stdio.h>\nint main(void) {\n    int a[2][3] = {{1, 2, 3}, {4, 5, 6}};\n    for (int i = 0; i < 2; ++i) {\n        int sum = 0;\n        for (int j = 0; j < 3; ++j) sum += a[i][j];\n        printf(\"Hang %d: %d\\n\", i, sum);\n    }\n    return 0;\n}\n","output":"Hang 0: 6\nHang 1: 15","stdin":"","cases":[{"stdin":"","stdout":"Hang 0: 6\nHang 1: 15","exit":0}],"followup":"Sửa thành ma trận 3×2 và xác định lại giới hạn của vòng lặp."},{"title":"Truy cập struct qua con trỏ","purpose":"So sánh dấu chấm và toán tử ->.","code":"#include <stdio.h>\nstruct Student { int id; double score; };\nint main(void) {\n    struct Student s = {101, 8.5};\n    struct Student *p = &s;\n    p->score = 9.0;\n    printf(\"ID=%d Diem=%.1f\\n\", s.id, s.score);\n    return 0;\n}\n","output":"ID=101 Diem=9.0","stdin":"","cases":[{"stdin":"","stdout":"ID=101 Diem=9.0","exit":0}],"followup":""}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"teaching_note":"Đề xuất 2 tiết riêng: ma trận hai chiều rồi struct; phải chạy ví dụ cho cả hai nội dung.","module":"M4","module_title":"Mảng, thuật toán xử lý dữ liệu và chuỗi","design_case":{"title":"Tổ chức dữ liệu hai máy theo ba lần đo","problem":"Bảng nhiệt độ máy 1 là 25,26,27 °C; máy 2 là 28,29,30 °C. Lưu trong mảng 2×3 và tính trung bình theo hàng.","input":["T[2][3] = {{25,26,27},{28,29,30}}"],"process":["Duyệt từng hàng, tính tổng rồi chia cho 3"],"output":["Trung bình máy 1 = 26 °C; máy 2 = 29 °C"],"assumptions":["Không suy diễn tình trạng kỹ thuật từ trung bình đơn lẻ"],"pseudocode":["Bắt đầu","Với từng hàng i = 0..1: đặt tổng = 0","Với j = 0..2: cộng T[i][j]","Tính trung bình hàng bằng phép chia số thực","Xuất hai trung bình; kết thúc"],"tests":[{"input":"Hàng 1: 25,26,27","expected":"26 °C","kind":"Máy 1"},{"input":"Hàng 2: 28,29,30","expected":"29 °C","kind":"Máy 2"},{"input":"Hàng 0 phần tử","expected":"Không hợp lệ với ma trận cố định 2×3","kind":"Ràng buộc kích thước"}],"reflection":"Khi nào nên dùng struct để lưu thêm mã máy, thời gian và các giá trị đo?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-16","number":16,"title":"Chuỗi ký tự trong C và ký tự kết thúc NUL","unit":"Chuỗi ký tự","source":"Slot_16_17_18_Strings.pptx, slide 3–12","lead":"Hiểu chuỗi C là một mảng char kết thúc bằng byte 0 và phân biệt độ dài logic với dung lượng.","objectives":["Khai báo, khởi tạo và duyệt được chuỗi C.","Giải thích được byte kết thúc NUL \\0 và dung lượng bộ đệm.","Phân biệt chuỗi có thể sửa với string literal."],"sections":[{"title":"Chuỗi theo quy ước C","text":"Chuỗi C là dãy char có byte kết thúc NUL (\\0). Độ dài chuỗi là số ký tự trước NUL, khác số byte cấp phát. Ví dụ char s[]=\"ABC\" gồm bốn phần tử: A, B, C và NUL.","bullets":[]},{"title":"Khai báo và khởi tạo","text":"char text[20] = \"Hello\"; tạo mảng có thể sửa, dung lượng 20 byte. char *p = \"Hello\"; p chỉ đến literal và không được ghi sửa qua p. Kích thước của mảng tại nơi khai báo có thể lấy bằng sizeof text.","bullets":[]},{"title":"Độ dài byte và UTF-8","text":"strlen(s) đếm số byte trước NUL, không mặc định là số ký tự Unicode khi chuỗi mã UTF-8. Trong các ví dụ nhập môn sử dụng ký tự ASCII để dễ quan sát chỉ số và độ dài. Việc xử lý tiếng Việt có dấu cần quan tâm mã hóa và locale.","bullets":[]},{"title":"In chuỗi","text":"printf(\"%s\", s) yêu cầu s trỏ tới một chuỗi kết thúc NUL hợp lệ. puts(s) in chuỗi và thêm xuống dòng. Không dùng %s để in mảng char chưa có NUL trong phạm vi truy cập.","bullets":[]}],"example":{"title":"Độ dài và dữ liệu chuỗi","code":"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    char s[] = \"UTEHY\";\n    printf(\"Chuoi: %s\\n\", s);\n    printf(\"Do dai: %zu\\n\", strlen(s));\n    printf(\"Kich thuoc mang: %zu\\n\", sizeof s);\n    return 0;\n}\n","output":"Chuoi: UTEHY\nDo dai: 5\nKich thuoc mang: 6","stdin":"","why":"Đọc chương trình theo thứ tự thực thi, dự đoán kết quả trước khi chạy và đối chiếu các bước giải thích ngay dưới mã ví dụ.","tests":[],"trace":["Mảng s được khởi tạo với 5 ký tự ASCII và 1 byte NUL.","strlen(s)=5 đếm byte trước NUL; sizeof s=6 là dung lượng toàn bộ mảng (theo đơn vị char)."]},"mistakes":["Quên dành một byte cho NUL.","Cố thay đổi ký tự bên trong string literal.","Đồng nhất strlen với số ký tự Unicode."],"exercises":[{"name":"Đếm nguyên âm ASCII","task":"Nhập một chuỗi tối đa 99 byte, đếm a/e/i/o/u không phân biệt hoa thường.","hint":"Dùng fgets, ctype.h, và kiểm tra ký tự.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Phân tích mảng","task":"Giải thích sizeof(\"AB\"), strlen(\"AB\"), và giá trị byte cuối.","hint":"Literal \"AB\" có 3 byte gồm NUL.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Cho char s[6]=\"AB\"; xác định sizeof, strlen và các phần tử được khởi tạo bằng 0.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Chuỗi char s[]=\"AB\" có sizeof s bằng?","choices":["Không xác định","3","4","2"],"answer":1,"explain":"Mảng chứa A, B và NUL, tổng 3 byte.","rationales":["Kích thước mảng có thể xác định ngay tại thời điểm biên dịch.","Mảng chứa A, B và NUL, tổng 3 byte.","4 lớn hơn dung lượng thực của mảng được suy ra từ literal.","Không tính byte NUL kết thúc."]},{"q":"strlen trả về gì?","choices":["Số byte trước ký tự NUL","Số từ","Dung lượng tối đa của buffer","Số ký tự Unicode"],"answer":0,"explain":"strlen đếm byte trước NUL của chuỗi C.","rationales":["strlen đếm byte trước NUL của chuỗi C.","strlen không đếm số từ.","strlen không biết dung lượng tối đa của bộ đệm.","strlen tính byte, không tự đếm mã điểm Unicode."]},{"q":"sizeof \"AB\" có giá trị bao nhiêu trên hệ thống C thông dụng?","choices":["4 byte do char luôn 16 bit.","2 byte.","Không tính được.","3 byte."],"answer":3,"explain":"Literal có hai ký tự A,B và một byte NUL.","rationales":["Không phù hợp: 4 byte do char luôn 16 bit. Phát biểu đúng: Literal có hai ký tự A,B và một byte NUL.","Không phù hợp: 2 byte. Phát biểu đúng: Literal có hai ký tự A,B và một byte NUL.","Không phù hợp: Không tính được. Phát biểu đúng: Literal có hai ký tự A,B và một byte NUL.","Literal có hai ký tự A,B và một byte NUL."]},{"q":"strlen(\"AB\") bằng bao nhiêu?","choices":["0.","Không xác định.","2.","3."],"answer":2,"explain":"strlen không tính byte kết thúc NUL.","rationales":["Không phù hợp: 0. Phát biểu đúng: strlen không tính byte kết thúc NUL.","Không phù hợp: Không xác định. Phát biểu đúng: strlen không tính byte kết thúc NUL.","strlen không tính byte kết thúc NUL.","Không phù hợp: 3. Phát biểu đúng: strlen không tính byte kết thúc NUL."]},{"q":"Với UTF-8, strlen trả về gì?","choices":["Luôn số chữ cái tiếng Việt.","Số byte trước NUL, không mặc định là số ký tự Unicode.","Luôn bằng sizeof con trỏ.","Luôn gấp đôi số chữ."],"answer":1,"explain":"UTF-8 có thể dùng nhiều byte cho một ký tự.","rationales":["Không phù hợp: Luôn số chữ cái tiếng Việt. Phát biểu đúng: UTF-8 có thể dùng nhiều byte cho một ký tự.","UTF-8 có thể dùng nhiều byte cho một ký tự.","Không phù hợp: Luôn bằng sizeof con trỏ. Phát biểu đúng: UTF-8 có thể dùng nhiều byte cho một ký tự.","Không phù hợp: Luôn gấp đôi số chữ. Phát biểu đúng: UTF-8 có thể dùng nhiều byte cho một ký tự."]}],"summary":["Chuỗi theo quy ước C","Khai báo và khởi tạo","Độ dài byte và UTF-8","In chuỗi"],"minutes":45,"syntax":[{"label":"Khai báo và kết thúc chuỗi C","code":"char ten[] = \"HVAC\";\n/* ten chứa: H, V, A, C, \\0 */\nsize_t n = strlen(ten);\n","meaning":"Chuỗi C kết thúc bằng byte NUL (\\0), strlen đếm số byte trước byte này, không gồm NUL.","watch":"Đoạn mã có strlen yêu cầu <string.h>; ký tự UTF-8 có thể chiếm nhiều byte."}],"flow":{"type":"loop","caption":"Đếm số byte trước ký tự kết thúc NUL","start":"i = 0","condition":"s[i] != NUL ?","body":"i++","end":"Xuất độ dài i"},"worked":{"title":"Bài mẫu: tự đếm độ dài chuỗi ASCII","problem":"Cho chuỗi \"HVAC\"; dùng vòng lặp tự đếm số byte trước byte NUL, không gọi strlen.","steps":["Khởi tạo mảng char s[] = \"HVAC\".","Cho i=0, tiếp tục khi s[i] khác ký tự NUL.","Xuất i là số byte dữ liệu của chuỗi ASCII."],"code":"#include <stdio.h>\n#include <stddef.h>\nint main(void) {\n    char s[] = \"HVAC\";\n    size_t i = 0;\n    while (s[i] != '\\0') ++i;\n    printf(\"Do dai = %zu\\n\", i);\n    return 0;\n}\n","output":"Do dai = 4","stdin":"","analysis":["Trong bộ nhớ có 5 byte, gồm 4 ký tự ASCII và 1 byte NUL.","Số ký tự hiển thị không luôn bằng số byte nếu chuỗi có ký tự UTF-8 nhiều byte."],"tests":["Thay bằng \"C\" → 1.","Thay bằng \"\" → 0."]},"deep_dive":{"context":"Một chuỗi C kết thúc bởi byte NUL, vì vậy số byte cấp phát thường lớn hơn độ dài strlen. Với UTF-8, một ký tự hiển thị có thể gồm nhiều byte; strlen không đếm số chữ tiếng Việt.","contrast":[["sizeof \"AB\"","Bằng 3 vì có A, B và byte NUL trong literal."],["strlen(\"AB\")","Bằng 2 vì đếm byte trước NUL."],["char a[]=\"AB\"","Mảng sửa được có 3 byte."],["const char *p=\"AB\"","Con trỏ đến literal; không sửa nội dung literal."]],"pitfall":"Không dùng printf(\"%s\", array) nếu không chứng minh trong vùng nhớ có byte NUL hợp lệ.","challenge":"Cho char s[6]=\"AB\"; xác định sizeof, strlen và các phần tử được khởi tạo bằng 0."},"lab_examples":[{"title":"Bảng byte của chuỗi ASCII","purpose":"In chỉ số và mã byte của chữ A, B, C cùng ký tự kết thúc.","code":"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    char s[] = \"ABC\";\n    printf(\"sizeof=%zu strlen=%zu\\n\", sizeof s, strlen(s));\n    for (size_t i = 0; i < sizeof s; ++i)\n        printf(\"byte[%zu]=%u\\n\", i, (unsigned)(unsigned char)s[i]);\n    return 0;\n}\n","output":"sizeof=4 strlen=3\nbyte[0]=65\nbyte[1]=66\nbyte[2]=67\nbyte[3]=0","stdin":"","cases":[{"stdin":"","stdout":"sizeof=4 strlen=3\nbyte[0]=65\nbyte[1]=66\nbyte[2]=67\nbyte[3]=0","exit":0}],"followup":"Vẽ bốn ô nhớ và chỉ vị trí NUL (không phải chữ số 0)."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M4","module_title":"Mảng, thuật toán xử lý dữ liệu và chuỗi","design_case":{"title":"Lưu tên mã thiết bị bằng chuỗi C","problem":"Lưu nhãn FAN1 trong một mảng char. Phân biệt bốn ký tự hiển thị và ký tự kết thúc NUL.","input":["Chuỗi ASCII \"FAN1\""],"process":["Sao chép vào bộ đệm có ít nhất 5 phần tử char"],"output":["strlen = 4; cần tối thiểu 5 phần tử char, kể cả NUL"],"assumptions":["sizeof(char) luôn bằng 1 byte theo C; số bit mỗi byte (CHAR_BIT) phụ thuộc triển khai; UTF-8 có thể dùng nhiều byte cho một ký tự Unicode"],"pseudocode":["Bắt đầu","Xác định chiều dài nhãn 4 ký tự","Cấp bộ đệm ít nhất 5 char","Ghi F, A, N, 1, rồi ký tự NUL","Dùng strlen để đo độ dài chuỗi"],"tests":[{"input":"\"FAN1\"","expected":"strlen=4","kind":"Thông thường"},{"input":"\"\"","expected":"strlen=0; vẫn cần NUL","kind":"Biên"},{"input":"char nhan[4]","expected":"Không đủ để chứa 4 ký tự và NUL","kind":"Không hợp lệ"}],"reflection":"Vì sao strlen(\"FAN1\") khác sizeof(\"FAN1\")?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-17","number":17,"title":"Nhập xuất chuỗi và các hàm string.h","unit":"Chuỗi ký tự","source":"Slot_16_17_18_Strings.pptx, slide 13–34","lead":"Nhập chuỗi đúng giới hạn, so sánh theo từ điển và dùng thư viện chuỗi an toàn.","objectives":["Sử dụng fgets để nhận chuỗi có khoảng trắng.","Dùng strlen, strcmp, strcpy, strcat có kiểm tra kích thước.","Giải thích vì sao gets và strupr không phù hợp làm hàm chuẩn."],"sections":[{"title":"Nhập an toàn bằng fgets","text":"fgets(buf, sizeof buf, stdin) giới hạn số byte đọc và thêm NUL khi thành công. Nếu còn chỗ, ký tự xuống dòng có thể nằm trong chuỗi; có thể tìm và loại bằng strcspn. Khi đầu vào quá dài, phần còn lại vẫn trong stdin; cần xử lý theo yêu cầu.","bullets":[]},{"title":"Các hàm cơ bản","text":"strlen đo độ dài byte; strcmp so sánh theo thứ tự từ điển (dấu âm/0/dương, không phải bắt buộc -1,0,1); strcpy sao chép chuỗi; strcat nối vào cuối. strcpy và strcat không tự kiểm tra dung lượng đích nên chỉ sử dụng khi đã chứng minh đủ chỗ.","bullets":[]},{"title":"Tìm kiếm và tách chuỗi","text":"strstr tìm chuỗi con và trả con trỏ hoặc NULL. strtok tách chuỗi có thể sửa theo tập delimiter, đồng thời sửa bộ đệm và có trạng thái nội bộ, cần thận trọng khi dùng nhiều phép tách lồng nhau.","bullets":[]},{"title":"Phân biệt hàm chuẩn và hàm mở rộng","text":"gets đã bị loại khỏi C11 vì rủi ro tràn bộ đệm; không dùng. strupr và strlwr không phải hàm thư viện chuẩn ISO C. Để đổi chữ ASCII, duyệt từng byte và dùng toupper/tolower đúng miền đối số ctype.h.","bullets":[]}],"example":{"title":"Đọc tên có khoảng trắng và bỏ xuống dòng","code":"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    char ten[80];\n    if (!fgets(ten, sizeof ten, stdin)) return 1;\n    ten[strcspn(ten, \"\\n\")] = '\\0';\n    printf(\"Xin chao, %s!\\n\", ten);\n    return 0;\n}\n","output":"Xin chao, Nguyen Van A!","stdin":"Nguyen Van A","why":"strcspn tìm vị trí đầu tiên chứa ký tự xuống dòng hoặc vị trí NUL; việc gán NUL an toàn trong cả hai trường hợp khi fgets thành công.","tests":[],"trace":["fgets đọc cả dấu cách trong tên vào bộ đệm đã cấp.","strcspn tìm vị trí newline; gán NUL loại bỏ newline trước khi in."]},"mistakes":["Dùng gets để nhập không giới hạn.","Dùng == thay strcmp để so sánh nội dung hai chuỗi.","Không kiểm tra kích thước trước strcpy/strcat."],"exercises":[{"name":"So sánh họ tên","task":"Nhập hai chuỗi không rỗng, dùng strcmp và in quan hệ theo thứ tự từ điển.","hint":"Phân biệt kết quả âm, bằng 0 và dương.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Chuỗi con","task":"Nhập dòng văn bản và từ khóa; tìm chuỗi con bằng strstr.","hint":"Xử lý trường hợp không thấy (NULL).","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Viết hàm nối hai chuỗi vào đích có dung lượng được truyền vào, trả trạng thái thành công/thất bại.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"Hàm nào so sánh nội dung hai chuỗi C?","choices":["strcmp","sizeof","scanf","=="],"answer":0,"explain":"strcmp so sánh chuỗi theo byte và trả dấu âm/0/dương.","rationales":["strcmp so sánh chuỗi theo byte và trả dấu âm/0/dương.","sizeof trả kích thước vùng lưu trữ hoặc kiểu.","scanf là hàm nhập định dạng.","== so sánh địa chỉ sau chuyển đổi mảng, không so sánh nội dung chuỗi."]},{"q":"Tại sao không dùng gets?","choices":["Không đọc được dấu cách","Không trả về giá trị","Không có trong C89","Không giới hạn bộ đệm, gây tràn"],"answer":3,"explain":"gets không kiểm soát kích thước buffer.","rationales":["gets vẫn có thể đọc khoảng trắng trong chuỗi.","gets có giá trị trả về, không phải hàm void.","gets có trong C89, không phải đến sau C89 mới xuất hiện.","gets không kiểm soát kích thước buffer."]},{"q":"strcmp(a,b) trả âm khi nào?","choices":["Khi a bằng b.","Khi a chứa dấu cách.","Khi a đứng trước b theo so sánh byte của C.","Khi chuỗi a dài hơn b."],"answer":2,"explain":"Không yêu cầu kết quả phải chính xác -1.","rationales":["Không phù hợp: Khi a bằng b. Phát biểu đúng: Không yêu cầu kết quả phải chính xác -1.","Không phù hợp: Khi a chứa dấu cách. Phát biểu đúng: Không yêu cầu kết quả phải chính xác -1.","Không yêu cầu kết quả phải chính xác -1.","Không phù hợp: Khi chuỗi a dài hơn b. Phát biểu đúng: Không yêu cầu kết quả phải chính xác -1."]},{"q":"Vì sao không nên dùng gets?","choices":["Vì gets luôn chỉ đọc 1 ký tự.","Không có cách chỉ định dung lượng đích, gây nguy cơ tràn.","Vì gets tự động cấp phát vô hạn.","Vì gets chỉ có trong Java."],"answer":1,"explain":"gets đã bị loại khỏi C11.","rationales":["Không phù hợp: Vì gets luôn chỉ đọc 1 ký tự. Phát biểu đúng: gets đã bị loại khỏi C11.","gets đã bị loại khỏi C11.","Không phù hợp: Vì gets tự động cấp phát vô hạn. Phát biểu đúng: gets đã bị loại khỏi C11.","Không phù hợp: Vì gets chỉ có trong Java. Phát biểu đúng: gets đã bị loại khỏi C11."]},{"q":"Trước khi strcat(dest, src), phải bảo đảm điều gì?","choices":["Dung lượng dest đủ chứa chuỗi nối cùng byte NUL.","dest và src phải cùng một địa chỉ.","dest là literal không sửa được.","src phải luôn rỗng."],"answer":0,"explain":"strcat không có tham số kiểm soát sức chứa đích.","rationales":["strcat không có tham số kiểm soát sức chứa đích.","Không phù hợp: dest và src phải cùng một địa chỉ. Phát biểu đúng: strcat không có tham số kiểm soát sức chứa đích.","Không phù hợp: dest là literal không sửa được. Phát biểu đúng: strcat không có tham số kiểm soát sức chứa đích.","Không phù hợp: src phải luôn rỗng. Phát biểu đúng: strcat không có tham số kiểm soát sức chứa đích."]}],"summary":["Nhập an toàn bằng fgets","Các hàm cơ bản","Tìm kiếm và tách chuỗi","Phân biệt hàm chuẩn và hàm mở rộng"],"minutes":45,"syntax":[{"label":"Đọc chuỗi có khoảng trắng và bỏ newline","code":"char ten[64];\nif (fgets(ten, sizeof ten, stdin) != NULL) {\n    ten[strcspn(ten, \"\\n\")] = '\\0';\n}\n","meaning":"fgets có giới hạn bộ đệm; strcspn tìm vị trí byte newline hoặc vị trí NUL nếu không có newline.","watch":"Cần include <stdio.h> và <string.h>; dòng quá dài có thể bị cắt, cần chính sách xử lý."},{"label":"So sánh chuỗi","code":"if (strcmp(a, b) == 0) { /* nội dung bằng nhau */ }\n","meaning":"strcmp so sánh nội dung chuỗi kết thúc NUL theo thứ tự byte; == giữa con trỏ không so sánh nội dung.","watch":"Không sử dụng strupr/strlwr như thể là hàm thư viện C chuẩn."}],"flow":{"type":"sequence","caption":"Xử lý một dòng nhập họ tên","steps":["Đọc dòng bằng fgets","Kiểm tra kết quả khác NULL","Tìm và thay newline bằng NUL","In hoặc xử lý nội dung chuỗi"]},"worked":{"title":"Bài mẫu: so sánh và tìm chuỗi con","problem":"Cho hai tên ASCII An và Binh; kiểm tra quan hệ sắp xếp bằng strcmp và tìm từ khóa lap trong chuỗi Hoc lap trinh C.","steps":["Khai báo các con trỏ const char* đến hai chuỗi và chuỗi văn bản.","Dùng dấu của strcmp, không so sánh bằng −1.","Dùng strstr và kiểm tra kết quả khác NULL."],"code":"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    const char *a = \"An\";\n    const char *b = \"Binh\";\n    printf(\"So sanh: %s\\n\", strcmp(a,b)<0 ? \"An truoc\" : \"An khong truoc\");\n    const char *s = \"Hoc lap trinh C\";\n    printf(\"Tim lap: %s\\n\", strstr(s,\"lap\")!=NULL ? \"co\" : \"khong\");\n    return 0;\n}\n","output":"So sanh: An truoc\nTim lap: co","stdin":"","analysis":["strcmp trả số âm khi tên An đứng trước Binh theo thứ tự byte.","strstr trả về một con trỏ khi tìm được chuỗi con lap."],"tests":["Thay tên bằng hai chuỗi bằng nhau → strcmp bằng 0; thay từ khóa xyz → strstr trả NULL."]},"deep_dive":{"context":"Các hàm chuỗi C giả thiết vùng nhớ kết thúc bằng NUL hợp lệ. strcmp trả số âm/0/dương, không bảo đảm chính xác −1/+1. Khi ghép chuỗi, cần chứng minh tổng độ dài và NUL không vượt dung lượng đích.","contrast":[["strlen","Đếm số byte trước NUL, không tính NUL."],["strcmp","So sánh byte chuỗi; trả giá trị âm, 0 hoặc dương."],["strstr","Trả con trỏ đến vị trí xuất hiện hoặc NULL."],["strcat","Ghi nối chuỗi; có thể tràn nếu dung lượng đích thiếu."]],"pitfall":"Không dùng gets; không giả định fgets đã đọc hết cả dòng nếu đầu vào dài hơn bộ đệm.","challenge":"Viết hàm nối hai chuỗi vào đích có dung lượng được truyền vào, trả trạng thái thành công/thất bại."},"lab_examples":[{"title":"So sánh và tìm chuỗi con","purpose":"Bài tập mẫu mới khác thao tác chào hỏi.","code":"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    const char *a = \"An\";\n    const char *b = \"Binh\";\n    printf(\"So sanh: %s\\n\", strcmp(a,b)<0 ? \"An truoc\" : \"An khong truoc\");\n    const char *s = \"Hoc lap trinh C\";\n    printf(\"Tim lap: %s\\n\", strstr(s,\"lap\")!=NULL ? \"co\" : \"khong\");\n    return 0;\n}\n","output":"So sanh: An truoc\nTim lap: co","stdin":"","cases":[{"stdin":"","stdout":"So sanh: An truoc\nTim lap: co","exit":0}],"followup":"Thay a=\"Chi\"; giải thích vì sao không kiểm tra strcmp == -1."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M4","module_title":"Mảng, thuật toán xử lý dữ liệu và chuỗi","design_case":{"title":"Đọc và chuẩn hóa một dòng nhật ký nhiệt độ","problem":"Dòng nhập mẫu “T:28.5\\n” chứa ký tự xuống dòng. Sử dụng fgets và thay dấu xuống dòng bằng NUL nếu có.","input":["Dòng văn bản T:28.5 và dấu xuống dòng"],"process":["fgets; kiểm tra NULL; tìm dấu xuống dòng; gán NUL"],"output":["Chuỗi “T:28.5” sau chuẩn hóa"],"assumptions":["Phải kiểm tra độ dài bộ đệm và trường hợp dòng quá dài"],"pseudocode":["Bắt đầu","Đọc dòng bằng fgets","Nếu thất bại: xử lý EOF/lỗi","Nếu có ký tự newline: thay bằng NUL","Sử dụng chuỗi đã xử lý"],"tests":[{"input":"\"T:28.5\\n\"","expected":"\"T:28.5\"","kind":"Thông thường"},{"input":"\"\\n\"","expected":"Chuỗi rỗng","kind":"Biên"},{"input":"Đầu vào > bộ đệm","expected":"Phát hiện và xử lý dòng chưa đọc hết","kind":"An toàn"}],"reflection":"Vì sao không được luôn giả định fgets đã đọc đủ toàn bộ dòng?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-18","number":18,"title":"Mảng chuỗi, chuẩn hóa và tách dữ liệu","unit":"Chuỗi ký tự","source":"Slot_16_17_18_Strings.pptx, slide 35–49","lead":"Tổ chức tập hợp chuỗi và tạo các hàm tự viết để chuẩn hóa dữ liệu văn bản.","objectives":["Khai báo và duyệt được mảng các chuỗi.","Cài đặt hàm loại khoảng trắng đầu/cuối theo ASCII.","Giải thích sự khác biệt giữa mảng char hai chiều và mảng con trỏ char."],"sections":[{"title":"Mảng các chuỗi","text":"char names[3][32] là ba vùng lưu trữ, mỗi vùng 32 byte. Khi đọc, phải bảo đảm mỗi chuỗi được kết thúc NUL. char *names[] là mảng các con trỏ, cách quản lý vùng nhớ khác và có thể trỏ đến các literal không được sửa.","bullets":[]},{"title":"Chuẩn hóa khoảng trắng","text":"Có thể loại dấu cách đầu bằng cách tìm vị trí ký tự đầu không phải khoảng trắng rồi dời dữ liệu. Để loại khoảng trắng cuối, đi từ cuối chuỗi về trước và đặt NUL. Khi xử lý ký tự theo ctype.h, nhớ ép byte về unsigned char.","bullets":[]},{"title":"Tách theo delimiter","text":"strtok có thể dùng để phân tích dữ liệu phân cách bằng dấu phẩy hoặc khoảng trắng, nhưng làm thay đổi chuỗi gốc và không giữ trường rỗng. Với dữ liệu CSV có dấu nháy kép và trường rỗng, cần trình phân tích đầy đủ hơn strtok.","bullets":[]},{"title":"Bài toán thực tế","text":"Quản lý danh sách họ tên yêu cầu xác định quy tắc hợp lệ, chiều dài tối đa, xử lý ký tự ngoài ASCII và cách so sánh. Với văn bản tiếng Việt UTF-8, các thao tác theo byte không tương đương xử lý từng ký tự tiếng Việt.","bullets":[]}],"example":{"title":"In mảng ba tên sinh viên","code":"#include <stdio.h>\nint main(void) {\n    char names[3][32] = {\"An\", \"Binh\", \"Chi\"};\n    for (int i = 0; i < 3; ++i)\n        printf(\"%d. %s\\n\", i + 1, names[i]);\n    return 0;\n}\n","output":"1. An\n2. Binh\n3. Chi","stdin":"","why":"Đọc chương trình theo thứ tự thực thi, dự đoán kết quả trước khi chạy và đối chiếu các bước giải thích ngay dưới mã ví dụ.","tests":[],"trace":["names là mảng gồm ba hàng, mỗi hàng có sức chứa 32 char.","Vòng lặp i=0..2 sử dụng %s để in từng tên, với số thứ tự i+1."]},"mistakes":["Dùng strcpy vào chuỗi đích không đủ chỗ.","Đọc chuỗi không có NUL.","Cho rằng strtok hỗ trợ mọi định dạng CSV."],"exercises":[{"name":"Sắp tên ASCII","task":"Nhập tối đa 10 tên ASCII, mỗi tên tối đa 29 byte; sắp theo strcmp.","hint":"Sử dụng mảng char names[10][30] và strcmp, trao đổi bằng buffer tạm.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Hàm rTrim","task":"Viết hàm bỏ khoảng trắng cuối của chuỗi có thể sửa.","hint":"Dùng strlen; cẩn thận chuỗi rỗng tránh giảm chỉ số âm.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Sắp xếp 5 chuỗi ASCII bằng strcmp, mô tả vì sao cách này không phải thứ tự từ điển tiếng Việt có dấu.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"char a[3][20] cho phép lưu tối đa bao nhiêu chuỗi riêng?","choices":["Không giới hạn","60","20","3"],"answer":3,"explain":"Có ba hàng, mỗi hàng chứa tối đa 19 byte nội dung cùng NUL.","rationales":["Mảng có số hàng cố định, không phải vô hạn.","60 là tổng byte chứa của 3 hàng, không phải số chuỗi.","20 là dung lượng mỗi hàng tính theo byte, không phải số chuỗi.","Có ba hàng, mỗi hàng chứa tối đa 19 byte nội dung cùng NUL."]},{"q":"strtok có thay đổi chuỗi nguồn không?","choices":["Không bao giờ","Không nhận chuỗi","Có, nó chèn các byte NUL khi tách","Chỉ khi lỗi"],"answer":2,"explain":"strtok sửa nội dung vùng nhớ nguồn để tách token.","rationales":["strtok sửa các dấu phân cách thành byte NUL.","strtok nhận một chuỗi có thể sửa hoặc NULL cho các lượt tiếp theo.","strtok sửa nội dung vùng nhớ nguồn để tách token.","Việc sửa chuỗi là hành vi thường xuyên, không chỉ khi lỗi."]},{"q":"strtok có bảo toàn các trường rỗng giữa hai dấu phẩy không?","choices":["Có, luôn trả chuỗi rỗng.","Không.","Có, nếu dùng UTF-8.","Chỉ khi trường là số nguyên."],"answer":1,"explain":"Các delimiter liên tiếp được xem là vùng phân cách, không tạo token rỗng.","rationales":["Không phù hợp: Có, luôn trả chuỗi rỗng. Phát biểu đúng: Các delimiter liên tiếp được xem là vùng phân cách, không tạo token rỗng.","Các delimiter liên tiếp được xem là vùng phân cách, không tạo token rỗng.","Không phù hợp: Có, nếu dùng UTF-8. Phát biểu đúng: Các delimiter liên tiếp được xem là vùng phân cách, không tạo token rỗng.","Không phù hợp: Chỉ khi trường là số nguyên. Phát biểu đúng: Các delimiter liên tiếp được xem là vùng phân cách, không tạo token rỗng."]},{"q":"strtok cần bộ đệm đầu vào có tính chất gì?","choices":["Là bộ đệm char có thể sửa.","Phải trỏ tới string literal cố định.","Phải có ít nhất 1000 byte.","Phải là const char*."],"answer":0,"explain":"strtok đặt byte NUL tại vị trí delimiter.","rationales":["strtok đặt byte NUL tại vị trí delimiter.","Không phù hợp: Phải trỏ tới string literal cố định. Phát biểu đúng: strtok đặt byte NUL tại vị trí delimiter.","Không phù hợp: Phải có ít nhất 1000 byte. Phát biểu đúng: strtok đặt byte NUL tại vị trí delimiter.","Không phù hợp: Phải là const char*. Phát biểu đúng: strtok đặt byte NUL tại vị trí delimiter."]},{"q":"Sắp xếp tên tiếng Việt bằng strcmp thuần trên UTF-8 sẽ thế nào?","choices":["Tự bỏ dấu thanh trước khi so sánh.","Chuyển văn bản thành ASCII.","Luôn đúng thứ tự tiếng Việt.","Không bảo đảm thứ tự từ điển tiếng Việt theo ngôn ngữ."],"answer":3,"explain":"strcmp so sánh các byte, không xử lý quy tắc xếp chữ tiếng Việt.","rationales":["Không phù hợp: Tự bỏ dấu thanh trước khi so sánh. Phát biểu đúng: strcmp so sánh các byte, không xử lý quy tắc xếp chữ tiếng Việt.","Không phù hợp: Chuyển văn bản thành ASCII. Phát biểu đúng: strcmp so sánh các byte, không xử lý quy tắc xếp chữ tiếng Việt.","Không phù hợp: Luôn đúng thứ tự tiếng Việt. Phát biểu đúng: strcmp so sánh các byte, không xử lý quy tắc xếp chữ tiếng Việt.","strcmp so sánh các byte, không xử lý quy tắc xếp chữ tiếng Việt."]}],"summary":["Mảng các chuỗi","Chuẩn hóa khoảng trắng","Tách theo delimiter","Bài toán thực tế"],"minutes":45,"syntax":[{"label":"Khai báo mảng chuỗi","code":"char ds[3][20] = {\"An\", \"Binh\", \"Chi\"};\n/* ds[i] là một chuỗi có sức chứa 20 char */\n","meaning":"Mỗi hàng là một mảng char có vùng nhớ riêng, có thể truy cập bằng ds[i][j].","watch":"Trước khi chép/ghép chuỗi phải kiểm tra giới hạn kích thước mảng đích."},{"label":"Tách token bằng strtok","code":"char *p = strtok(buf, \",\");\nwhile (p != NULL) {\n    /* sử dụng p */\n    p = strtok(NULL, \",\");\n}\n","meaning":"strtok sửa nội dung bộ đệm và duy trì trạng thái phân tách giữa các lần gọi.","watch":"Không gọi strtok trên chuỗi literal; không dùng khi cần bảo toàn chuỗi gốc."}],"flow":{"type":"loop","caption":"Rút gọn các khoảng trắng liên tiếp","start":"read=0; write=0","condition":"s[read] != NUL ?","body":"Ghi byte hợp lệ; tăng read","end":"Bỏ khoảng trắng cuối; thêm NUL"},"worked":{"title":"Bài mẫu: chuẩn hóa khoảng trắng ASCII","problem":"Cho chuỗi \"  Lap   trinh   C  \"; xóa khoảng trắng đầu/cuối và gộp nhiều dấu cách liên tiếp thành một.","steps":["Duyệt từ trái sang phải bằng hai chỉ số đọc và ghi.","Chỉ ghi dấu cách khi đã có ký tự trước đó và ký tự trước không phải dấu cách.","Bỏ dấu cách cuối (nếu có), đặt byte NUL và in."],"code":"#include <stdio.h>\n#include <stddef.h>\nint main(void) {\n    char s[] = \"  Lap   trinh   C  \";\n    size_t rd = 0, wr = 0;\n    while (s[rd] != '\\0') {\n        char c = s[rd++];\n        if (c != ' ' || (wr > 0 && s[wr-1] != ' ')) {\n            s[wr++] = c;\n        }\n    }\n    if (wr > 0 && s[wr-1] == ' ') --wr;\n    s[wr] = '\\0';\n    printf(\"Chuan hoa: %s\\n\", s);\n    return 0;\n}\n","output":"Chuan hoa: Lap trinh C","stdin":"","analysis":["Hàm này chỉ chuẩn hóa byte dấu cách ASCII, chưa xử lý tab, xuống dòng hoặc chuẩn Unicode.","Thao tác tại chỗ an toàn vì chỉ số ghi không vượt chỉ số đọc."],"tests":["Thay s=\"    \" → chuỗi rỗng.","Thay s=\"A B\" → giữ nguyên."]},"deep_dive":{"context":"Mảng char[][N] chứa các bộ đệm cố định liên tiếp, còn mảng char* chứa các giá trị con trỏ. strtok làm thay đổi bộ đệm đầu vào và không bảo toàn các trường rỗng khi có nhiều delimiter liên tiếp.","contrast":[["char a[3][32]","Ba vùng char, mỗi vùng 32 byte."],["char *a[3]","Mảng ba con trỏ, mỗi con trỏ trỏ đến một chuỗi/vùng phù hợp."],["strtok","Tách token và sửa delimiter thành NUL."],["strcmp","So sánh byte của hai chuỗi C."]],"pitfall":"Không dùng strtok để đọc CSV chuẩn có dấu nháy hoặc trường rỗng; nó không phải CSV parser đầy đủ.","challenge":"Sắp xếp 5 chuỗi ASCII bằng strcmp, mô tả vì sao cách này không phải thứ tự từ điển tiếng Việt có dấu."},"lab_examples":[{"title":"Tách token với strtok và kiểm tra dữ liệu gốc","purpose":"Chuỗi cần là mảng có thể sửa, không phải literal được sửa trực tiếp.","code":"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    char line[] = \"An, Binh,,Chi\";\n    char *token = strtok(line, \", \");\n    int count = 0;\n    while (token != NULL) {\n        printf(\"%d:%s\\n\", ++count, token);\n        token = strtok(NULL, \", \");\n    }\n    printf(\"Tong token=%d\\n\", count);\n    return 0;\n}\n","output":"1:An\n2:Binh\n3:Chi\nTong token=3","stdin":"","cases":[{"stdin":"","stdout":"1:An\n2:Binh\n3:Chi\nTong token=3","exit":0}],"followup":"Nhận xét vì sao trường rỗng giữa hai dấu phẩy bị bỏ qua."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M4","module_title":"Mảng, thuật toán xử lý dữ liệu và chuỗi","design_case":{"title":"Tách bản ghi thiết bị dạng CSV đơn giản","problem":"Bản ghi “M1,ON,31” có ba trường mã máy, trạng thái và giá trị đo. Tách trường và kiểm tra dữ liệu.","input":["Chuỗi “M1,ON,31”"],"process":["Phân tách theo dấu phẩy và kiểm tra số lượng trường"],"output":["Ba trường M1, ON, 31"],"assumptions":["strtok bỏ qua trường rỗng và sửa chuỗi gốc; muốn giữ trường rỗng cần phương pháp khác"],"pseudocode":["Bắt đầu","Sao chép dòng sang bộ đệm có thể sửa","Tách theo dấu phẩy và đếm trường","Kiểm tra số lượng và kiểu từng trường","Xuất cấu trúc bản ghi hoặc báo sai"],"tests":[{"input":"\"M1,ON,31\"","expected":"3 trường hợp lệ","kind":"Thông thường"},{"input":"\"M1,,31\"","expected":"Cần phát hiện trường trạng thái rỗng; strtok đơn lẻ không bảo toàn","kind":"Biên"},{"input":"\"M1,ON\"","expected":"Không đủ 3 trường","kind":"Thiếu dữ liệu"}],"reflection":"Vì sao strtok không phù hợp nếu CSV có giá trị rỗng cần giữ nguyên?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-19","number":19,"title":"Tệp văn bản: mở, đọc, ghi và đóng","unit":"Làm việc với tệp","source":"Slot_19_20_Files.pptx, slide 3–30","lead":"Lưu trữ dữ liệu vượt quá vòng đời chương trình và xử lý lỗi thao tác tệp.","objectives":["Phân biệt luồng tệp, chế độ r/w/a và EOF.","Đọc, ghi tệp văn bản bằng fopen/fgets/fprintf/fclose.","Phát hiện và xử lý tệp không tồn tại hoặc lỗi đọc ghi."],"sections":[{"title":"Vai trò của tệp","text":"Biến thường mất giá trị khi chương trình kết thúc; tệp lưu dữ liệu trên thiết bị lưu trữ và cho phép các lần chạy khác nhau dùng lại. C cung cấp một giao diện qua kiểu FILE và các hàm của stdio.h.","bullets":[]},{"title":"Mở và đóng tệp","text":"fopen(\"data.txt\", \"r\") mở tệp văn bản đọc; \"w\" tạo/ghi đè; \"a\" ghi nối cuối. Nếu thất bại, fopen trả NULL. fclose giải phóng tài nguyên và cần kiểm tra kết quả khi bảo đảm ghi dữ liệu thành công.","bullets":[]},{"title":"Đọc và ghi văn bản","text":"fprintf gửi dữ liệu có định dạng ra tệp; fscanf đọc giá trị định dạng; fgets đọc theo dòng, đặc biệt hữu ích khi muốn kiểm tra dữ liệu. Không dùng while(!feof(fp)) như điều kiện đọc; thay vào đó kiểm tra trực tiếp kết quả hàm đọc.","bullets":[]},{"title":"Vị trí tệp trên OnlineGDB","text":"Trong OnlineGDB, để đọc tệp data.txt, sinh viên cần tạo tệp này trong cùng dự án trước khi Run, trừ khi chương trình tự tạo tệp. Việc lưu trữ có thể phụ thuộc phiên làm việc, không nên giả định dữ liệu được giữ vĩnh viễn nếu không lưu dự án.","bullets":[]}],"example":{"title":"Ghi và đọc lại tệp văn bản","code":"#include <stdio.h>\nint main(void) {\n    FILE *f = fopen(\"diem.txt\", \"w\");\n    if (f == NULL) { perror(\"Mo ghi\"); return 1; }\n    if (fprintf(f, \"%d\\n\", 85) < 0) { fclose(f); return 1; }\n    if (fclose(f) != 0) return 1;\n    f = fopen(\"diem.txt\", \"r\");\n    if (f == NULL) { perror(\"Mo doc\"); return 1; }\n    int diem;\n    if (fscanf(f, \"%d\", &diem) != 1) { fclose(f); return 1; }\n    printf(\"Diem = %d\\n\", diem);\n    if (fclose(f) != 0) return 1;\n    return 0;\n}\n","output":"Diem = 85","stdin":"","why":"Chương trình tự tạo diem.txt trong thư mục làm việc; các bước fopen, fprintf, fclose, fopen, fscanf và fclose đều được kiểm tra theo mức căn bản.","tests":[],"trace":["Chương trình mở tệp để ghi và kiểm tra kết quả thao tác.","Sau khi đóng tệp, chương trình mở lại để đọc và in dữ liệu, tránh giả định có tệp đầu vào sẵn."]},"mistakes":["Dùng fopen mà không kiểm tra NULL.","Dùng while(!feof(f)) để đọc.","Không đóng tệp hoặc không kiểm tra lỗi ghi quan trọng."],"exercises":[{"name":"Tệp điểm","task":"Đọc tệp data.txt gồm số nguyên mỗi dòng (tối đa 100), in tổng và trung bình.","hint":"Dùng fscanf với vòng điều kiện ==1; kiểm tra lỗi dữ liệu ngoài định dạng.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Ghi thống kê","task":"Sau khi tính tổng và trung bình, ghi vào results.txt.","hint":"Dùng fprintf và kiểm tra fclose.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Mở một tệp văn bản do sinh viên tạo trên OnlineGDB, đọc cho đến hết tệp, phát hiện lỗi đọc và đếm dòng hợp lệ.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"fopen trả về gì nếu mở tệp thất bại?","choices":["0 kiểu int","EOF kiểu int","Con trỏ NULL","Chuỗi rỗng"],"answer":2,"explain":"fopen trả về NULL khi không thể mở tệp.","rationales":["fopen trả kiểu FILE*, không phải int 0.","EOF là hằng int dùng trong ngữ cảnh I/O khác, không phải giá trị trả về của fopen.","fopen trả về NULL khi không thể mở tệp.","Chuỗi rỗng không phải giá trị trả về của fopen."]},{"q":"Điều kiện đọc số nguyên an toàn hơn là?","choices":["while (f)","while (fscanf(f,\"%d\",&x)==1)","while (x)","while (!feof(f))"],"answer":1,"explain":"Điều kiện cần dựa trên kết quả thao tác đọc.","rationales":["Điều kiện f chỉ kiểm tra con trỏ, không thể hiện thành công lần đọc.","Điều kiện cần dựa trên kết quả thao tác đọc.","Giá trị x cũ không cho biết lần đọc mới thành công.","feof chỉ báo sau một thao tác phát hiện hết tệp, dễ gây xử lý dư."]},{"q":"Chế độ fopen(\"file.txt\", \"w\") ảnh hưởng tệp đã tồn tại ra sao?","choices":["Tệp thường bị cắt bỏ nội dung cũ khi mở thành công.","Tự tạo bản sao lưu.","Chỉ được đọc.","Giữ nguyên nội dung và chỉ thêm cuối."],"answer":0,"explain":"w là chế độ ghi đè; cần tránh dùng trên dữ liệu quan trọng.","rationales":["w là chế độ ghi đè; cần tránh dùng trên dữ liệu quan trọng.","Không phù hợp: Tự tạo bản sao lưu. Phát biểu đúng: w là chế độ ghi đè; cần tránh dùng trên dữ liệu quan trọng.","Không phù hợp: Chỉ được đọc. Phát biểu đúng: w là chế độ ghi đè; cần tránh dùng trên dữ liệu quan trọng.","Không phù hợp: Giữ nguyên nội dung và chỉ thêm cuối. Phát biểu đúng: w là chế độ ghi đè; cần tránh dùng trên dữ liệu quan trọng."]},{"q":"Cách lặp đọc tệp nào đúng hơn?","choices":["while(1) không có điều kiện dừng.","Lặp 1000 lần bất kể tệp dài ngắn.","while(!feof(f)) rồi luôn dùng dữ liệu cũ.","while(fgets(line,sizeof line,f)!=NULL) { ... }."],"answer":3,"explain":"Phải kiểm tra trực tiếp kết quả phép đọc.","rationales":["Không phù hợp: while(1) không có điều kiện dừng. Phát biểu đúng: Phải kiểm tra trực tiếp kết quả phép đọc.","Không phù hợp: Lặp 1000 lần bất kể tệp dài ngắn. Phát biểu đúng: Phải kiểm tra trực tiếp kết quả phép đọc.","Không phù hợp: while(!feof(f)) rồi luôn dùng dữ liệu cũ. Phát biểu đúng: Phải kiểm tra trực tiếp kết quả phép đọc.","Phải kiểm tra trực tiếp kết quả phép đọc."]},{"q":"Sau vòng lặp fgets kết thúc, hàm nào giúp kiểm tra lỗi đọc?","choices":["strcpy(f).","strlen(f).","ferror(f).","rand()."],"answer":2,"explain":"ferror cho biết trạng thái lỗi của luồng.","rationales":["Không phù hợp: strcpy(f). Phát biểu đúng: ferror cho biết trạng thái lỗi của luồng.","Không phù hợp: strlen(f). Phát biểu đúng: ferror cho biết trạng thái lỗi của luồng.","ferror cho biết trạng thái lỗi của luồng.","Không phù hợp: rand(). Phát biểu đúng: ferror cho biết trạng thái lỗi của luồng."]}],"summary":["Vai trò của tệp","Mở và đóng tệp","Đọc và ghi văn bản","Vị trí tệp trên OnlineGDB"],"minutes":45,"syntax":[{"label":"Quy trình ghi tệp văn bản","code":"FILE *f = fopen(\"ketqua.txt\", \"w\");\nif (f == NULL) { /* xử lý lỗi */ }\nelse {\n    fprintf(f, \"Gia tri=%d\\n\", 42);\n    if (fclose(f) == EOF) { /* lỗi ghi/đóng */ }\n}\n","meaning":"fopen mở tệp, fprintf ghi có định dạng, fclose đóng và có thể báo lỗi.","watch":"Chế độ \"w\" tạo tệp hoặc ghi đè tệp cũ; không dùng nếu muốn bảo toàn nội dung đã có."},{"label":"Đọc một dòng từ tệp","code":"FILE *f = fopen(\"ketqua.txt\", \"r\");\nif (f != NULL) {\n    char buf[100];\n    if (fgets(buf, sizeof buf, f) != NULL) {\n        /* xử lý dòng */\n    }\n    fclose(f);\n}\n","meaning":"Đọc cần kiểm tra cả mở tệp và giá trị trả về của fgets.","watch":"EOF không phải là byte bắt buộc lưu trong tệp; nó là giá trị báo trạng thái của các hàm đọc."}],"flow":{"type":"loop","caption":"Đọc từng dòng tệp văn bản","start":"Mở tệp ở chế độ r","condition":"fgets trả khác NULL?","body":"Xử lý dòng vừa đọc","end":"Kiểm tra lỗi; đóng tệp"},"worked":{"title":"Bài mẫu: đọc nhiều dòng và tính trung bình tệp văn bản","problem":"Tạo tệp thực hành gồm các điểm 8,9,7; đọc từng dòng, kiểm tra miền 0..10, tính số dòng và điểm trung bình.","steps":["Tạo tệp thử nghiệm riêng và kiểm tra ghi đóng tệp.","Đọc từng dòng bằng fgets; dùng strtol kiểm tra các giá trị.","Từ chối tệp lỗi hoặc rỗng, tính trung bình khi count>0."],"code":"#include <stdio.h>\n#include <stdlib.h>\n#include <errno.h>\n#include <ctype.h>\n#include <limits.h>\nint main(void) {\n    FILE *f = fopen(\"diem_v2.txt\", \"w\");\n    if (f == NULL) { perror(\"Mo ghi\"); return 1; }\n    int write_failed = (fputs(\"8\\n9\\n7\\n\", f) == EOF);\n    if (fclose(f) != 0) write_failed = 1;\n    if (write_failed) return 1;\n    f = fopen(\"diem_v2.txt\", \"r\");\n    if (f == NULL) { perror(\"Mo doc\"); return 1; }\n    char line[64];\n    long sum = 0;\n    int count = 0, invalid = 0;\n    while (fgets(line, sizeof line, f) != NULL) {\n        char *end;\n        errno = 0;\n        long v = strtol(line, &end, 10);\n        while (isspace((unsigned char)*end)) ++end;\n        if (errno == ERANGE || end == line || *end != '\\0' || v < 0 || v > 10) { invalid=1; break; }\n        sum += v; ++count;\n    }\n    if (ferror(f)) invalid = 1;\n    if (fclose(f) != 0 || invalid || count == 0) { puts(\"Tap tin loi\"); return 1; }\n    printf(\"So dong=%d; TB=%.2f\\n\", count, (double)sum/count);\n    return 0;\n}\n","output":"So dong=3; TB=8.00","stdin":"","analysis":["Dùng kết quả của fgets để xác định khi nào có dòng mới, không dùng while(!feof).","Ví dụ tạo tệp trên thư mục làm việc; tránh chạy mã có mode w trên tệp quan trọng."],"tests":["Tệp 8,9,7 → 8.00; tệp rỗng → báo lỗi; dòng abc → báo lỗi."]},"deep_dive":{"context":"Đọc tệp cần dựa vào kết quả của phép đọc, không phải điều kiện !feof trước khi đọc. Chế độ w ghi đè nội dung hiện có; phải dùng tệp thực hành riêng và kiểm tra fclose nếu yêu cầu bảo đảm ghi.","contrast":[["r","Mở tệp đang tồn tại để đọc."],["w","Mở để ghi; tạo mới hoặc cắt bỏ nội dung cũ."],["a","Thêm dữ liệu cuối tệp."],["ferror","Phân biệt lỗi đọc với kết thúc tệp sau khi thao tác thất bại."]],"pitfall":"Không lặp bằng while(!feof(f)); EOF chỉ được ghi nhận sau khi một lần đọc chạm cuối tệp.","challenge":"Mở một tệp văn bản do sinh viên tạo trên OnlineGDB, đọc cho đến hết tệp, phát hiện lỗi đọc và đếm dòng hợp lệ."},"lab_examples":[{"title":"Đọc nhiều dòng và tính tổng từ tệp văn bản","purpose":"Chương trình tự tạo tệp kiểm thử để OnlineGDB chạy được, sau đó đọc từng dòng.","code":"#include <stdio.h>\n#include <stdlib.h>\n#include <errno.h>\n#include <ctype.h>\n#include <limits.h>\nint main(void) {\n    FILE *f = fopen(\"diem_v2.txt\", \"w\");\n    if (f == NULL) { perror(\"Mo ghi\"); return 1; }\n    int write_failed = (fputs(\"8\\n9\\n7\\n\", f) == EOF);\n    if (fclose(f) != 0) write_failed = 1;\n    if (write_failed) return 1;\n    f = fopen(\"diem_v2.txt\", \"r\");\n    if (f == NULL) { perror(\"Mo doc\"); return 1; }\n    char line[64];\n    long sum = 0;\n    int count = 0, invalid = 0;\n    while (fgets(line, sizeof line, f) != NULL) {\n        char *end;\n        errno = 0;\n        long v = strtol(line, &end, 10);\n        while (isspace((unsigned char)*end)) ++end;\n        if (errno == ERANGE || end == line || *end != '\\0' || v < 0 || v > 10) { invalid=1; break; }\n        sum += v; ++count;\n    }\n    if (ferror(f)) invalid = 1;\n    if (fclose(f) != 0 || invalid || count == 0) { puts(\"Tap tin loi\"); return 1; }\n    printf(\"So dong=%d; TB=%.2f\\n\", count, (double)sum/count);\n    return 0;\n}\n","output":"So dong=3; TB=8.00","stdin":"","cases":[{"stdin":"","stdout":"So dong=3; TB=8.00","exit":0}],"followup":"Tạo tệp rỗng và dự đoán nhánh xử lý count==0; lưu ý “w” ghi đè tệp."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M5","module_title":"Tệp dữ liệu và bài thực hành tích hợp","design_case":{"title":"Ghi nhật ký nhiệt độ vào tệp văn bản","problem":"Lưu dòng “2026-11-20,28.5” vào tệp CSV; sau đó đọc lại và xác nhận nội dung.","input":["Ngày chuỗi và nhiệt độ dạng số"],"process":["Mở tệp với chế độ thích hợp; kiểm tra fopen, fprintf, fclose"],"output":["Một dòng văn bản đọc lại được"],"assumptions":["Đây là dữ liệu giả lập; cần kiểm tra quyền ghi và mã lỗi I/O"],"pseudocode":["Bắt đầu","Mở tệp để ghi; kiểm tra con trỏ FILE*","Ghi một dòng theo định dạng CSV","Đóng và kiểm tra lỗi","Mở lại để đọc và so sánh nội dung"],"tests":[{"input":"Ghi một dòng","expected":"Đọc lại đúng dòng","kind":"Thông thường"},{"input":"Tệp không mở được","expected":"Thông báo lỗi; không ghi","kind":"Lỗi I/O"},{"input":"Tệp rỗng","expected":"Không có bản ghi để phân tích","kind":"Biên"}],"reflection":"Tại sao cần kiểm tra cả việc đóng tệp khi ghi dữ liệu quan trọng?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]},{"id":"slot-20","number":20,"title":"Tệp nhị phân, fread/fwrite và định vị tệp","unit":"Làm việc với tệp","source":"Slot_19_20_Files.pptx, slide 31–42","lead":"Lưu và cập nhật bản ghi nhị phân, hiểu giới hạn về tính khả chuyển dữ liệu giữa các nền tảng.","objectives":["Sử dụng fwrite và fread với một kiểu struct xác định.","Giải thích chế độ rb, wb, ab và fseek/rewind.","Phân biệt bản ghi nhị phân thô với định dạng tệp có tính khả chuyển."],"sections":[{"title":"Tệp nhị phân và độ dài dữ liệu","text":"Mở với \"rb\", \"wb\", \"ab\" để truyền dữ liệu nhị phân mà không có chuyển đổi văn bản do môi trường. fwrite(ptr, size, count, fp) trả số phần tử đã ghi, fread trả số phần tử đọc được. Để kiểm tra kết thúc hay lỗi, dùng feof và ferror sau thao tác đọc.","bullets":[]},{"title":"Ghi struct thô","text":"Ghi trực tiếp sizeof(struct) byte chỉ thích hợp khi chương trình và môi trường đọc ghi thống nhất cách biểu diễn. Padding, endianness, kích thước kiểu và biểu diễn số thực có thể khác giữa nền tảng hoặc phiên bản chương trình. Không xem fwrite(struct) là định dạng liên thông chuẩn.","bullets":[]},{"title":"Định vị tệp","text":"fseek(fp, offset, SEEK_SET/SEEK_CUR/SEEK_END) chuyển vị trí trong tệp theo quy tắc chế độ và triển khai; rewind(fp) về đầu và xóa trạng thái lỗi/EOF. Với tệp văn bản, chỉ có một số cách dùng offset là có tính khả chuyển, như giá trị từ ftell với SEEK_SET.","bullets":[]},{"title":"Quản lý bản ghi và kiểm thử","text":"Các thao tác thêm, xem, sửa một bản ghi cần kiểm tra mã định danh trùng, lỗi tệp, số lượng bản ghi và thao tác cập nhật. Tệp dữ liệu thử nghiệm cần các trường hợp rỗng, chỉ có một bản ghi và bản ghi không tìm thấy.","bullets":[]}],"example":{"title":"Ghi và đọc một bản ghi nhị phân trong một lần chạy","code":"#include <stdio.h>\nstruct Item { int id; double price; };\nint main(void) {\n    struct Item a = {7, 12.5}, b;\n    FILE *f = fopen(\"item.bin\", \"wb\");\n    if (!f) return 1;\n    if (fwrite(&a, sizeof a, 1, f) != 1) { fclose(f); return 1; }\n    if (fclose(f) != 0) return 1;\n    f = fopen(\"item.bin\", \"rb\");\n    if (!f) return 1;\n    if (fread(&b, sizeof b, 1, f) != 1) { fclose(f); return 1; }\n    printf(\"ID=%d, gia=%.1f\\n\", b.id, b.price);\n    if (fclose(f) != 0) return 1;\n    return 0;\n}\n","output":"ID=7, gia=12.5","stdin":"","why":"Ví dụ chỉ đọc lại trong cùng môi trường thực thi và cùng chương trình. Không khẳng định định dạng .bin thu được có thể dùng trực tiếp trên mọi kiến trúc.","tests":[],"trace":["fwrite ghi một đối tượng vào tệp mở chế độ nhị phân.","fread đọc lại vào đối tượng cùng kiểu trong cùng môi trường; ảnh bộ nhớ struct không phải định dạng portable."]},"mistakes":["Ghi struct thô rồi khẳng định tệp tương thích mọi máy.","Không kiểm tra số phần tử fwrite/fread trả về.","Cập nhật sai offset làm hỏng bản ghi khác."],"exercises":[{"name":"Đọc danh sách bản ghi","task":"Tạo mảng 3 Item, ghi bằng fwrite và đọc lại để hiển thị.","hint":"Kiểm tra số phần tử ghi/đọc; chỉ ghi những phần tử đã khởi tạo.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Sửa bản ghi","task":"Thiết kế hàm cập nhật giá của Item theo id trong tệp nhị phân.","hint":"Đọc lần lượt; tìm vị trí bằng ftell hoặc chỉ số; ghi lại đúng bản ghi, thử id không tồn tại.","criteria":"Đúng yêu cầu, xử lý đầu vào và giải thích kết quả.","level":"Vận dụng"},{"name":"Bài vận dụng mở rộng","task":"Thiết kế chức năng cập nhật giá theo mã bản ghi, kiểm thử id tồn tại, không tồn tại và tệp rỗng.","hint":"Phân tích Input–Process–Output, viết mã C11, tự lập bộ dữ liệu thông thường/biên/sai và giải thích đầu ra.","criteria":"Có thuật toán hoặc lập luận, chương trình độc lập, ít nhất ba phép kiểm thử và nhận xét trường hợp biên.","level":"Vận dụng–Phân tích"}],"quiz":[{"q":"fwrite trả về giá trị gì?","choices":["Số byte luôn bằng size×count","Số phần tử ghi thành công","Địa chỉ vùng đệm","Con trỏ tệp"],"answer":1,"explain":"fwrite trả số phần tử được ghi đầy đủ.","rationales":["fwrite trả về số phần tử ghi đầy đủ, không bắt buộc bằng số byte.","fwrite trả số phần tử được ghi đầy đủ.","fwrite không trả địa chỉ bộ đệm.","fwrite không trả con trỏ FILE*."]},{"q":"Ghi trực tiếp struct thành nhị phân có bảo đảm khả chuyển?","choices":["Không, vì padding và biểu diễn có thể khác","Có với mọi hệ thống","Chỉ phụ thuộc tên tệp","Có nếu dùng .bin"],"answer":0,"explain":"Dạng byte nội bộ của struct phụ thuộc triển khai và ABI.","rationales":["Dạng byte nội bộ của struct phụ thuộc triển khai và ABI.","Dạng biểu diễn đối tượng có thể khác giữa kiến trúc.","Tên tệp không quyết định padding, endian hay kiểu biểu diễn.","Đuôi .bin không tạo khả chuyển cho cấu trúc dữ liệu."]},{"q":"Giá trị trả về của fwrite(ptr,size,count,f) biểu thị gì?","choices":["Vị trí của con trỏ char.","Số byte của toàn bộ RAM.","Mã Unicode của bản ghi.","Số phần tử được ghi thành công."],"answer":3,"explain":"Để xác nhận ghi đủ, so sánh với count.","rationales":["Không phù hợp: Vị trí của con trỏ char. Phát biểu đúng: Để xác nhận ghi đủ, so sánh với count.","Không phù hợp: Số byte của toàn bộ RAM. Phát biểu đúng: Để xác nhận ghi đủ, so sánh với count.","Không phù hợp: Mã Unicode của bản ghi. Phát biểu đúng: Để xác nhận ghi đủ, so sánh với count.","Để xác nhận ghi đủ, so sánh với count."]},{"q":"Vì sao không nên trao đổi tệp tạo từ fwrite(struct) giữa mọi nền tảng?","choices":["Vì tệp luôn bị nén.","Vì fwrite chỉ ghi văn bản.","Padding, biểu diễn số và kích thước kiểu có thể khác nhau.","Vì struct không thể ghi xuống tệp."],"answer":2,"explain":"Cần định dạng tuần tự hóa có đặc tả độc lập nền tảng.","rationales":["Không phù hợp: Vì tệp luôn bị nén. Phát biểu đúng: Cần định dạng tuần tự hóa có đặc tả độc lập nền tảng.","Không phù hợp: Vì fwrite chỉ ghi văn bản. Phát biểu đúng: Cần định dạng tuần tự hóa có đặc tả độc lập nền tảng.","Cần định dạng tuần tự hóa có đặc tả độc lập nền tảng.","Không phù hợp: Vì struct không thể ghi xuống tệp. Phát biểu đúng: Cần định dạng tuần tự hóa có đặc tả độc lập nền tảng."]},{"q":"Muốn sửa bản ghi tại vị trí vừa đọc bằng luồng r+b, nên làm gì?","choices":["Chỉ dùng puts vào stdout.","Ghi nhớ vị trí, fseek về đầu bản ghi rồi fwrite có kiểm tra.","Luôn dùng chế độ ab để ghi đè giữa tệp.","Đóng tệp mà không ghi."],"answer":1,"explain":"Việc định vị giúp thay đúng bản ghi và tuân thủ quy tắc chuyển đọc–ghi.","rationales":["Không phù hợp: Chỉ dùng puts vào stdout. Phát biểu đúng: Việc định vị giúp thay đúng bản ghi và tuân thủ quy tắc chuyển đọc–ghi.","Việc định vị giúp thay đúng bản ghi và tuân thủ quy tắc chuyển đọc–ghi.","Không phù hợp: Luôn dùng chế độ ab để ghi đè giữa tệp. Phát biểu đúng: Việc định vị giúp thay đúng bản ghi và tuân thủ quy tắc chuyển đọc–ghi.","Không phù hợp: Đóng tệp mà không ghi. Phát biểu đúng: Việc định vị giúp thay đúng bản ghi và tuân thủ quy tắc chuyển đọc–ghi."]}],"summary":["Tệp nhị phân và độ dài dữ liệu","Ghi struct thô","Định vị tệp","Quản lý bản ghi và kiểm thử"],"minutes":45,"syntax":[{"label":"Đọc/ghi bản ghi nhị phân","code":"size_t ghi = fwrite(&record, sizeof record, 1, f);\nsize_t doc = fread(&record, sizeof record, 1, f);\n","meaning":"fwrite/fread trả về số phần tử ghi/đọc thành công, không phải mặc nhiên là số byte.","watch":"Mẫu là minh họa cách gọi trong hàm, với record và FILE *f đã khai báo, tệp mở chế độ nhị phân."},{"label":"Di chuyển vị trí tệp","code":"if (fseek(f, 0L, SEEK_SET) != 0) {\n    /* xử lý lỗi định vị */\n}\n","meaning":"SEEK_SET định vị tương đối theo đầu tệp; với tệp nhị phân, fseek dùng offset byte do chương trình cung cấp.","watch":"Không xem ảnh bộ nhớ struct trong tệp nhị phân là định dạng dữ liệu tương thích trên mọi hệ thống."}],"flow":{"type":"loop","caption":"Đọc các bản ghi nhị phân liên tiếp","start":"Mở tệp chế độ rb","condition":"fread được 1 bản ghi?","body":"Kiểm tra và xử lý bản ghi","end":"Kiểm tra lỗi; đóng tệp"},"worked":{"title":"Bài mẫu: cập nhật bản ghi nhị phân bằng ftell và fseek","problem":"Tạo ba bản ghi Item với id 1,2,3; tìm id=2 và sửa giá từ 20.0 thành 25.0 bằng chế độ r+b.","steps":["Ghi ba bản ghi vào tệp nhị phân thực hành mới.","Mở r+b, trước mỗi fread lưu vị trí ftell; tìm bản ghi id=2.","Quay về bằng fseek rồi fwrite, đóng và đọc lại để đối chiếu."],"code":"#include <stdio.h>\nstruct Item { int id; double price; };\nint main(void) {\n    struct Item a[] = {{1,10.0},{2,20.0},{3,30.0}};\n    FILE *f = fopen(\"items_v2.bin\", \"wb\");\n    if (f == NULL) return 1;\n    int write_failed = (fwrite(a, sizeof a[0], 3, f) != 3);\n    if (fclose(f) != 0) write_failed = 1;\n    if (write_failed) return 1;\n    f = fopen(\"items_v2.bin\", \"r+b\");\n    if (f == NULL) return 1;\n    struct Item x;\n    int found = 0;\n    while (1) {\n        long pos = ftell(f);\n        if (pos < 0) { fclose(f); return 1; }\n        if (fread(&x, sizeof x, 1, f) != 1) break;\n        if (x.id == 2) {\n            x.price = 25.0;\n            if (fseek(f, pos, SEEK_SET) != 0 || fwrite(&x, sizeof x, 1, f) != 1) {\n                fclose(f); return 1;\n            }\n            found = 1;\n            break;\n        }\n    }\n    if (ferror(f) || fclose(f) != 0 || !found) return 1;\n    f = fopen(\"items_v2.bin\", \"rb\");\n    if (f == NULL) return 1;\n    if (fseek(f, (long)sizeof(struct Item), SEEK_SET) != 0 ||\n        fread(&x, sizeof x, 1, f) != 1) { fclose(f); return 1; }\n    if (fclose(f) != 0) return 1;\n    printf(\"ID=%d; gia=%.1f\\n\", x.id, x.price);\n    return 0;\n}\n","output":"ID=2; gia=25.0","stdin":"","analysis":["Phải ghi nhận vị trí trước khi đọc để không ghi đè sang bản ghi kế tiếp.","Cần kiểm tra fwrite, ferror và fclose; tệp struct thô chỉ phù hợp với môi trường đọc/ghi tương thích."],"tests":["Id=2 → giá 25.0; id không tồn tại → không có thay đổi; tệp rỗng → phải xử lý."]},"deep_dive":{"context":"Khi sửa tệp nhị phân, cần lưu vị trí bản ghi trước khi đọc, dùng fseek để quay về và ghi lại có kiểm tra số phần tử. Không coi dump struct thô là định dạng trao đổi độc lập kiến trúc.","contrast":[["rb","Mở tệp nhị phân chỉ đọc."],["wb","Tạo/ghi đè tệp nhị phân."],["r+b","Mở tệp nhị phân hiện có để đọc và cập nhật."],["ftell/fseek","Lấy vị trí và di chuyển con trỏ vị trí tệp phù hợp."]],"pitfall":"Khi chuyển từ đọc sang ghi trên luồng cập nhật cần thao tác định vị phù hợp; không sửa bản ghi nếu chưa tìm thấy id.","challenge":"Thiết kế chức năng cập nhật giá theo mã bản ghi, kiểm thử id tồn tại, không tồn tại và tệp rỗng."},"lab_examples":[{"title":"Sửa một bản ghi nhị phân theo id","purpose":"Ví dụ có đóng/mở tệp và định vị đúng trước khi ghi cập nhật.","code":"#include <stdio.h>\nstruct Item { int id; double price; };\nint main(void) {\n    struct Item a[] = {{1,10.0},{2,20.0},{3,30.0}};\n    FILE *f = fopen(\"items_v2.bin\", \"wb\");\n    if (f == NULL) return 1;\n    int write_failed = (fwrite(a, sizeof a[0], 3, f) != 3);\n    if (fclose(f) != 0) write_failed = 1;\n    if (write_failed) return 1;\n    f = fopen(\"items_v2.bin\", \"r+b\");\n    if (f == NULL) return 1;\n    struct Item x;\n    int found = 0;\n    while (1) {\n        long pos = ftell(f);\n        if (pos < 0) { fclose(f); return 1; }\n        if (fread(&x, sizeof x, 1, f) != 1) break;\n        if (x.id == 2) {\n            x.price = 25.0;\n            if (fseek(f, pos, SEEK_SET) != 0 || fwrite(&x, sizeof x, 1, f) != 1) {\n                fclose(f); return 1;\n            }\n            found = 1;\n            break;\n        }\n    }\n    if (ferror(f) || fclose(f) != 0 || !found) return 1;\n    f = fopen(\"items_v2.bin\", \"rb\");\n    if (f == NULL) return 1;\n    if (fseek(f, (long)sizeof(struct Item), SEEK_SET) != 0 ||\n        fread(&x, sizeof x, 1, f) != 1) { fclose(f); return 1; }\n    if (fclose(f) != 0) return 1;\n    printf(\"ID=%d; gia=%.1f\\n\", x.id, x.price);\n    return 0;\n}\n","output":"ID=2; gia=25.0","stdin":"","cases":[{"stdin":"","stdout":"ID=2; gia=25.0","exit":0}],"followup":"Dùng id=99 và giải thích vì sao chương trình không ghi thay một bản ghi bất kỳ."}],"practice_protocol":["Nêu dữ liệu vào, dữ liệu ra và điều kiện hợp lệ trước khi viết mã.","Dự đoán kết quả bằng bảng truy vết hoặc tính tay.","Sao chép chương trình vào OnlineGDB, chọn C, chạy với ít nhất hai bộ dữ liệu.","Đối chiếu đầu ra, thử tình huống biên và giải thích mọi sai khác."],"lesson_parts":["Tình huống kỹ thuật và mục tiêu","Phân tích IPO, dữ liệu và giả thiết","Mã giả / lưu đồ thuật toán","Kiến thức và cú pháp C11","Dự đoán → chạy chương trình → truy vết","Bảng kiểm thử và sửa lỗi","Bài tập mẫu + luyện tập độc lập","Trắc nghiệm giải thích từng lựa chọn","Rubric, tự phản tư và tổng kết"],"module":"M5","module_title":"Tệp dữ liệu và bài thực hành tích hợp","design_case":{"title":"Lưu và sửa bản ghi thiết bị trong tệp nhị phân","problem":"Một bản ghi chứa mã thiết bị và nhiệt độ được ghi rồi cập nhật theo ID trong tệp nhị phân trên cùng môi trường biên dịch.","input":["ID thiết bị; giá trị nhiệt độ; tệp nhị phân"],"process":["Ghi struct; tìm ID bằng fread; xác định vị trí; fseek; fwrite"],"output":["Bản ghi mục tiêu được cập nhật; bản ghi khác giữ nguyên"],"assumptions":["Biểu diễn struct phụ thuộc ABI, kích thước/đệm và không phải định dạng lưu trữ khả chuyển"],"pseudocode":["Bắt đầu","Mở tệp chế độ nhị phân phù hợp; kiểm tra lỗi","Duyệt và đọc từng bản ghi","Nếu trùng ID: định vị đúng vị trí và ghi đè","Kiểm tra kết quả I/O; đóng tệp"],"tests":[{"input":"ID tồn tại","expected":"Cập nhật đúng bản ghi","kind":"Thông thường"},{"input":"ID không tồn tại","expected":"Không ghi đè bản ghi nào","kind":"Không tìm thấy"},{"input":"Tệp bị lỗi/không mở","expected":"Báo lỗi và không cập nhật","kind":"An toàn dữ liệu"}],"reflection":"Vì sao không nên trao đổi trực tiếp tệp fwrite(struct) giữa các hệ biên dịch khác nhau?","status":"Tình huống sư phạm biên soạn mới; không thay thế ví dụ PRF192 hoặc tiêu chuẩn kỹ thuật"},"rubric":[{"name":"Phân tích yêu cầu, đơn vị và giả thiết","score":2.0},{"name":"Mã giả, lưu đồ hoặc luận giải thuật toán","score":2.5},{"name":"Chương trình C và tổ chức mã","score":2.5},{"name":"Kiểm thử: thông thường, biên và dữ liệu sai","score":2.0},{"name":"Giải thích kết quả và giới hạn áp dụng","score":1.0}]}],"workshops":[{"id":"w01","title":"Workshop 1 — Quản lý điểm lớp học","after":7,"source":"Workshop_01.docx","objectives":["Điều kiện if/else, for, while và xác thực điểm.","Tính tổng, trung bình và số sinh viên đạt/chưa đạt."],"brief":"Nhập số sinh viên và điểm trong đoạn [0,10]. Tính tổng điểm, điểm trung bình, số người đạt (điểm từ 5) và chưa đạt. Số sinh viên và từng điểm phải được kiểm tra hợp lệ.","requirements":["Nhập số sinh viên nguyên dương theo giới hạn do người học công bố.","Lặp để nhận từng điểm và xử lý nhập không hợp lệ.","Tính tổng, trung bình, số lượng đạt và chưa đạt; đối chiếu tổng hai nhóm bằng n.","Thử n=1, điểm 0, 5, 10 và dữ liệu không hợp lệ."],"scaffold":"#include <stdio.h>\nint main(void) {\n    int n;\n    /* TODO: nhập/kiểm tra n */\n    /* TODO: nhập từng điểm và thống kê */\n    /* TODO: hiển thị kết quả */\n    return 0;\n}","testcases":["n=3; điểm 4,5,9 → tổng 18; trung bình 6.00; đạt 2; chưa đạt 1.","Điểm 10.5 → không hợp lệ; không cộng vào thống kê."],"rubric":[3,3,2,2]},{"id":"w02","title":"Workshop 2 — Tính lương và phụ cấp bằng hàm","after":9,"source":"Workshop_02.docx","objectives":["Xây dựng và gọi hàm tính phụ cấp, thuế, thu nhập ròng.","Thống kê tổng chi phí lương và số người theo nhóm phụ cấp."],"brief":"Giả định học thuật của đề gốc: lương cơ bản dưới 6 triệu có phụ cấp 25%; 6–15 triệu (bao gồm biên) 15%; trên 15 triệu 10%. Thuế minh họa bằng 10% phần tổng thu nhập vượt 8 triệu. Đây KHÔNG phải cách tính thuế hoặc lương hiện hành theo pháp luật Việt Nam.","requirements":["Đọc n và mức lương cơ bản không âm; xử lý nhập lỗi.","Viết các hàm riêng cho phụ cấp, thuế và thực lĩnh; truyền giá trị.","Tính thu nhập trước thuế = cơ bản + phụ cấp, phần chịu thuế minh họa = max(0, trước_thuế - 8 triệu), thuế = 10% phần đó.","Thống kê số người theo ba ngưỡng và tổng thu nhập ròng."],"scaffold":"#include <stdio.h>\ndouble phu_cap(double luong) { /* TODO */ return 0.0; }\ndouble thue_minh_hoa(double thu_nhap) { /* TODO */ return 0.0; }\nint main(void) { /* TODO: nhập, tính và thống kê */ return 0; }","testcases":["5 triệu → phụ cấp 1.25 triệu; tổng trước thuế 6.25 triệu; thuế 0.","10 triệu → phụ cấp 1.5 triệu; thuế 0.35 triệu; thực lĩnh 11.15 triệu.","15 triệu thuộc nhóm 15%; 15,000,001 thuộc nhóm 10%."],"rubric":[2,4,2,2]},{"id":"w03","title":"Workshop 3 — Thống kê và tìm kiếm mảng","after":14,"source":"Workshop_03.docx","objectives":["Tổ chức chương trình bằng các hàm xử lý mảng.","Duyệt, tìm kiếm, tính tổng/trung bình/cực trị."],"brief":"Nhập 1–100 số nguyên, hiển thị dữ liệu, tìm vị trí đầu tiên của một giá trị và tính tổng, trung bình, lớn nhất, nhỏ nhất.","requirements":["Kiểm tra n trong [1,100] và từng số đầu vào.","Viết các hàm riêng cho nhập, in, tìm, tính toán.","Dùng chỉ số 0-based và nêu quy ước khi không tìm thấy.","Xử lý dãy gồm một phần tử, nhiều phần tử trùng nhau, phần tử âm."],"scaffold":"#include <stdio.h>\nint search(const int a[], int n, int x) {\n    for (int i=0;i<n;i++) if(a[i]==x) return i;\n    return -1;\n}\nint main(void) { /* TODO: nhập mảng + thống kê */ return 0; }","testcases":["{4,7,2,9}, tìm 2 → vị trí 2; tổng 22; TB 5.50; min 2; max 9.","{-1}, tìm -1 → vị trí 0; min=max=-1."],"rubric":[2,3,3,2]},{"id":"w04","title":"Workshop 4 — Sắp xếp và lọc doanh số","after":15,"source":"Workshop_04.docx","objectives":["Kết hợp struct, mảng, vòng lặp và hàm.","Sắp tăng/giảm và lọc các giá trị vượt ngưỡng."],"brief":"Quản lý doanh số tối đa 100 ngày qua một struct chứa mảng int và số ngày. Chương trình có menu nhập, hiển thị, sắp tăng, sắp giảm và lọc doanh số vượt mục tiêu.","requirements":["Định nghĩa struct Sales gồm values[100] và n.","Viết hàm sortAscending, sortDescending và filterGreater.","Sắp xếp không làm mất hoặc tăng số phần tử.","Thử tất cả giá trị bằng nhau, mảng đã sắp và ngưỡng không có kết quả."],"scaffold":"#include <stdio.h>\nstruct Sales { int values[100]; int n; };\nvoid sort_asc(struct Sales *s) { /* TODO */ }\nvoid sort_desc(struct Sales *s) { /* TODO */ }\nint main(void) { /* TODO: menu */ return 0; }","testcases":["{30,10,20} tăng → {10,20,30}; giảm → {30,20,10}.","Mục tiêu 20 → chỉ liệt kê 30 (điều kiện >, không phải >=)."],"rubric":[2,3,3,2]},{"id":"w05","title":"Workshop 5 — Đọc tệp và ghi kết quả thống kê","after":20,"source":"Workshop_05.docx","objectives":["Đọc số nguyên từ data.txt vào mảng có giới hạn.","Tính thống kê và ghi ra results.txt."],"brief":"Tệp data.txt chứa một số nguyên trên mỗi dòng. Chương trình đọc tối đa 100 số, hiển thị, tính tổng, trung bình, lớn nhất, nhỏ nhất và ghi kết quả vào results.txt.","requirements":["Tạo tệp data.txt trong OnlineGDB hoặc thư mục dự án.","Xử lý không mở được tệp, tệp rỗng hoặc dữ liệu sai định dạng.","Kiểm tra số phần tử không vượt 100; bảo đảm trung bình không chia cho 0.","Ghi kết quả và kiểm tra lỗi ghi, đóng tệp."],"scaffold":"#include <stdio.h>\nint main(void) {\n    int a[100], n=0;\n    FILE *f = fopen(\"data.txt\", \"r\");\n    if (!f) { perror(\"data.txt\"); return 1; }\n    /* TODO: đọc, kiểm tra và thống kê */\n    fclose(f);\n    return 0;\n}","testcases":["25 30 45 10 60 5 → tổng 175; trung bình 29.17; min 5; max 60.","Tệp rỗng → thông báo không có dữ liệu, không chia cho 0."],"rubric":[2,3,3,2]}],"assignments":[{"id":"a01","title":"Assignment 1 — Quản lý sản phẩm bằng tệp nhị phân","source":"Assignment_Option1.docx","brief":"Xây dựng chương trình quản lý sản phẩm với id duy nhất, tên tối đa 49 byte nội dung ASCII + 1 byte NUL, đơn giá, số lượng; lưu trữ trong products.bin. Giao diện menu cho phép ghi đè, bổ sung, xem và sửa theo id. Tài liệu gốc không yêu cầu xóa; không ghi CRUD đầy đủ nếu chưa hiện thực thao tác Delete.","requirements":["Định nghĩa struct Product; quy ước chiều dài tên, đơn vị tiền và miền giá trị.","Chia hàm ghi đè, bổ sung, đọc và sửa một bản ghi.","Kiểm tra id trùng trước khi thêm và id không có khi sửa.","Xử lý fopen/fread/fwrite/fseek/fclose và nhập không hợp lệ.","Kiểm thử tệp rỗng, lỗi tệp, bản ghi đầu/cuối, ghi đè và bổ sung."],"rubric":[1.5,1.5,2,1.5,1.5,1,1],"note":"Lưu struct dạng byte thô có tính phụ thuộc nền tảng: không bảo đảm đọc được trên máy có ABI khác."},{"id":"a02","title":"Assignment 2 — Quản lý sinh viên bằng tệp văn bản","source":"Assignment_Option2.docx","brief":"Quản lý bản ghi sinh viên (ID, FirstName, LastName, GPA) trong students.txt; cho phép thêm, tìm theo id, tìm theo họ và hiển thị danh sách được sắp tăng theo họ.","requirements":["Chọn định dạng văn bản rõ ràng và xử lý dấu phân cách trong tên.","Xây dựng hàm addStudent, displayStudents, searchStudentById, searchStudentByLastName, sortStudentsByLastName.","Kiểm tra ID trùng, GPA hợp lệ theo thang đã công bố, file thiếu và dữ liệu lỗi.","Sắp xếp theo họ có quy tắc với các bản ghi trùng họ.","Kiểm thử với 0, 1, nhiều sinh viên và các tình huống tìm không thấy."],"rubric":[2,2.5,3,2.5],"note":"Ví dụ dữ liệu gốc sử dụng tên ASCII. Nếu mở rộng sang tiếng Việt UTF-8, cần xây dựng quy tắc so sánh phù hợp; strcmp chỉ so sánh theo byte."}],"references":[{"name":"PRF192 — bộ 10 slide Slot 00–20","detail":"Nguồn khung nội dung chính; bản tải lên trong Project."},{"name":"PRF192 — 5 Workshops và 2 Assignments","detail":"Nguồn tình huống và yêu cầu thực hành; được viết lại bằng tiếng Việt."},{"name":"K. N. King, C Programming: A Modern Approach, 2nd ed.","detail":"Đối chiếu cú pháp, kiểu, phép toán, thư viện C89/C99."},{"name":"B. W. Kernighan & D. M. Ritchie, The C Programming Language, 2nd ed.","detail":"Đối chiếu khái niệm nền tảng và ví dụ nhập môn."},{"name":"G. Perry & D. Miller, C Programming Absolute Beginner’s Guide, 3rd ed.","detail":"Tham khảo phương pháp giảng dạy cho người mới."},{"name":"Z. A. Shaw, Learn C the Hard Way","detail":"Tham khảo mô hình thực hành và debug."},{"name":"ISO/IEC 9899:2024 (C23) — chuẩn C hiện hành","detail":"Nguồn ISO chính thức: https://www.iso.org/standard/82075.html. Ví dụ của website chọn cú pháp tương thích C11 để thuận tiện thực hành; C11 không phải bản hiện hành."}],"corrections":[{"source":"Slot 01, slide 18","issue":"Biểu diễn số nhị phân 00111000 bị ghi thành 104.","revision":"00111000₂ = 56₁₀."},{"source":"Slot 01, slide 21","issue":"Ký hiệu KB/MB dùng cho bội số 1024.","revision":"Phân biệt kB (1000 byte) và KiB (1024 byte)."},{"source":"Slot 02–04","issue":"Kích thước các kiểu được minh họa theo một môi trường cụ thể.","revision":"Không khẳng định sizeof(int)=4 hoặc char có 8 bit trên mọi triển khai."},{"source":"Slot 10","issue":"Diễn giải phép ép kiểu con trỏ và byte order theo quy tắc phổ quát.","revision":"Chỉ giải tham chiếu con trỏ hợp lệ; tránh type punning vi phạm aliasing/alignment."},{"source":"Slot 13–15","issue":"Đồng nhất mảng cục bộ với stack và mảng động với heap.","revision":"Dùng thuật ngữ thời gian lưu trữ và quy tắc cấp phát, không gán bố cục tuyệt đối."},{"source":"Slot 16–18, slide 21, 30–31","issue":"Dùng gets, strupr, strlwr như các hàm chung.","revision":"Loại gets (không có trong C11), thay bằng fgets; strupr/strlwr không phải ISO C."},{"source":"Slot 19–20","issue":"Tệp nhị phân struct có thể bị hiểu là định dạng khả chuyển.","revision":"Ghi rõ rủi ro padding, endian và kích thước kiểu."},{"source":"Assignment 1","issue":"Đề gọi CRUD nhưng không yêu cầu chức năng xóa.","revision":"Bám yêu cầu gốc: ghi đè, bổ sung, đọc, sửa; xóa là mở rộng tùy chọn."},{"source":"Workshop 2","issue":"Bảng thuế minh họa có thể bị hiểu nhầm là chính sách thực tế.","revision":"Ghi rõ tình huống giả định học thuật, không dùng để tính thuế thực tế."},{"source":"Biên tập v2.0 · Slot 03/05/12","issue":"Khả chuyển phép nhân; tên thuật toán không khớp; nhập liệu cắt dòng.","revision":"Đã sửa mã và bổ sung bộ ca kiểm thử phản ví dụ."},{"source":"Biên tập v2.0 · Slot 07/14/15/17/19/20","issue":"Thiếu minh chứng vận dụng cho phần thuật toán chính.","revision":"Bổ sung chương trình chạy độc lập, bài tập mẫu và bảng truy vết mở rộng."},{"source":"Biên tập v2.0 · Trắc nghiệm","issue":"Đáp án cũ tập trung tại một phương án và quá ít câu mỗi bài.","revision":"Bổ sung 63 câu, xáo trộn kiểm soát và cân bằng tổng thể 105 câu."}],"modules":[{"id":"M1","title":"Tư duy thuật toán và tính toán cơ bản","from":0,"to":4,"description":"Nhận diện dữ liệu, biểu diễn yêu cầu và xây dựng chương trình C đầu tiên."},{"id":"M2","title":"Cấu trúc điều khiển và tổ chức chương trình","from":5,"to":9,"description":"Xây dựng cấu trúc rẽ nhánh, lặp và hàm để giải quyết vấn đề có quy tắc."},{"id":"M3","title":"Bộ nhớ, thư viện và nhập dữ liệu an toàn","from":10,"to":12,"description":"Quản lý tài nguyên, kiểm tra đầu vào và xử lý các tình huống không hợp lệ."},{"id":"M4","title":"Mảng, thuật toán xử lý dữ liệu và chuỗi","from":13,"to":18,"description":"Tổ chức dữ liệu đo, tìm kiếm, sắp xếp và xử lý chuỗi trong C."},{"id":"M5","title":"Tệp dữ liệu và bài thực hành tích hợp","from":19,"to":20,"description":"Đọc ghi tệp và triển khai nhiệm vụ tích hợp theo Workshop/Assignment."}]};
